    "/setup.cgi",
    # TP-Link Archer AX21 (CVE-2023-1389) — `country=$(...)`
    "/cgi-bin/luci/;stok=/locale",
    "/cgi-bin/luci/",
    # Tenda / ZTE `/goform/*` handlers
    "/goform/formJsonAjaxReq",
    "/goform/setSysAdm",
    "/goform/goform_get_cmd_process",
