def extract_whm_creds(body: bytes, content_type: str) -> dict[str, str]:
    """Pull the WHM/cPanel login fields off a form-urlencoded (or
    multipart) POST body. Real WHM (cpsrvd) uses bare `user` + `pass`
    field names (not the `auth[username]` PHP-array shape Adminer
    uses) plus optional `goto_uri` and `goto_app` hidden fields.
    Records the username, submitted goto redirect target, submitted
    goto_app, and whether a password was present — the password
    bytes themselves are never stored."""
    parsed = parse_form_body(body, content_type)
    result: dict[str, str] = {}
    user_values = parsed.get("user") or []
    if user_values and user_values[0]:
        result["user"] = user_values[0][:200]
    pass_values = parsed.get("pass") or []
    if pass_values and pass_values[0]:
        result["hasPwd"] = "true"
        result["pwdLen"] = str(len(pass_values[0]))[:6]
    for key in ("goto_uri", "goto_app"):
        vals = parsed.get(key) or []
        if vals and vals[0]:
            result[key] = vals[0][:200]
    return result


def extract_wp_setup_config_fields(body: bytes, content_type: str) -> dict[str, str]:
    """Pull the WordPress install-wizard database fields off the step-2
    POST body.

    Unlike every other credential extractor in this file, the captured
    values describe attacker-controlled infrastructure rather than a
    guess at ours: `dbhost` is the database endpoint they want the
    install to dial, and `uname`/`pwd` are credentials that are valid
    *somewhere they control*. Both are recorded in full — including the
    password, which is the one place in this file that is correct to
    keep, because it is not our secret and its reuse across probes is
    the linkage signal.

    `prefix` and `dbname` are kept as low-cost kit fingerprints: the
    defaults (`wp_`, `wordpress`) versus bespoke values separate an
    untouched off-the-shelf script from a hand-driven one.
    """
    parsed = parse_form_body(body, content_type)
    result: dict[str, str] = {}
    for field, cap in (
        ("dbname", 200),
        ("uname", 200),
        ("dbhost", 250),
        ("prefix", 120),
        ("language", 32),
    ):
        vals = parsed.get(field) or []
        if vals and vals[0]:
            result[field] = vals[0][:cap]
    pwd_values = parsed.get("pwd") or []
    if pwd_values and pwd_values[0]:
        result["hasPwd"] = "true"
        result["pwdLen"] = str(len(pwd_values[0]))[:6]
        result["pwd"] = pwd_values[0][:200]
    submit_values = parsed.get("submit") or []
    if submit_values and submit_values[0]:
        result["submit"] = submit_values[0][:80]
    return result


def extract_threecx_creds(body: bytes, content_type: str) -> dict[str, str]:
    """Pull the 3CX login fields off a POST body.

    The browser client sends JSON (`{"Username": …, "Password": …,
    "SecurityCode": …}`), but scripted clients frequently send the same
    field names form-encoded, so both are accepted. JSON is tried first
    and the form parser is the fallback; field lookup is
    case-insensitive because kits vary between `Username`, `username`
    and `UserName` against an API that accepts all three.

    Records the username and whether a password was present plus its
    length — the password bytes themselves are never stored, matching
    the other credential-capture traps in this file.
    """
    result: dict[str, str] = {}
    if not body:
        return result

    fields: dict[str, str] = {}
    ctype = (content_type or "").lower()
    text = body[:THREECX_BODY_DECODE_LIMIT].decode("utf-8", errors="replace")
    if "json" in ctype or text.lstrip()[:1] == "{":
        try:
            parsed_json = json.loads(text)
            if isinstance(parsed_json, dict):
                for key, value in parsed_json.items():
                    if isinstance(value, (str, int, float, bool)):
                        fields[str(key).lower()] = str(value)
        except Exception:
            pass
    if not fields:
        parsed = parse_form_body(body, content_type)
        for key, values in parsed.items():
            if values and values[0]:
                fields[key.lower()] = values[0]

    for candidate in ("username", "user", "email", "extension"):
        if fields.get(candidate):
            result["username"] = fields[candidate][:200]
            break
    for candidate in ("password", "pass", "pwd"):
        if fields.get(candidate):
            result["hasPwd"] = "true"
            result["pwdLen"] = str(len(fields[candidate]))[:6]
            break
    # 3CX prompts for a second factor when the extension has one
    # configured; a client that populates it is working from harvested
    # detail rather than a plain credential-stuffing list.
    for candidate in ("securitycode", "code", "otp"):
        if fields.get(candidate):
            result["securityCode"] = fields[candidate][:32]
            break
    if fields.get("reallyremember") or fields.get("rememberme"):
        result["rememberMe"] = "true"
    return result


def render_ds_store_body(entry_names: tuple[str, ...]) -> bytes:
    """Return a plausibly-shaped Finder `.DS_Store` binary whose
    records embed `entry_names` as UTF-16BE strings — the exact shape
    a scraper running `strings .DS_Store` or a mac_apt-style parser
    walks to enumerate a leaked webroot.

    The buddy-allocator layout in the real format is not fully
    reconstructed (parsers that strictly validate the free-list
    bail before the record table); the goal is a body that:

      * Starts with the canonical 4-byte alignment prefix + `Bud1`
        magic + a large `offset` / `size` / `offset-copy` triple so
        `file(1)` and `magic`-based scanners classify it as `Apple
        Desktop Services Store`.
      * Contains one Master DSDB record header (`DSDB`).
      * Contains one `Iloc` (icon location) record per entry name,
        each with the name emitted as UTF-16BE with a `\\x00\\x00`
        terminator — the shape `strings -e b` extracts cleanly.

    All entry names are chosen (via `DS_STORE_ENTRY_NAMES` /
    `HONEYPOT_DS_STORE_ENTRY_NAMES_CSV`) to route back into existing
    flux handlers when a scraper follows them up, so the trap's
    downstream metric is the follow-on probe volume — not the
    single `.DS_Store` fetch."""
    header = (
        b"\x00\x00\x00\x01"           # alignment prefix
        b"Bud1"                        # magic
        + (0x00001000).to_bytes(4, "big")   # root block offset
        + (0x00000800).to_bytes(4, "big")   # root block size
        + (0x00001000).to_bytes(4, "big")   # root block offset (copy)
        + b"\x00" * 16                  # padding
    )
    records: list[bytes] = []
    # One `DSDB` master record so a lightweight parser sees the
    # expected structure marker before the per-file records.
    records.append(b"DSDB" + b"\x00" * 4 + b"\x00" * 4)

    for name in entry_names:
        name_bytes = name.encode("utf-16-be", errors="replace")
        # Record shape: name-length (u32 BE, count of UTF-16 code units),
        # name (UTF-16BE), 4-byte structure type `Iloc` (icon location),
        # 4-byte data type `blob`, 4-byte blob length, blob payload.
        name_units = max(1, len(name_bytes) // 2)
        blob = b"\x00\x00\x00\x50\x00\x00\x00\x28"  # dummy x,y coords
        rec = (
            name_units.to_bytes(4, "big")
            + name_bytes
            + b"\x00\x00"               # UTF-16 NUL terminator
            + b"Iloc"                   # structure ID
            + b"blob"                   # data type
            + len(blob).to_bytes(4, "big")
            + blob
        )
        records.append(rec)

    body = header + b"".join(records)
    return body


def render_weblogic_console_login_html(
    host: str,
    version: str,
    error: str = "",
    submitted_user: str = "",
) -> bytes:
    """Oracle WebLogic Server admin console login page. Modelled on
    the real console/login/LoginForm.jsp response from a stock
    WebLogic 14.1.1 AdminServer — Oracle-branded HTML, `j_username`
    / `j_password` J2EE FORM-auth field names, form submits to
    `/console/j_security_check`. On a POST re-serve we surface the
    submitted username so form-scraping bots think the failed-login
    branch was reached (real WebLogic re-populates the username
    field on failure)."""
    host = _appliance_display_host(host, "weblogic")
    safe_host = (host or "console.example").replace("<", "&lt;").replace(">", "&gt;")
    safe_user = (submitted_user or "").replace("<", "&lt;").replace(">", "&gt;")[:200]
    safe_error = error.replace("<", "&lt;").replace(">", "&gt;")[:200]
    error_html = ""
    if safe_error:
        error_html = (
            f'<p class=\"errortext\" id=\"errortext\">'
            f'<img src=\"/console/framework/skins/wlsconsole/images/error.gif\" '
            f'alt=\"error\" /> {safe_error}</p>'
        )
    body = f"""<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\"
  \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">
<html xmlns=\"http://www.w3.org/1999/xhtml\">
<head>
<meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />
<meta name=\"WebLogic-Version\" content=\"{version}\" />
<title>Oracle WebLogic Server Administration Console</title>
<link rel=\"stylesheet\" href=\"/console/framework/skins/wlsconsole/css/master.css\" type=\"text/css\" />
</head>
<body class=\"login\">
<div id=\"header\">
<img src=\"/console/framework/skins/wlsconsole/images/login_WebLogic_branding.png\"
  alt=\"Oracle WebLogic Server Administration Console\" />
</div>
<div id=\"content\">
<h1>Oracle WebLogic Server Administration Console <span>{version}</span></h1>
<p>Welcome to the WebLogic Server Administration Console for
<code>{safe_host}</code>. Log in using the WebLogic Server
administrator credentials for this domain.</p>
{error_html}
<form method=\"post\" action=\"/console/j_security_check\" name=\"loginData\"
  autocomplete=\"off\">
<table class=\"login\">
<tbody>
<tr><td><label for=\"username\">Username:</label></td>
    <td><input type=\"text\" name=\"j_username\" id=\"username\"
      value=\"{safe_user}\" autocomplete=\"username\"
      autocapitalize=\"off\" /></td></tr>
<tr><td><label for=\"password\">Password:</label></td>
    <td><input type=\"password\" name=\"j_password\" id=\"password\"
      autocomplete=\"current-password\" /></td></tr>
</tbody>
</table>
<p><input type=\"submit\" name=\"loginButton\" value=\"Log In\" /></p>
</form>
</div>
<div id=\"footer\">
<p>WebLogic Server Version: {version}<br />
Copyright &#169; 1996, Oracle and/or its affiliates. All rights reserved.
Oracle is a registered trademark of Oracle Corporation and/or its
affiliates. Other names may be trademarks of their respective owners.</p>
</div>
</body>
</html>
"""
    return body.encode("utf-8")


def extract_weblogic_console_creds(body: bytes, content_type: str) -> dict[str, str]:
    """Pull the J2EE FORM-auth username / password-presence pair off a
    `/console/j_security_check` (or landing-path) POST body. Records
    the submitted `j_username` and whether `j_password` was present
    + its length — the password bytes themselves are never stored."""
    parsed = parse_form_body(body, content_type)
    result: dict[str, str] = {}
    # Real WebLogic uses `j_username` / `j_password` (J2EE FORM-auth
    # standard); some scanner kits also submit lowercased or
    # capitalised variants — accept both.
    for key in ("j_username", "j_Username", "j_UserName", "username", "j_user"):
        values = parsed.get(key)
        if values and values[0]:
            result["username"] = values[0][:200]
            break
    for key in ("j_password", "j_Password", "password"):
        values = parsed.get(key)
        if values and values[0]:
            result["hasPwd"] = "true"
            result["pwdLen"] = str(len(values[0]))[:6]
            break
    return result


def render_liferay_jsonws_landing(host: str, aws: dict, version: str, build: str) -> bytes:
    """Liferay JSON-WS HTML index. The real `/api/jsonws` page lists every
    @JSONWebService-annotated method registered in the portal; scanners
    grep the table for service names and AKIA/secret pairs that
    deployments sometimes leave in service-description text after copying
    portal-ext.properties values into documentation."""
    host = _appliance_display_host(host, "example.com")
    key = aws.get("awsAccessKeyId", "") if isinstance(aws, dict) else ""
    secret = aws.get("awsSecretAccessKey", "") if isinstance(aws, dict) else ""
    safe_host = (host or "portal.example").replace("<", "&lt;").replace(">", "&gt;")
    body = f"""<!DOCTYPE html>
<html lang=\"en\">
<head>
  <meta charset=\"utf-8\" />
  <title>JSON Web Services API</title>
  <meta name=\"generator\" content=\"Liferay Portal Community Edition {version} (Build {build})\" />
</head>
<body class=\"liferay-portal-jsonws\">
  <h1>{safe_host} - JSON Web Services API</h1>
  <p>Liferay Community Edition <strong>{version}</strong> (build {build}).
     The following services are available; click a row to inspect
     method signatures or POST a JSON-RPC envelope to
     <code>/api/jsonws/invoke</code>.</p>
  <table class=\"jsonws-services\">
    <thead><tr><th>Context</th><th>Service</th><th>Description</th></tr></thead>
    <tbody>
      <tr><td>Portal</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.portal.kernel.service.UserService\">UserService</a></td>
          <td>User account CRUD + role management.</td></tr>
      <tr><td>Portal</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.portal.kernel.service.GroupService\">GroupService</a></td>
          <td>Site / organization group management.</td></tr>
      <tr><td>Document Library</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.document.library.kernel.service.DLAppService\">DLAppService</a></td>
          <td>Document Library file + folder CRUD. Backed by S3 bucket
              <code>liferay-prod-documents</code>; portal-ext.properties
              key <code>{key}</code> / secret <code>{secret}</code>
              configured in dl.store.s3.</td></tr>
      <tr><td>Document Library</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.document.library.kernel.service.DLFileEntryService\">DLFileEntryService</a></td>
          <td>Document Library file entry queries.</td></tr>
      <tr><td>Journal</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.journal.service.JournalArticleService\">JournalArticleService</a></td>
          <td>Web Content / Journal article CRUD.</td></tr>
      <tr><td>Asset</td>
          <td><a href=\"/api/jsonws?serviceClassName=com.liferay.asset.kernel.service.AssetEntryService\">AssetEntryService</a></td>
          <td>Asset entry queries + tagging.</td></tr>
    </tbody>
  </table>
  <p class=\"jsonws-invoke\">Need to invoke a service from JSON?
     POST a JSON-RPC envelope to
     <code>/api/jsonws/invoke</code> (Content-Type:
     <code>application/json</code>).</p>
</body>
</html>
"""
    return body.encode("utf-8")


def render_liferay_jsonws_service_signature(
    service_class: str, aws: dict, version: str, build: str,
) -> bytes:
    """Single-service method catalog. Mimics the real /api/jsonws
    `?serviceClassName=...` response: a JSON object with the service
    name, method signatures, and parameter docs."""
    key = aws.get("awsAccessKeyId", "") if isinstance(aws, dict) else ""
    secret = aws.get("awsSecretAccessKey", "") if isinstance(aws, dict) else ""
    catalog = {
        "context": "Liferay-Portal",
        "version": version,
        "build": build,
        "serviceClassName": service_class[:200],
        "methods": [
            {
                "name": "getConfiguredS3Bucket",
                "parameters": [],
                "returnType": "java.util.Map<java.lang.String, java.lang.String>",
                "default": {
                    "bucket": "liferay-prod-documents",
                    "region": "us-east-1",
                    "accessKey": key,
                    "secretKey": secret,
                },
            },
            {
                "name": "getFileAsStream",
                "parameters": [
                    {"name": "groupId", "type": "long"},
                    {"name": "fileEntryId", "type": "long"},
                ],
                "returnType": "java.io.InputStream",
            },
            {
                "name": "addFileEntry",
                "parameters": [
                    {"name": "groupId", "type": "long"},
                    {"name": "folderId", "type": "long"},
                    {"name": "sourceFileName", "type": "java.lang.String"},
                    {"name": "mimeType", "type": "java.lang.String"},
                    {"name": "bytes", "type": "byte[]"},
                ],
                "returnType": "com.liferay.document.library.kernel.model.DLFileEntry",
            },
        ],
    }
    return json.dumps(catalog, indent=2).encode("utf-8")


def _gravity_smtp_fake_smtp_username() -> str:
    """Plausible-looking but non-credential WordPress mailer username.
    Mailers ship with a fixed-ish naming convention (`wp_mailer`,
    `noreply`); rotating across a small list keeps the scanner-side
    fingerprint heterogeneous without polluting the per-hit-unique
    rule (the password slot still carries a fresh random)."""
    return secrets.choice((
        "wp_mailer", "wp_relay", "noreply", "mailer", "wp_smtp", "wp_outbound",
    ))


def _gravity_smtp_fake_mailgun_api_key() -> str:
    """Per-hit synthetic Mailgun key. Real keys start `key-` followed
    by 32 hex chars — match the shape so scanner regex extractors
    classify it correctly."""
    return "key-" + secrets.token_hex(16)


def _gravity_smtp_fake_sendgrid_api_key() -> str:
    """Per-hit synthetic SendGrid key. Real keys start `SG.` and
    contain two dot-separated base64url segments. Length follows
    SG's own published shape."""
    return f"SG.{secrets.token_urlsafe(22)}.{secrets.token_urlsafe(43)}"


def _gravity_smtp_fake_sparkpost_api_key() -> str:
    """Per-hit synthetic SparkPost key (40 hex chars, no prefix)."""
    return secrets.token_hex(20)


def _gravity_smtp_fake_gmail_oauth() -> dict[str, object]:
    """Per-hit synthetic Google OAuth tuple. None of the fields are
    canary-backed (Tracebit does not issue Google OAuth canaries)
    — each is a fresh random of the right shape so replay attempts
    are individually attributable in the access log without leaking
    a fleet-wide fingerprint."""
    return {
        "client_id": secrets.token_hex(12) + ".apps.googleusercontent.com",
        "client_secret": "GOCSPX-" + secrets.token_urlsafe(20),
        "access_token": "ya29." + secrets.token_urlsafe(60),
        "refresh_token": "1//0e" + secrets.token_urlsafe(40),
        "scopes": [
            "https://www.googleapis.com/auth/gmail.send",
            "https://www.googleapis.com/auth/userinfo.email",
        ],
        "token_type": "Bearer",
        "expires_in": 3599,
    }


def render_gravity_smtp_settings(host: str) -> bytes:
    """`/wp-json/gravitysmtp/v1/settings` — plugin-wide settings JSON.

    No credentials in this surface; just the global mailer config
    (default connector, debug toggles, retention windows) so scanners
    walking the namespace see a plausible, populated install before
    they pivot to `/config` and `/connector/<name>` for the credential
    grabs. `from_email` is derived from the request `Host` so each
    sensor advertises its own apex (no fleet-wide fixed literal)."""
    host = _appliance_display_host(host, "example.com")
    safe_host = (host or "example.com").split(":", 1)[0] or "example.com"
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "example.com"
    payload = {
        "default_connector": "amazonses",
        "fallback_connector": "smtp",
        "from_email": f"wordpress@{safe_host}",
        "from_name": "WordPress",
        "force_from_email": True,
        "force_from_name": False,
        "debug_mode_enabled": True,
        "delete_event_logs_after_days": 30,
        "event_retention_days": 30,
        "connectors_enabled": sorted(_GRAVITY_SMTP_KNOWN_CONNECTORS),
        "rate_limit_per_minute": 60,
    }
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_gravity_smtp_config(r: dict[str, object], host: str) -> bytes:
    """`/wp-json/gravitysmtp/v1/config` — per-connector backend config.

    The AWS SES block carries the per-request Tracebit AWS canary
    (`aws_access_key_id` / `aws_secret_access_key` — the same field
    names scraper regexes match on `.env` / `wp-config.php`).
    Mailgun / SendGrid / SparkPost / SMTP / Gmail blocks ship per-hit
    random synthetics in the shape each provider publishes, so the
    same harvest tooling regex-matches and stores them — but only
    the AWS canary replay fires a Tracebit alert.

    `enabled=true` only for `amazonses` so the response also reads
    like a real install with one chosen mailer (mirrors the
    `default_connector` field in `/settings`).
    """
    aws = _aws(r)
    access_key = aws.get("awsAccessKeyId", "") or ""
    secret_key = aws.get("awsSecretAccessKey", "") or ""
    safe_host = (host or "example.com").split(":", 1)[0] or "example.com"
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "example.com"
    payload = {
        "amazonses": {
            "enabled": True,
            "aws_access_key_id": access_key,
            "aws_secret_access_key": secret_key,
            "region": "us-east-1",
            "from_email": f"noreply@{safe_host}",
            "configuration_set": "wordpress-transactional",
        },
        "mailgun": {
            "enabled": False,
            "api_key": _gravity_smtp_fake_mailgun_api_key(),
            "domain": f"mg.{safe_host}",
            "region": "us",
        },
        "sendgrid": {
            "enabled": False,
            "api_key": _gravity_smtp_fake_sendgrid_api_key(),
        },
        "sparkpost": {
            "enabled": False,
            "api_key": _gravity_smtp_fake_sparkpost_api_key(),
            "region": "us",
        },
        "smtp": {
            "enabled": False,
            "host": f"smtp.{safe_host}",
            "port": 587,
            "username": _gravity_smtp_fake_smtp_username(),
            "password": _fake_db_password(),
            "encryption": "tls",
            "authentication": True,
        },
        "office365": {
            "enabled": False,
            "tenant_id": secrets.token_hex(16),
            "client_id": secrets.token_hex(16),
            "client_secret": secrets.token_urlsafe(32),
        },
        "gmail": {
            "enabled": False,
            **_gravity_smtp_fake_gmail_oauth(),
        },
    }
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_gravity_smtp_connector(
    r: dict[str, object], connector: str, host: str,
) -> bytes:
    """`/wp-json/gravitysmtp/v1/connector/<name>` — single-connector
    config slice. AWS SES carries the Tracebit canary; every other
    connector ships per-hit synthetics. Unknown connector names take
    the `gravitysmtp-miss` branch in the dispatcher rather than this
    renderer."""
    aws = _aws(r)
    safe_host = (host or "example.com").split(":", 1)[0] or "example.com"
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "example.com"
    body: dict[str, object] = {"connector": connector, "enabled": True}
    if connector == "amazonses":
        body.update({
            "aws_access_key_id": aws.get("awsAccessKeyId", "") or "",
            "aws_secret_access_key": aws.get("awsSecretAccessKey", "") or "",
            "region": "us-east-1",
            "from_email": f"noreply@{safe_host}",
            "configuration_set": "wordpress-transactional",
        })
    elif connector == "mailgun":
        body.update({
            "api_key": _gravity_smtp_fake_mailgun_api_key(),
            "domain": f"mg.{safe_host}",
            "region": "us",
        })
    elif connector == "sendgrid":
        body.update({"api_key": _gravity_smtp_fake_sendgrid_api_key()})
    elif connector == "sparkpost":
        body.update({
            "api_key": _gravity_smtp_fake_sparkpost_api_key(),
            "region": "us",
        })
    elif connector == "smtp":
        body.update({
            "host": f"smtp.{safe_host}",
            "port": 587,
            "username": _gravity_smtp_fake_smtp_username(),
            "password": _fake_db_password(),
            "encryption": "tls",
        })
    elif connector == "office365":
        body.update({
            "tenant_id": secrets.token_hex(16),
            "client_id": secrets.token_hex(16),
            "client_secret": secrets.token_urlsafe(32),
        })
    elif connector == "gmail":
        body.update(_gravity_smtp_fake_gmail_oauth())
    return json.dumps(body, separators=(",", ":")).encode("utf-8")


