def render_gitconfig() -> bytes:
    """User-level `~/.gitconfig`. Carries a per-hit synthetic
    `Authorization: Bearer ghp_<random>` in the `[http "..."] extraheader`
    slot — a real-looking GitHub token shape (`ghp_` prefix, 40 chars)
    that harvesters grep for. NOT a Tracebit canary; per-hit unique so
    a fleet-wide replay still shows up as N different tokens rather than
    one fixed literal. The `[credential] helper = store` line is the
    chain the scanner follows next (to `/.git-credentials`)."""
    fake_token = "ghp_" + secrets.token_urlsafe(32)[:36]
    fake_email = f"deploy+{secrets.token_hex(4)}@internal-tools.lan"
    return (
        "[user]\n"
        f"\temail = {fake_email}\n"
        "\tname = Deploy Bot\n"
        "[credential]\n"
        "\thelper = store\n"
        "[credential \"https://github.com\"]\n"
        "\tusername = deploy-bot\n"
        "[http \"https://github.com/\"]\n"
        f"\textraheader = Authorization: Bearer {fake_token}\n"
        "[core]\n"
        "\tautocrlf = input\n"
        "\teditor = vim\n"
        "[pull]\n"
        "\trebase = true\n"
        "[init]\n"
        "\tdefaultBranch = main\n"
    ).encode("utf-8")


def render_gitignore() -> bytes:
    """Project `.gitignore`. Pure deception — listing typical Node +
    Python + Terraform + secret-file patterns convinces a scanner that
    the webroot is a checked-out git tree, which keeps it walking the
    fake-git surface next. Also: some scanners walk every entry in
    `.gitignore` as a target dictionary (`*.pem`, `.env`, ...), so the
    listing doubles as a hint sheet that lands those probes on existing
    canary traps (`.env.*`, `.aws/credentials`, `service-account.json`)."""
    return (
        "# git ls-files --others --exclude-from=.gitignore\n"
        "node_modules/\n"
        ".next/\n"
        ".cache/\n"
        "dist/\n"
        "build/\n"
        "coverage/\n"
        "*.log\n"
        "npm-debug.log*\n"
        "yarn-debug.log*\n"
        ".DS_Store\n"
        "Thumbs.db\n"
        "\n"
        "# env / secrets\n"
        ".env\n"
        ".env.*\n"
        "!.env.example\n"
        "*.pem\n"
        "*.key\n"
        ".aws/credentials\n"
        "credentials.json\n"
        "service-account.json\n"
        "\n"
        "# python\n"
        "__pycache__/\n"
        "*.pyc\n"
        ".venv/\n"
        ".pytest_cache/\n"
        "\n"
        "# terraform\n"
        "*.tfstate\n"
        "*.tfstate.backup\n"
        ".terraform/\n"
    ).encode("utf-8")


def extract_wp_login_creds(body: bytes, content_type: str) -> dict[str, str]:
    parsed = parse_form_body(body, content_type)
    result: dict[str, str] = {}
    for key in ("log", "pwd", "wp-submit", "redirect_to", "testcookie", "_wpnonce", "rememberme"):
        values = parsed.get(key)
        if values and values[0]:
            if key == "pwd":
                result["hasPwd"] = "true"
            else:
                result[key] = values[0][:200]
    return result


# --- WordPress user-enum renderers ----------------------------------------
# Three response shapes match the three observed enumeration surfaces:
#   - JSON array for `/wp-json/wp/v2/users`
#   - Sitemap XML for `/wp-sitemap-users-N.xml`
#   - Yoast/RankMath author-sitemap variant
# A single fake user object renderer is shared between the array and
# indexed-id REST handlers so the shape is identical.

_EXTERNAL_HOST_FALLBACK = "example.com"

# The site's own public hostname, for the case below where the request
# cannot supply one. `HONEYPOT_SITE_HOST` is the explicit setting;
# `SENSOR_PRIMARY_DOMAIN` is read as a fallback because a deployment
# that terminates TLS for a known name already has it in the
# environment, and requiring it to be restated would leave the common
# case unconfigured.
#
# Preferring this over the request host would be *more* faithful to
# WordPress, which serves its stored `siteurl` regardless of which alias
# was used to reach it. It is deliberately second anyway: an
# externally-plausible request host is the one the client actually
# chose, and existing traps are documented as pointing back at it.
SITE_HOST = (
    os.environ.get("HONEYPOT_SITE_HOST")
    or os.environ.get("SENSOR_PRIMARY_DOMAIN")
    or ""
).strip().lower()


def _host_is_externally_plausible(h: str) -> bool:
    """Whether `h` can appear in a link a client is expected to follow.

    Rejects what a reverse proxy substitutes for a real name — address
    literals and loopback — plus anything unroutable off-box or
    syntactically unusable in a URL."""
    if not h or any(c in h for c in (" ", "\n", "\r", '"', "<", ">", "/")):
        return False
    if h in ("localhost", "localhost.localdomain") or h.endswith(".local"):
        return False
    # Address literals: IPv6 (bracketed or colon-bearing) and dotted quads.
    if h.startswith("[") or ":" in h:
        return False
    labels = h.split(".")
    return len(labels) >= 2 and not all(label.isdigit() for label in labels)


def _appliance_display_host(host: str, fallback: str) -> str:
    """The hostname an appliance page may print as its own name.

    Every vendor portal here renders the requested host into its title
    and page furniture, guarded by `host or "<vendor default>"`. That
    guard only fires on an *empty* host — and the value that actually
    arrives behind a reverse proxy which rewrites `Host` is not empty,
    it is `127.0.0.1`. So the pages shipped
    `<title>… - 127.0.0.1</title>`: not a name any appliance would
    print, and identical from every host running this software, which
    makes it a fleet fingerprint rather than a cosmetic slip. Found by
    probing a deployment — unit tests pass a hostname straight into the
    renderer, so they cannot see it. Same way the OIDC issuer defect was
    found, and the same defect.

    Same test and fallback order as `_external_base_url`, minus the URL
    scheme: the requested host when it could be a real external name,
    else the configured site host, else the vendor placeholder the
    caller supplied.
    """
    h = (host or "").strip().lower().split(":", 1)[0]
    if _host_is_externally_plausible(h):
        return h
    if _host_is_externally_plausible(SITE_HOST):
        return SITE_HOST
    return fallback


def _external_base_url(host: str) -> str:
    """Construct an `https://<host>` base URL for the absolute links any
    surface embeds — the WordPress author archives and REST `_links`
    self hrefs, the OIDC issuer and every endpoint the discovery
    document advertises.

    The host has to look like an externally-reachable name before it is
    used. Where a reverse proxy in front of this server rewrites `Host`
    (and `X-Forwarded-Host` with it) to its upstream address, what
    arrives is a loopback literal — and building links out of that is
    worse than the 404 they replaced: every URL the document advertises
    points the client at its own machine, so the discovery chain these
    surfaces exist to start dead-ends on the first follow. It is also a
    fleet-wide constant, identical from every host behind such a proxy.

    Same reasoning, and the same test, as `_plausible_deploy_host`.

    Every renderer that publishes an absolute URL has to call this. The
    OIDC discovery document did not, and shipped
    `issuer: https://127.0.0.1` with all nine of its endpoints under it
    for as long as it existed — the same defect this helper was written
    for, in a second family, found by probing a deployment rather than
    by reading the code. Unit tests pass a hostname straight into the
    renderer, so they cannot see it.

    When the request cannot supply a usable name, `SITE_HOST` does —
    which is what makes the links followable rather than merely safe.
    The last resort is an IANA reserved-for-documentation name: it
    cannot be mistaken for a real target, and it cannot point a scanner
    at somebody else's domain, which an invented plausible one could.
    """
    h = (host or "").strip().lower().split(":", 1)[0]
    if _host_is_externally_plausible(h):
        return f"https://{h}"
    if _host_is_externally_plausible(SITE_HOST):
        return f"https://{SITE_HOST}"
    return f"https://{_EXTERNAL_HOST_FALLBACK}"


def _wp_user_enum_fake_user(slot: dict[str, str], host_url: str) -> dict[str, object]:
    """Build a single WP REST user object matching wp-json/wp/v2/users
    shape exactly. avatar_urls are pointed at Gravatar with a
    placeholder hash — the same shape WP serves for any user that has
    not configured an avatar."""
    slug = slot["slug"]
    # Deterministic 32-hex placeholder so the URL is well-formed; this
    # is not a credential and not sensor-specific (per design principle).
    avatar_hash = hashlib.md5(slug.encode("utf-8")).hexdigest()
    avatar_base = f"https://secure.gravatar.com/avatar/{avatar_hash}"
    return {
        "id": int(slot["id"]),
        "name": slot["name"],
        "url": "",
        "description": "",
        "link": f"{host_url}/author/{slug}/",
        "slug": slug,
        "avatar_urls": {
            "24": f"{avatar_base}?s=24&d=mm&r=g",
            "48": f"{avatar_base}?s=48&d=mm&r=g",
            "96": f"{avatar_base}?s=96&d=mm&r=g",
        },
        "meta": [],
        "_links": {
            "self": [{"href": f"{host_url}/wp-json/wp/v2/users/{slot['id']}"}],
            "collection": [{"href": f"{host_url}/wp-json/wp/v2/users"}],
        },
    }


def render_wp_user_enum_rest_list(host: str) -> bytes:
    """`/wp-json/wp/v2/users` — JSON array of every fake user."""
    base = _external_base_url(host)
    users = [_wp_user_enum_fake_user(slot, base) for slot in _WP_USER_ENUM_FAKE_USERS]
    return json.dumps(users, separators=(",", ":")).encode("utf-8")


def render_wp_user_enum_rest_single(host: str, user_id: int) -> bytes:
    """`/wp-json/wp/v2/users/<id>` — single user object, or a 404-shape
    error JSON when the id is out of range. Real WP returns a
    `rest_user_invalid_id` payload for unknown ids; we mirror that so a
    scanner walking ids `1..50` sees the expected envelope and stops at
    the first miss, instead of hammering until rate-limited."""
    base = _external_base_url(host)
    for slot in _WP_USER_ENUM_FAKE_USERS:
        if int(slot["id"]) == user_id:
            return json.dumps(
                _wp_user_enum_fake_user(slot, base),
                separators=(",", ":"),
            ).encode("utf-8")
    # WordPress's stock not-found envelope:
    body = {
        "code": "rest_user_invalid_id",
        "message": "Invalid user ID.",
        "data": {"status": 404},
    }
    return json.dumps(body, separators=(",", ":")).encode("utf-8")


def render_wp_user_enum_sitemap_xml(host: str) -> bytes:
    """`/wp-sitemap-users-N.xml` — WordPress 5.5+ core sitemap shape.
    Includes the XSL stylesheet PI that real WP emits so curl/wget
    captures + browser views both look authentic."""
    base = _external_base_url(host)
    lines = [
        b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
        f"<?xml-stylesheet type=\"text/xsl\" href=\"{base}/wp-sitemap.xsl\" ?>".encode("utf-8"),
        b"<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\" "
        b"xmlns:xhtml=\"http://www.w3.org/1999/xhtml\">",
    ]
    for slot in _WP_USER_ENUM_FAKE_USERS:
        loc = f"{base}/author/{slot['slug']}/"
        lines.append(b"<url><loc>" + loc.encode("utf-8") + b"</loc></url>")
    lines.append(b"</urlset>")
    return b"\n".join(lines)


def render_wp_user_enum_yoast_xml(host: str) -> bytes:
    """`/author-sitemap.xml` — Yoast SEO author sitemap. Same shape as
    the core sitemap but with the Yoast XSL stylesheet."""
    base = _external_base_url(host)
    lines = [
        b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
        f"<?xml-stylesheet type=\"text/xsl\" href=\"{base}/main-sitemap.xsl\" ?>".encode("utf-8"),
        b"<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\" "
        b"xmlns:image=\"http://www.google.com/schemas/sitemap-image/1.1\">",
    ]
    for slot in _WP_USER_ENUM_FAKE_USERS:
        loc = f"{base}/author/{slot['slug']}/"
        lines.append(
            b"<url><loc>" + loc.encode("utf-8") + b"</loc>"
            b"<lastmod>2026-01-01T00:00:00+00:00</lastmod></url>"
        )
    lines.append(b"</urlset>")
    return b"\n".join(lines)


# --- WordPress REST index renderers ---------------------------------------

def _wp_rest_site_name(host: str) -> str:
    """Derive a plausible site title from the request Host so the index
    is not the same document on every sensor. `shop.example.co.uk` ->
    `Shop`. Falls back to a generic title when the Host is unusable."""
    h = _external_base_url(host)
    label = h.split("://", 1)[-1].split(".", 1)[0]
    label = re.sub(r"[^A-Za-z0-9-]", "", label).replace("-", " ").strip()
    return label.title() if label else "My Site"


def _wp_rest_route_entry(
    base: str, route: str, methods: tuple[str, ...],
) -> dict[str, object]:
    """One `routes` map value in WordPress's index shape. The self link
    is what a client follows, so it is always the canonical
    `/wp-json/<route>` spelling of a route this server answers."""
    namespace = "" if route == "/" else _WP_REST_NAMESPACE
    if route.startswith("/batch/"):
        namespace = "batch/v1"
    return {
        "namespace": namespace,
        "methods": list(methods),
        "endpoints": [{"methods": list(methods), "args": {}}],
        "_links": {"self": [{"href": f"{base}/wp-json{'' if route == '/' else route}"}]},
    }


def _wp_rest_advertised_routes() -> tuple[tuple[str, tuple[str, ...]], ...]:
    """Every route the index advertises, in WordPress's own ordering.

    This is the single source of truth the index renderer and the
    dispatcher both read, so an advertised route cannot drift away from
    a served one — the failure mode this trap exists to fix."""
    routes: list[tuple[str, tuple[str, ...]]] = [
        ("/", ("GET",)),
        (f"/{_WP_REST_NAMESPACE}", ("GET",)),
    ]
    for name in _WP_REST_COLLECTIONS:
        routes.append((f"/{_WP_REST_NAMESPACE}/{name}", ("GET", "POST")))
    for name in _WP_REST_DESCRIPTORS:
        routes.append((f"/{_WP_REST_NAMESPACE}/{name}", ("GET",)))
    routes.append((f"/{_WP_REST_NAMESPACE}/search", ("GET",)))
    for name in _WP_REST_AUTH_REQUIRED:
        routes.append((f"/{_WP_REST_NAMESPACE}/{name}", ("GET",)))
    routes.append(("/batch/v1", ("POST",)))
    return tuple(routes)


def render_wp_rest_index(host: str) -> bytes:
    """`/wp-json/` — the REST discovery document.

    Shaped like WordPress core's index: site identity, the registered
    namespaces, and a `routes` map whose self links are the addresses a
    client is expected to follow next. Only routes this server answers
    are listed."""
    base = _external_base_url(host)
    routes = {
        route: _wp_rest_route_entry(base, route, methods)
        for route, methods in _wp_rest_advertised_routes()
    }
    doc = {
        "name": _wp_rest_site_name(host),
        "description": "Just another WordPress site",
        "url": f"{base}/",
        "home": f"{base}/",
        "gmt_offset": 0,
        "timezone_string": "",
        "namespaces": ["oembed/1.0", "batch/v1", _WP_REST_NAMESPACE],
        "authentication": {},
        "routes": routes,
        "site_logo": 0,
        "site_icon": 0,
        "site_icon_url": "",
        "_links": {"help": [{"href": "https://developer.wordpress.org/rest-api/"}]},
    }
    return json.dumps(doc, separators=(",", ":")).encode("utf-8")


def render_wp_rest_namespace_index(host: str) -> bytes:
    """`/wp-json/wp/v2` — the namespace index. Same document shape as
    the root index, filtered to one namespace, which is exactly what
    WordPress returns for a namespace request."""
    base = _external_base_url(host)
    prefix = f"/{_WP_REST_NAMESPACE}"
    routes = {
        route: _wp_rest_route_entry(base, route, methods)
        for route, methods in _wp_rest_advertised_routes()
        if route == prefix or route.startswith(prefix + "/")
    }
    doc = {
        "namespace": _WP_REST_NAMESPACE,
        "methods": ["GET"],
        "endpoints": [{"methods": ["GET"], "args": {}}],
        "routes": routes,
        "_links": {"up": [{"href": f"{base}/wp-json/"}]},
    }
    return json.dumps(doc, separators=(",", ":")).encode("utf-8")


def _wp_rest_rendered(text: str) -> dict[str, object]:
    return {"rendered": text, "protected": False}


def _wp_rest_post_object(
    base: str, slot: dict[str, str], kind: str,
) -> dict[str, object]:
    """A `wp/v2/posts` or `wp/v2/pages` item. Content is ordinary site
    copy — no credential-shaped field appears anywhere in it."""
    rest_base = "posts" if kind == "post" else "pages"
    link_path = f"{base}/{slot['slug']}/" if kind == "page" else f"{base}/2026/{slot['slug']}/"
    obj: dict[str, object] = {
        "id": int(slot["id"]),
        "date": slot["date"],
        "date_gmt": slot["date"],
        "guid": {"rendered": f"{base}/?p={slot['id']}"},
        "modified": slot["date"],
        "modified_gmt": slot["date"],
        "slug": slot["slug"],
        "status": "publish",
        "type": kind,
        "link": link_path,
        "title": {"rendered": slot["title"]},
        "content": {"rendered": f"<p>{slot['excerpt']}</p>", "protected": False},
        "excerpt": _wp_rest_rendered(f"<p>{slot['excerpt']}</p>"),
        "author": int(slot["author"]),
        "featured_media": 0,
        "comment_status": "open" if kind == "post" else "closed",
        "ping_status": "open" if kind == "post" else "closed",
        "template": "",
        "meta": [],
        "_links": {
            "self": [{"href": f"{base}/wp-json/wp/v2/{rest_base}/{slot['id']}"}],
            "collection": [{"href": f"{base}/wp-json/wp/v2/{rest_base}"}],
            "author": [{"href": f"{base}/wp-json/wp/v2/users/{slot['author']}"}],
        },
    }
    if kind == "post":
        obj["sticky"] = False
        obj["format"] = "standard"
        obj["categories"] = [1]
        obj["tags"] = []
    else:
        obj["parent"] = 0
        obj["menu_order"] = 0
    return obj


def render_wp_rest_collection(host: str, name: str) -> bytes:
    """A `wp/v2/<collection>` listing. Empty collections return `[]`,
    which is what a real small install returns — an error envelope
    would be the lie."""
    base = _external_base_url(host)
    if name == "posts":
        items: list[object] = [
            _wp_rest_post_object(base, s, "post") for s in _WP_REST_FAKE_POSTS
        ]
    elif name == "pages":
        items = [_wp_rest_post_object(base, s, "page") for s in _WP_REST_FAKE_PAGES]
    elif name == "categories":
        items = [{
            "id": 1, "count": len(_WP_REST_FAKE_POSTS), "description": "",
            "link": f"{base}/category/uncategorized/", "name": "Uncategorized",
            "slug": "uncategorized", "taxonomy": "category", "parent": 0, "meta": [],
            "_links": {
                "self": [{"href": f"{base}/wp-json/wp/v2/categories/1"}],
                "collection": [{"href": f"{base}/wp-json/wp/v2/categories"}],
            },
        }]
    else:
        items = []
    return json.dumps(items, separators=(",", ":")).encode("utf-8")


def render_wp_rest_single(host: str, name: str, item_id: int) -> tuple[bytes, int]:
    """A `wp/v2/<collection>/<id>` item, or WordPress's own not-found
    envelope. Returns `(body, status)`.

    Answering the miss correctly is the point: a scanner walking ids
    reads `rest_post_invalid_id` as 'REST is live, that id is not', and
    a bare 404 page as 'REST is off'. The two produce different next
    requests."""
    base = _external_base_url(host)
    slots = _WP_REST_FAKE_POSTS if name == "posts" else (
        _WP_REST_FAKE_PAGES if name == "pages" else ()
    )
    kind = "post" if name == "posts" else "page"
    for slot in slots:
        if int(slot["id"]) == item_id:
            return (
                json.dumps(
                    _wp_rest_post_object(base, slot, kind), separators=(",", ":"),
                ).encode("utf-8"),
                200,
            )
    code = {
        "posts": "rest_post_invalid_id",
        "pages": "rest_post_invalid_id",
        "media": "rest_post_invalid_id",
        "categories": "rest_term_invalid",
        "tags": "rest_term_invalid",
        "comments": "rest_comment_invalid_id",
    }.get(name, "rest_post_invalid_id")
    message = "Invalid term ID." if code == "rest_term_invalid" else (
        "Invalid comment ID." if code == "rest_comment_invalid_id" else "Invalid post ID."
    )
    body = {"code": code, "message": message, "data": {"status": 404}}
    return json.dumps(body, separators=(",", ":")).encode("utf-8"), 404


def render_wp_rest_descriptor(host: str, name: str) -> bytes:
    """`types` / `taxonomies` / `statuses` — the read-only descriptor
    objects a fingerprinting client reads to confirm the install."""
    base = _external_base_url(host)
    if name == "types":
        doc: dict[str, object] = {
            key: {
                "description": "",
                "hierarchical": key == "page",
                "name": label,
                "slug": key,
                "taxonomies": ["category", "post_tag"] if key == "post" else [],
                "rest_base": rest_base,
                "rest_namespace": _WP_REST_NAMESPACE,
                "_links": {
                    "collection": [{"href": f"{base}/wp-json/wp/v2/{rest_base}"}],
                },
            }
            for key, label, rest_base in (
                ("post", "Posts", "posts"),
                ("page", "Pages", "pages"),
                ("attachment", "Media", "media"),
            )
        }
    elif name == "taxonomies":
        doc = {
            key: {
                "name": label, "slug": key, "hierarchical": key == "category",
                "rest_base": rest_base, "rest_namespace": _WP_REST_NAMESPACE,
                "types": ["post"],
                "_links": {
                    "collection": [{"href": f"{base}/wp-json/wp/v2/{rest_base}"}],
                },
            }
            for key, label, rest_base in (
                ("category", "Categories", "categories"),
                ("post_tag", "Tags", "tags"),
            )
        }
    else:  # statuses
        doc = {
            "publish": {
                "name": "Published", "public": True, "queryable": True,
                "slug": "publish", "date_floating": False,
                "_links": {
                    "archives": [{"href": f"{base}/wp-json/wp/v2/posts"}],
                },
            },
        }
    return json.dumps(doc, separators=(",", ":")).encode("utf-8")


def _litellm_virtual_key() -> str:
    """A per-hit virtual key in the proxy's own `sk-` shape. Random, never
    a literal: a fixed one would be the same string on every host and
    would detect nothing if it came back."""
    return "sk-" + secrets.token_urlsafe(24).replace("-", "").replace("_", "")[:32]


def _litellm_token_hash() -> str:
    """Per-hit token hash, the form the proxy stores instead of the key."""
    return secrets.token_hex(32)


def render_litellm_model_info(r: dict[str, object]) -> bytes:
    """`/model/info` — the model registry.

    The registry entry for a managed-cloud model carries the provider
    credential the proxy dials out with. That is the credential worth
    backing with a canary: it belongs to the operator's cloud account
    rather than to the proxy, so a client that takes it and uses it does
    so somewhere a replay is visible. The remaining provider slots take
    per-hit synthetic values in each vendor's published key shape, so the
    registry looks populated without shipping a fixed literal."""
    aws = _aws(r)
    data = [
        {
            "model_name": "gpt-4o",
            "litellm_params": {
                "model": "azure/gpt-4o",
                "api_base": "https://ai-gateway-prod.openai.azure.com/",
                "api_version": "2024-10-21",
                "api_key": "sk-" + secrets.token_urlsafe(28)[:28],
            },
            "model_info": {
                "id": secrets.token_hex(16),
                "mode": "chat",
                "max_tokens": 4096,
                "input_cost_per_token": 2.5e-06,
                "output_cost_per_token": 1e-05,
                "supports_function_calling": True,
            },
        },
        {
            "model_name": "claude-3-5-sonnet",
            "litellm_params": {
                "model": "bedrock/anthropic.claude-3-5-sonnet-20241022-v2:0",
                "aws_region_name": "us-east-1",
                "aws_access_key_id": aws.get("awsAccessKeyId", ""),
                "aws_secret_access_key": aws.get("awsSecretAccessKey", ""),
                "aws_session_token": aws.get("awsSessionToken", ""),
            },
            "model_info": {
                "id": secrets.token_hex(16),
                "mode": "chat",
                "max_tokens": 8192,
                "input_cost_per_token": 3e-06,
                "output_cost_per_token": 1.5e-05,
                "supports_vision": True,
            },
        },
        {
            "model_name": "text-embedding-3-small",
            "litellm_params": {
                "model": "openai/text-embedding-3-small",
                "api_key": "sk-proj-" + secrets.token_urlsafe(36)[:36],
            },
            "model_info": {
                "id": secrets.token_hex(16),
                "mode": "embedding",
                "input_cost_per_token": 2e-08,
            },
        },
    ]
    return json.dumps({"data": data}, separators=(",", ":")).encode("utf-8")


def render_litellm_key_info() -> bytes:
    """`/key/info` — metadata for the key that authenticated the call.
    No key material: the proxy stores a hash, so returning one is what
    the real route does."""
    doc = {
        "key": _litellm_token_hash(),
        "info": {
            "token": _litellm_token_hash(),
            "key_name": "sk-...prod",
            "key_alias": "platform-prod",
            "spend": 418.7231,
            "max_budget": 2000.0,
            "expires": None,
            "models": ["gpt-4o", "claude-3-5-sonnet", "text-embedding-3-small"],
            "tpm_limit": 400000,
            "rpm_limit": 2000,
            "team_id": "platform",
            "user_id": "svc-platform",
            "metadata": {"environment": "production"},
        },
    }
    return json.dumps(doc, separators=(",", ":")).encode("utf-8")


def render_litellm_key_generate(requested_models: list[str]) -> bytes:
    """`POST /key/generate` — mint a virtual key.

    Echoing the requested model list back is what the real route does,
    and it means the log keeps what the caller asked to be able to reach,
    not just that it asked."""
    return json.dumps({
        "key": _litellm_virtual_key(),
        "expires": None,
        "key_name": "sk-...auto",
        "token_id": _litellm_token_hash(),
        "models": requested_models,
        "spend": 0.0,
        "max_budget": None,
        "user_id": "default_user_id",
        "team_id": None,
    }, separators=(",", ":")).encode("utf-8")


def render_litellm_spend_logs() -> bytes:
    """`/global/spend/logs` — recent spend rows. Establishes that the
    proxy is in real use, which is the difference between a target worth
    minting a key on and an empty test deployment. Keys appear as the
    stored hash, never as key material."""
    rows = [
        {
            "request_id": "chatcmpl-" + secrets.token_hex(12),
            "api_key": _litellm_token_hash(),
            "model": model,
            "call_type": "acompletion",
            "spend": spend,
            "total_tokens": tokens,
            "startTime": start,
            "endTime": end,
            "user": user,
            "metadata": {"user_api_key_alias": alias},
        }
        for model, spend, tokens, start, end, user, alias in (
            ("claude-3-5-sonnet", 0.4182, 21_907,
             "2026-08-21T22:14:03", "2026-08-21T22:14:09", "svc-platform", "platform-prod"),
            ("gpt-4o", 0.1937, 8_402,
             "2026-08-21T22:16:41", "2026-08-21T22:16:44", "svc-batch", "batch-jobs"),
            ("text-embedding-3-small", 0.0021, 104_558,
             "2026-08-21T22:19:58", "2026-08-21T22:20:12", "svc-index", "search-index"),
        )
    ]
    return json.dumps(rows, separators=(",", ":")).encode("utf-8")


def render_litellm_auth_error() -> bytes:
    """The proxy's own unauthenticated envelope. Returning it rather than
    a 404 is what tells a client the route exists and is worth a key
    guess — which is the guess we want to record."""
    return json.dumps({
        "error": {
            "message": "Authentication Error, No api key passed in.",
            "type": "auth_error",
            "param": "None",
            "code": "401",
        },
    }, separators=(",", ":")).encode("utf-8")


def render_wp_rest_auth_error(code: str, message: str) -> bytes:
    """WordPress's stock permission envelope. Status 401 accompanies it;
    the envelope is what proves the route is registered."""
    body = {"code": code, "message": message, "data": {"status": 401}}
    return json.dumps(body, separators=(",", ":")).encode("utf-8")


# Multipart Content-Disposition header tokens used by file-upload trap.
# Tokens we care about: name="..." and filename="..." (or unquoted). Match
# is anchored to the raw bytes of a multipart part and is permissive about
# quoting because exploit clients vary.
_MULTIPART_NAME_RE = re.compile(
    rb'(?i)name\s*=\s*(?:"([^"]*)"|([^;\r\n]+))',
)
_MULTIPART_FILENAME_RE = re.compile(
    rb'(?i)filename\s*=\s*(?:"([^"]*)"|([^;\r\n]+))',
)
_MULTIPART_CONTENT_TYPE_RE = re.compile(
    rb'(?im)^\s*Content-Type\s*:\s*([^\r\n;]+)',
)


def extract_multipart_parts(
    body: bytes,
    content_type: str,
    max_parts: int,
) -> tuple[list[str], list[str], list[str], bool]:
    """Parse a `multipart/form-data` body well enough to extract:

    - field names (`name="..."`)
    - uploaded filenames (`filename="..."` — empty/absent means a plain field, not a file)
    - per-part Content-Type values
    - whether any part contains a PHP-shell indicator

    Returns ``(names, filenames, content_types, has_php_shell)``.

    Stops at `max_parts` parts. Stdlib-only: no `email.parser` dependency
    on the wire-shape, since exploit clients commonly emit slightly
    malformed multipart bodies that `email` rejects. We split on the
    boundary token from the Content-Type header and read the
    per-part header block via regex on the raw bytes.
    """
    if not body:
        return [], [], [], False
    ct_raw = content_type or ""
    ct_low = ct_raw.lower()
    if "multipart/form-data" not in ct_low or "boundary=" not in ct_low:
        return [], [], [], False
    # Find the boundary in the original-case header — boundary values are
    # case-sensitive, so we must not lowercase before extraction.
    boundary_start = ct_low.index("boundary=") + len("boundary=")
    boundary = ct_raw[boundary_start:].split(";", 1)[0].strip()
    # RFC 7578 permits a quoted boundary; strip surrounding quotes if present.
    if boundary.startswith('"') and boundary.endswith('"') and len(boundary) >= 2:
        boundary = boundary[1:-1]
    if not boundary:
        return [], [], [], False
    sep = b"--" + boundary.encode("latin-1", errors="replace")
    raw_parts = body.split(sep)
    # First element is the preamble (usually empty), last is the epilogue or
    # `--\r\n` end marker — neither is a real part.
    names: list[str] = []
    filenames: list[str] = []
    content_types: list[str] = []
    has_php_shell = False
    for chunk in raw_parts[1:1 + max_parts]:
        if not chunk or chunk[:2] == b"--":
            # Either the epilogue or the closing `--` after the final boundary.
            continue
        # Each part begins with CRLF (per RFC) — strip the leading newline so
        # the header regexes can match from the start. Tolerate LF-only.
        if chunk[:2] == b"\r\n":
            chunk = chunk[2:]
        elif chunk[:1] == b"\n":
            chunk = chunk[1:]
        header_end = chunk.find(b"\r\n\r\n")
        if header_end == -1:
            header_end = chunk.find(b"\n\n")
            if header_end == -1:
                # Malformed part — record its presence but skip extraction.
                continue
            part_headers = chunk[:header_end]
            part_body = chunk[header_end + 2:]
        else:
            part_headers = chunk[:header_end]
            part_body = chunk[header_end + 4:]
        m_name = _MULTIPART_NAME_RE.search(part_headers)
        if m_name:
            name_bytes = (m_name.group(1) or m_name.group(2) or b"").strip()
            names.append(name_bytes.decode("utf-8", errors="replace")[:120])
        m_filename = _MULTIPART_FILENAME_RE.search(part_headers)
        if m_filename:
            fn_bytes = (m_filename.group(1) or m_filename.group(2) or b"").strip()
            # An empty filename="" means "no file submitted for this field" —
            # we still record the field name above but skip the filename list.
            if fn_bytes:
                filenames.append(fn_bytes.decode("utf-8", errors="replace")[:240])
        m_ct = _MULTIPART_CONTENT_TYPE_RE.search(part_headers)
        if m_ct:
            ct_value = m_ct.group(1).strip()
            content_types.append(ct_value.decode("latin-1", errors="replace")[:120])
        if not has_php_shell:
            lowered_body = part_body.lower()
            for needle in _FILE_UPLOAD_PHP_SHELL_INDICATORS:
                if needle in lowered_body:
                    has_php_shell = True
                    break
    return names, filenames, content_types, has_php_shell


def extract_webapp_form_creds(body: bytes, content_type: str) -> tuple[str, bool, bool, list[str]]:
    """Pull (username, has_password, has_email, field_names) out of a form
    body. Accepts both `application/x-www-form-urlencoded` (the dominant
    shape from credential-stuffing tooling) and `application/json`
    (occasional API-style POST). Username value is capped at 120 chars;
    password value is never returned, only its presence."""
    username = ""
    has_password = False
    has_email = False
    field_names: list[str] = []
    if not body:
        return username, has_password, has_email, field_names
    ct = (content_type or "").split(";", 1)[0].strip().lower()
    parsed: dict[str, list[str]] = {}
    if ct in {"application/x-www-form-urlencoded", ""}:
        parsed = parse_form_body(body, content_type)
    elif ct == "application/json":
        try:
            obj = json.loads(body.decode("utf-8", errors="replace"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            obj = None
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, (str, int, float, bool)):
                    parsed[str(k)] = [str(v)]
    field_names = sorted({str(k) for k in parsed.keys()})[:32]
    for key in WEBAPP_FORM_USERNAME_KEYS:
        for candidate in (key, key.upper()):
            values = parsed.get(candidate)
            if values and values[0]:
                username = str(values[0])[:120]
                break
        if username:
            break
    has_password = any(
        bool((parsed.get(key) or parsed.get(key.upper()) or [""])[0])
        for key in WEBAPP_FORM_PASSWORD_KEYS
    )
    has_email = any(
        "@" in str((parsed.get(key) or parsed.get(key.upper()) or [""])[0])
        for key in ("email", "user_email", "e_mail", "mail")
    )
    if not has_email and username and "@" in username:
        has_email = True
    return username, has_password, has_email, field_names


def parse_cookies(cookie_header: str) -> dict[str, str]:
    cookies: dict[str, str] = {}
    if not cookie_header:
        return cookies
    for part in cookie_header.split(";"):
        part = part.strip()
        if not part or "=" not in part:
            continue
        name, _, value = part.partition("=")
        cookies[name.strip()] = value.strip()
    return cookies


def parse_form_body(body_bytes: bytes, content_type: str) -> dict[str, list[str]]:
    if not body_bytes:
        return {}
    ct = (content_type or "").split(";", 1)[0].strip().lower()
    # FortiOS SSL VPN posts `Content-Type: text/plain;charset=UTF-8` on
    # `/remote/logincheck` with a body that is otherwise form-urlencoded
    # (`ajax=1&username=…&credential=…`). Wild credential-stuffer fleets
    # copy that content type verbatim, so accepting `text/plain` here is
    # what recovers `username` / `credential` capture on those hits.
    # `parse_qs` on genuinely-free-text bodies just yields keys nothing
    # downstream looks for, so this doesn't leak into other traps.
    if ct not in {"application/x-www-form-urlencoded", "text/plain", ""}:
        return {}
    try:
        text = body_bytes.decode("utf-8", errors="replace")
    except UnicodeDecodeError:
        return {}
    return parse_qs(text, keep_blank_values=True)


def extract_webshell_command(
    query_params: dict[str, list[str]],
    form_params: dict[str, list[str]],
    cookies: dict[str, str],
    headers: object,
) -> tuple[str, str, str]:
    """Return (source, key, command). source='' means no command found."""
    for source, collection in (("query", query_params), ("form", form_params)):
        for key in WEBSHELL_COMMAND_KEYS:
            for candidate in (key, key.upper()):
                values = collection.get(candidate)
                if values and values[0]:
                    return source, candidate, values[0]
    for key in WEBSHELL_COMMAND_KEYS:
        if key in cookies and cookies[key]:
            return "cookie", key, cookies[key]
    for header_name in WEBSHELL_COMMAND_HEADERS:
        value = headers.get(header_name)
        if value:
            return "header", header_name, value
    return "", "", ""


def simulate_command_output(command: str) -> str:
    """Return plausible fake output for common reconnaissance commands.

    The goal is to look convincing enough that a scanner moves on to its next
    command instead of bailing after the first probe. Unknown commands return
    an empty string (which many shells produce for assignments, `cd`, etc.)
    so we don't leak "it's fake" via a canned error message.
    """
    cmd = command.strip()
    if not cmd:
        return ""
    first = cmd.split(None, 1)[0].lower().lstrip("!")
    if first in {"id"}:
        return "uid=33(www-data) gid=33(www-data) groups=33(www-data)\n"
    if first in {"whoami"}:
        return "www-data\n"
    if first in {"hostname"}:
        return "web-01\n"
    if first in {"pwd"}:
        return "/var/www/html/wp-content/plugins/hellopress\n"
    if cmd in {"uname", "uname -a", "uname -r"}:
        return "Linux web-01 5.15.0-86-generic #96-Ubuntu SMP Wed Sep 20 08:23:49 UTC 2023 x86_64 x86_64 x86_64 GNU/Linux\n"
    if cmd.startswith("cat /etc/passwd"):
        return (
            "root:x:0:0:root:/root:/bin/bash\n"
            "daemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\n"
            "bin:x:2:2:bin:/bin:/usr/sbin/nologin\n"
            "sys:x:3:3:sys:/dev:/usr/sbin/nologin\n"
            "www-data:x:33:33:www-data:/var/www:/usr/sbin/nologin\n"
            "mysql:x:112:116:MySQL Server,,,:/nonexistent:/bin/false\n"
        )
    if first in {"ls", "dir"}:
        return "index.php\nreadme.txt\nwp_filemanager.php\n"
    if cmd in {"w", "who"}:
        return "\n"
    return ""


def render_webshell_page(command: str = "", output: str = "") -> bytes:
    """Minimal but plausible File Manager-ish page. Encourages follow-up POSTs."""
    safe_command = command.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
    safe_output = output.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    html = (
        "<!doctype html>\n"
        "<html><head><title>File Manager</title></head><body>\n"
        "<h2>File Manager</h2>\n"
        "<form method='POST' action=''>\n"
        f"<input type='text' name='cmd' size='80' value='{safe_command}' autofocus />\n"
        "<input type='submit' value='Execute' />\n"
        "</form>\n"
        f"<pre>{safe_output}</pre>\n"
        "</body></html>\n"
    )
    return html.encode("utf-8")


def render_kcfinder_browse_html() -> bytes:
    """Plausible KCFinder file-browser landing page. Two goals: (1) pass
    presence-detection scanners that grep for `KCFinder` / `kcfinder.js`
    in the response body, and (2) carry an `<input type="file" name="upload[]">`
    so the scanner's next move is a multipart POST to `upload.php` — which
    is where we actually capture the payload."""
    return (
        b"<!doctype html>\n"
        b"<html lang=\"en\"><head>\n"
        b"<meta charset=\"utf-8\">\n"
        b"<title>KCFinder File Browser</title>\n"
        b"<link rel=\"stylesheet\" href=\"themes/oxygen/style.css\">\n"
        b"<script src=\"js/kcfinder.js\"></script>\n"
        b"</head>\n"
        b"<body class=\"kcfinder\">\n"
        b"<div id=\"toolbar\">\n"
        b"<button id=\"upload\">Upload</button>\n"
        b"<button id=\"refresh\">Refresh</button>\n"
        b"</div>\n"
        b"<form id=\"upload-form\" method=\"POST\" action=\"upload.php\" enctype=\"multipart/form-data\">\n"
        b"<input type=\"file\" name=\"upload[]\" multiple>\n"
        b"<input type=\"submit\" value=\"Upload\">\n"
        b"</form>\n"
        b"<div id=\"files\"></div>\n"
        b"</body></html>\n"
    )


def render_kcfinder_upload_response(filenames: list[str]) -> bytes:
    """KCFinder's `upload.php` returns one line per uploaded file, with a
    leading `/` for accepted uploads. Real-world scanners parse the first
    character to decide success. We claim success on every part: the next
    request the scanner makes is the actual webshell hit, which lands on
    `/<filename>` (404 in our world) but the multipart body is already
    logged by then."""
    if not filenames:
        return b""
    # Cap how many names we echo back to avoid amplifying an oversized
    # multipart body into an oversized response.
    return ("\n".join(f"/{name}" for name in filenames[:32]) + "\n").encode("utf-8")


def render_jquery_filer_readme() -> bytes:
    """Plausible jquery.filer README — presence-detection scanners fetch
    this exact file before sending the upload POST. Body matches the
    shape of the real README so a content-grep test passes."""
    return (
        b"jQuery.filer\n"
        b"============\n"
        b"\n"
        b"jQuery.filer is a simple HTML5 file uploader, a tool for client-side\n"
        b"file management, with multiple file selection, drag and drop support,\n"
        b"image previews, progress bars and image thumbnails.\n"
        b"\n"
        b"Server-side: php/upload.php (PHP-based form-data handler).\n"
        b"\n"
        b"License: MIT\n"
    )


def render_jquery_filer_upload_response(filenames: list[str]) -> bytes:
    """jquery.filer expects JSON in the shape ``{"OK": 1, "files": [...]}``
    on success. Each file entry mirrors the input filename and reports a
    plausible size + URL so the scanner accepts the upload as complete."""
    if not filenames:
        return b'{"OK":0,"err":"no file","files":[]}\n'
    files = [
        {
            "name": fn,
            "size": secrets.randbelow(900_000) + 1024,
            "type": "application/octet-stream",
            "file": f"./uploads/{fn}",
            "id": secrets.token_hex(8),
        }
        for fn in filenames[:32]
    ]
    return (json.dumps({"OK": 1, "files": files}) + "\n").encode("utf-8")


def render_blueimp_upload_response(filenames: list[str]) -> bytes:
    """Blueimp jQuery-File-Upload server reference implementation returns
    JSON in the shape ``{"files": [{"name": "...", "size": N, "url": "...",
    "thumbnailUrl": "...", "deleteUrl": "...", "deleteType": "DELETE"}, ...]}``.
    On a GET to `server/php/` it lists already-uploaded files; we return
    an empty list so the scanner thinks it found a fresh installation."""
    files = [
        {
            "name": fn,
            "size": secrets.randbelow(900_000) + 1024,
            "type": "application/octet-stream",
            "url": f"server/php/files/{fn}",
            "thumbnailUrl": "",
            "deleteUrl": f"server/php/?file={fn}",
            "deleteType": "DELETE",
        }
        for fn in filenames[:32]
    ]
    return (json.dumps({"files": files}) + "\n").encode("utf-8")


def _parse_chain_params(query: str) -> tuple[str, int]:
    """Extract redirect-chain tracking params from query string."""
    chain_id = ""
    hop = 0
    for part in query.split("&"):
        if "=" not in part:
            continue
        key, _, value = part.partition("=")
        if key == "_hp_chain":
            chain_id = value
        elif key == "_hp_hop":
            try:
                hop = int(value)
            except ValueError:
                pass
    return chain_id, hop


# --- Tarpit module framework ---


class TarpitModule:
    """Base class. Subclass and add to TARPIT_MODULES to activate.

    terminal=True  -> module produces a full aiohttp Response (and logs).
    terminal=False -> module returns (extra_headers, meta) for the caller
                      to merge into the tarpit stream's headers.
    """

    name: str = ""
    terminal: bool = False

    def should_run(self, ctx: dict[str, object]) -> bool:
        return False

    async def run_terminal(self, request: "web.Request", ctx: dict[str, object]) -> "web.Response":
        raise NotImplementedError

    def augment(
        self, request: "web.Request", ctx: dict[str, object]
    ) -> tuple[dict[str, str], dict[str, object]]:
        return {}, {}


class DNSCallbackModule(TarpitModule):
    """Redirect to <uuid>.track-domain to fingerprint DNS resolution."""

    name = "dns-callback"
    terminal = True

    def should_run(self, ctx):
        return MOD_DNS_CALLBACK_ENABLED and MOD_DNS_CALLBACK_DOMAIN

    async def run_terminal(self, request, ctx):
        callback_id = str(uuid.uuid4())
        proto = ctx.get("protocol", "https")
        location = f"{proto}://{callback_id}.{MOD_DNS_CALLBACK_DOMAIN}{ctx['path']}"
        append_log({
            **ctx["log_context"],
            "status": 302,
            "result": "tarpit-module",
            "module": self.name,
            "callbackId": callback_id,
            "location": location,
        })
        return web.Response(
            status=302,
            body=b"redirecting\n",
            headers={
                "Location": location,
                "Content-Type": "text/plain; charset=utf-8",
                "Cache-Control": "no-store",
            },
        )


class CookieTrackingModule(TarpitModule):
    """Set a tracking cookie; detect if scanners return it."""

    name = "cookie-tracking"
    terminal = False

    def should_run(self, ctx):
        return MOD_COOKIE_ENABLED

    def augment(self, request, ctx):
        cookie_header = request.headers.get("Cookie", "")
        returned_tid = ""
        if "_hp_tid=" in cookie_header:
            for part in cookie_header.split(";"):
                part = part.strip()
                if part.startswith("_hp_tid="):
                    returned_tid = part[8:]
                    break
        cookie_id = str(uuid.uuid4())
        headers = {"Set-Cookie": f"_hp_tid={cookie_id}; Path=/; HttpOnly; SameSite=Lax"}
        meta: dict[str, object] = {"cookieId": cookie_id}
        if returned_tid:
            meta["cookieReturned"] = returned_tid
        return headers, meta


class RedirectChainModule(TarpitModule):
    """Start a redirect chain to measure follow-depth."""

    name = "redirect-chain"
    terminal = True

    def should_run(self, ctx):
        if not MOD_REDIRECT_CHAIN_ENABLED:
            return False
        return not ctx.get("query") or "_hp_chain" not in ctx["query"]

    async def run_terminal(self, request, ctx):
        chain_id = str(uuid.uuid4())
        location = f"{ctx['path']}?_hp_chain={chain_id}&_hp_hop=1"
        append_log({
            **ctx["log_context"],
            "status": 302,
            "result": "tarpit-module",
            "module": self.name,
            "chainId": chain_id,
            "hop": 0,
        })
        return web.Response(
            status=302,
            body=b"redirecting\n",
            headers={
                "Location": location,
                "Content-Type": "text/plain; charset=utf-8",
                "Cache-Control": "no-store",
            },
        )


class ContentLengthMismatchModule(TarpitModule):
    """Set a large Content-Length to fingerprint client timeout/validation."""

    name = "content-length-mismatch"
    terminal = False

    def should_run(self, ctx):
        return MOD_CONTENT_LENGTH_MISMATCH_ENABLED

    def augment(self, request, ctx):
        return (
            {"Content-Length": str(MOD_CONTENT_LENGTH_CLAIMED_BYTES)},
            {"claimedBytes": MOD_CONTENT_LENGTH_CLAIMED_BYTES},
        )


class ETagProbeModule(TarpitModule):
    """Set ETag/Last-Modified; detect conditional requests on repeat visits."""

    name = "etag-probe"
    terminal = False

    def should_run(self, ctx):
        return MOD_ETAG_PROBE_ENABLED

    def augment(self, request, ctx):
        request_id = ctx.get("request_id", "")
        etag_value = f'"{request_id}"'
        headers = {"ETag": etag_value, "Last-Modified": "Mon, 01 Jan 2024 00:00:00 GMT"}
        meta: dict[str, object] = {"etag": etag_value}
        if_none_match = request.headers.get("If-None-Match", "")
        if_modified_since = request.headers.get("If-Modified-Since", "")
        if if_none_match:
            meta["conditionalRequest"] = True
            meta["ifNoneMatch"] = if_none_match[:256]
        if if_modified_since:
            meta["conditionalRequest"] = True
            meta["ifModifiedSince"] = if_modified_since[:256]
        return headers, meta


TARPIT_MODULES: list[TarpitModule] = []
if MOD_DNS_CALLBACK_ENABLED and MOD_DNS_CALLBACK_DOMAIN:
    TARPIT_MODULES.append(DNSCallbackModule())
if MOD_REDIRECT_CHAIN_ENABLED:
    TARPIT_MODULES.append(RedirectChainModule())
if MOD_COOKIE_ENABLED:
    TARPIT_MODULES.append(CookieTrackingModule())
if MOD_CONTENT_LENGTH_MISMATCH_ENABLED:
    TARPIT_MODULES.append(ContentLengthMismatchModule())
if MOD_ETAG_PROBE_ENABLED:
    TARPIT_MODULES.append(ETagProbeModule())


def build_tarpit_chunk(request_id: str, path: str, chunk_index: int) -> bytes:
    base = f"TRACEBIT_TARPIT_{chunk_index:06d}={request_id[:8]}:{path}".encode("utf-8", errors="replace")
    if len(base) < TARPIT_CHUNK_BYTES:
        base = base + (b"." * (TARPIT_CHUNK_BYTES - len(base)))
    else:
        base = base[:TARPIT_CHUNK_BYTES]
    return base + b"\n"


# One aiohttp session per process, created on first use. Reusing the session
# pools TCP+TLS connections to Tracebit so rapid cache-miss bursts don't each
# pay the handshake cost.
_http_session: aiohttp.ClientSession | None = None


async def _get_http_session() -> aiohttp.ClientSession:
    global _http_session
    if _http_session is None or _http_session.closed:
        _http_session = aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=10),
        )
    return _http_session


async def issue_credentials(
    request_id: str,
    client_ip: str,
    host: str,
    user_agent: str,
    path: str,
    proto: str,
    types: tuple[str, ...] | list[str] | None = None,
) -> dict[str, object]:
    issue_url = f"{API_BASE_URL}/api/v1/credentials/issue-credentials"
    safe_host = re.sub(r"[^0-9a-z._-]+", "-", host or "unknown").strip("-") or "unknown"
    request_name = f"{SENSOR_ID or 'sensor'}-{safe_host}-{datetime.now(UTC).strftime('%Y%m%dT%H%M%SZ')}-{request_id[:8]}"
    payload = {
        "name": request_name,
        "types": list(types) if types else CANARY_TYPES,
        "source": TRACEBIT_SOURCE,
        "sourceType": TRACEBIT_SOURCE_TYPE,
        "labels": [
            {"name": "sensor_id", "value": SENSOR_ID or "unknown"},
            {"name": "host", "value": host or "unknown"},
            {"name": "path", "value": path},
            {"name": "client_ip", "value": client_ip or "unknown"},
            {"name": "request_id", "value": request_id},
            {"name": "protocol", "value": proto or "unknown"},
            {"name": "user_agent", "value": (user_agent or "unknown")[:180]},
        ],
    }
    session = await _get_http_session()
    async with session.post(
        issue_url,
        json=payload,
        headers={
            "Authorization": f"Bearer {API_KEY}",
            "Accept": "application/json",
        },
    ) as response:
        response.raise_for_status()
        result = await response.json()
    _schedule_confirmations(result)
    return result


# Issued canaries don't show up as "active" in the Tracebit dashboard
# until /confirm-credentials is POSTed with their confirmationId — the
# OpenAPI spec is explicit about this. Without it, attackers harvesting
# our /id_rsa, .env, etc. get valid canary creds, but the operator's
# active-key list stays at whatever was confirmed manually. Fire one
# best-effort confirmation per issued canary, in the background, so the
# attacker-facing response isn't slowed by the extra round trip.
_CONFIRM_TASKS: set[asyncio.Task[None]] = set()


def _extract_confirmation_ids(response: object) -> list[str]:
    if not isinstance(response, dict):
        return []
    ids: list[str] = []
    for block_key, id_field in (("aws", "awsConfirmationId"), ("ssh", "sshConfirmationId")):
        block = response.get(block_key)
        if isinstance(block, dict):
            value = block.get(id_field)
            if isinstance(value, str) and value:
                ids.append(value)
    http = response.get("http")
    if isinstance(http, dict):
        for details in http.values():
            if isinstance(details, dict):
                value = details.get("confirmationId")
                if isinstance(value, str) and value:
                    ids.append(value)
    return ids


async def confirm_credential(confirmation_id: str) -> None:
    if not confirmation_id or not API_KEY:
        return
    confirm_url = f"{API_BASE_URL}/api/v1/credentials/confirm-credentials"
    session = await _get_http_session()
    try:
        async with session.post(
            confirm_url,
            json={"id": confirmation_id},
            headers={
                "Authorization": f"Bearer {API_KEY}",
                "Accept": "application/json",
            },
        ) as response:
            response.raise_for_status()
    except (aiohttp.ClientError, asyncio.TimeoutError):
        return


def _schedule_confirmations(response: object) -> None:
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    for confirmation_id in _extract_confirmation_ids(response):
        task = loop.create_task(confirm_credential(confirmation_id))
        _CONFIRM_TASKS.add(task)
        task.add_done_callback(_CONFIRM_TASKS.discard)


def format_env_payload(tracebit_response: dict[str, object]) -> str:
    # Rendered body is served verbatim on /.env; every string here is
    # visible to the attacker. No headers, no "canary"/"tracebit" tells,
    # no error sentinels — an empty upstream response becomes an empty
    # body, which is indistinguishable from an unremarkable empty .env.
    lines: list[str] = []

    aws = tracebit_response.get("aws")
    if isinstance(aws, dict):
        lines.extend(
            [
                f"AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}",
                f"AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}",
                f"AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}",
                f"AWS_CREDENTIAL_EXPIRATION={aws.get('awsExpiration', '')}",
            ]
        )

    ssh = tracebit_response.get("ssh")
    if isinstance(ssh, dict):
        lines.extend(
            [
                f"SSH_HOST={ssh.get('sshIp', '')}",
                f"SSH_PRIVATE_KEY_B64={ssh.get('sshPrivateKey', '')}",
                f"SSH_PUBLIC_KEY_B64={ssh.get('sshPublicKey', '')}",
                f"SSH_KEY_EXPIRATION={ssh.get('sshExpiration', '')}",
            ]
        )

    http = tracebit_response.get("http")
    if isinstance(http, dict):
        for canary_type, details in sorted(http.items()):
            if not isinstance(details, dict):
                continue
            env_key = canary_type.upper().replace("-", "_")
            credentials = details.get("credentials")
            if credentials is not None:
                lines.append(f"{env_key}_CREDENTIALS_JSON={json.dumps(credentials, separators=(',', ':'))}")
            host_names = details.get("hostNames")
            if isinstance(host_names, list):
                lines.append(f"{env_key}_HOSTNAMES={','.join(str(value) for value in host_names)}")
            expires_at = details.get("expiresAt")
            if expires_at:
                lines.append(f"{env_key}_EXPIRATION={expires_at}")

    if not lines:
        return ""
    lines.append("")
    return "\n".join(lines)


# --- Fake /.git/ tree builder ---

_FAKE_GIT_LOCK: asyncio.Lock | None = None
_FAKE_GIT_CACHE: dict[str, tuple[float, dict[str, bytes], dict[str, object]]] = {}
# Single-flight gate: same shape as `_CANARY_INFLIGHT`. A burst of concurrent
# `<prefix>/.git/config` probes from one IP would otherwise all bypass the
# empty cache, all call `issue_credentials`, and most of them fail issuance
# when the upstream rate-limits.
_FAKE_GIT_INFLIGHT: dict[str, "asyncio.Future[tuple[dict[str, bytes], dict[str, object]] | None]"] = {}


def _get_fake_git_lock() -> asyncio.Lock:
    # Must be created inside a running event loop; lazily initialize so the
    # module can be imported outside an async context (tests, etc.).
    global _FAKE_GIT_LOCK
    if _FAKE_GIT_LOCK is None:
        _FAKE_GIT_LOCK = asyncio.Lock()
    return _FAKE_GIT_LOCK


def _git_loose_object(obj_type: bytes, content: bytes) -> tuple[str, bytes]:
    """Return (sha1_hex, zlib-deflated loose object body)."""
    header = obj_type + b" " + str(len(content)).encode("ascii") + b"\x00"
    raw = header + content
    return hashlib.sha1(raw).hexdigest(), zlib.compress(raw)


def _git_tree_entry(mode: str, name: str, sha_hex: str) -> bytes:
    return mode.encode("ascii") + b" " + name.encode("utf-8") + b"\x00" + bytes.fromhex(sha_hex)


# Canonical 14 hook sample names a `git init`-fresh repo ships under
# `.git/hooks/`. Scanners enumerate these as a fingerprint check — a real
# repo always has them, a hand-rolled fake usually does not. A 404 on
# `.git/hooks/pre-commit.sample` against an otherwise-plausible /.git/HEAD
# is a strong "this isn't real" tell, so we serve a non-empty body for
# every name.
_FAKE_GIT_HOOK_NAMES: tuple[str, ...] = (
    "applypatch-msg",
    "commit-msg",
    "fsmonitor-watchman",
    "post-checkout",
    "post-commit",
    "post-merge",
    "post-receive",
    "post-rewrite",
    "post-update",
    "pre-applypatch",
    "pre-commit",
    "pre-merge-commit",
    "pre-push",
    "pre-rebase",
    "pre-receive",
    "prepare-commit-msg",
    "push-to-checkout",
    "sendemail-validate",
    "update",
)

# Extra branch names that enumeration scanners hit alongside
# `main` / `master`. These are the high-signal repeats from the
# fake-git-miss logs: each shows up at single-digit-to-low-double-digit
# IP-counts/day across the sensor fleet, all `.sample` hooks and
# common branch refs. Same `commit_sha` keeps each ref consistent
# with the synthesized tree.
_FAKE_GIT_EXTRA_BRANCHES: tuple[str, ...] = (
    "develop",
    "development",
    "dev",
    "staging",
    "production",
    "prod",
    "release",
    "qa",
)

# Tag refs a released repo would ship. Lightweight tags (bare commit-sha refs
# under `refs/tags/`) — no separate tag-object plumbing needed. The same
# `commit_sha` used for the branch heads is fine: every tag is projected
# onto the one synthesized commit. Common release-cadence names cover the
# scanner dictionaries that walk `/.git/refs/tags/<name>` after the branches.
# All entries stay within one convention: semver-v-prefixed release tags
# plus movable named pointers (`latest`/`release`/`stable`). Mixing bare
# `1.0.0` semver or channel-name tags like `alpha`/`beta` alongside the
# v-prefixed tags would make the release-naming pattern inconsistent —
# a fingerprint tell for scanners that check convention adherence.
_FAKE_GIT_TAG_REFS: tuple[str, ...] = (
    "v0.1",
    "v1.0",
    "v1.0.0",
    "v1.1",
    "v2.0",
    "v2.0.0",
    "latest",
    "release",
    "stable",
)


def _fake_git_hook_body(name: str) -> bytes:
    """Plausible-shaped `.sample` hook body.

    Deliberately a short generic shell stub rather than git's verbatim
    GPL-licensed template, so we don't redistribute GPL content inside
    Flux. Scanners that hash-match against git's exact bodies will spot
    the difference; the much more common check ("does this file exist
    and look hook-shaped?") still passes.
    """
    return (
        f"#!/bin/sh\n"
        f"#\n"
        f"# An example hook script for `{name}`.\n"
        f"# To enable, rename this file by removing the `.sample` suffix\n"
        f"# and make it executable.\n"
        f"#\n"
        f"# To bypass any hook, pass `--no-verify` to the relevant\n"
        f"# `git` invocation.\n"
        f"\n"
        f"exit 0\n"
    ).encode("utf-8")


def _format_secrets_yaml(tracebit_response: dict[str, object]) -> str:
    aws = tracebit_response.get("aws") if isinstance(tracebit_response, dict) else None
    if not isinstance(aws, dict):
        aws = {}
    lines = [
        "# config/secrets.yml",
        "# Rotated quarterly per INFRA-218.",
        "# Access restricted to prod deploy role; do not share.",
        "production:",
        "  aws:",
        f"    access_key_id: {aws.get('awsAccessKeyId', '')}",
        f"    secret_access_key: {aws.get('awsSecretAccessKey', '')}",
        f"    session_token: {aws.get('awsSessionToken', '')}",
        f"    expiration: {aws.get('awsExpiration', '')}",
        "    region: us-east-1",
        "",
    ]
    return "\n".join(lines)


def _build_fake_git_remote_url(tracebit_response: dict[str, object]) -> str:
    """Build the `url = …` line for the fake /.git/config [remote].

    If FAKE_GIT_REMOTE_URL is set (operator override), use it verbatim.
    Otherwise embed the Tracebit AWS canary as HTTPS Basic userinfo, so a
    scraper that only reads `.git/config` (no clone) still walks away with
    a live canary key. An attacker who extracts the URL and tries the
    access-key/secret as AWS credentials trips the canary; an attacker who
    actually runs `git clone` against the URL fails (the host is not ours)
    but we still catch them via the rest of the fake-git tree.
    """
    if FAKE_GIT_REMOTE_URL:
        return FAKE_GIT_REMOTE_URL
    aws = _aws(tracebit_response)
    access_key = str(aws.get("awsAccessKeyId") or "").strip()
    secret = str(aws.get("awsSecretAccessKey") or "").strip()
    if not access_key or not secret:
        # Canary mint failed or was incomplete; fall back to a static SSH
        # URL (no secret material) rather than emitting a malformed URL.
        return f"git@{FAKE_GIT_REMOTE_HOST}:{FAKE_GIT_REMOTE_PATH}"
    # Percent-encode the secret — base64 can contain '+' / '/' which break
    # URL parsing by downstream tools. quote() with an empty safe set is
    # RFC 3986 userinfo-safe.
    encoded_secret = quote(secret, safe="")
    return f"https://{access_key}:{encoded_secret}@{FAKE_GIT_REMOTE_HOST}/{FAKE_GIT_REMOTE_PATH}"


def _build_fake_repo(
    secrets_body: str,
    tracebit_response: dict[str, object] | None = None,
) -> tuple[dict[str, bytes], dict[str, object]]:
    """Build a loose-object git repo as a path->bytes map.

    Layout: root/{.env.example, README.md, config/secrets.yml}. One commit.
    The canary creds live inside the secrets.yml blob AND (when the Tracebit
    response is provided) inside the `.git/config` remote-origin URL.
    """
    secrets_sha, secrets_blob = _git_loose_object(b"blob", secrets_body.encode("utf-8"))

    readme_body = (
        "# internal-tools\n\n"
        "Shared ops tooling for production deploys.\n\n"
        "## Setup\n\n"
        "1. Copy `.env.example` to `.env`.\n"
        "2. Fill credentials from `config/secrets.yml` (rotated quarterly).\n"
        "3. Run `./bin/deploy prod`.\n"
    )
    readme_sha, readme_blob = _git_loose_object(b"blob", readme_body.encode("utf-8"))

    env_example_body = (
        "# Copy to .env and populate from config/secrets.yml\n"
        "AWS_ACCESS_KEY_ID=\n"
        "AWS_SECRET_ACCESS_KEY=\n"
        "AWS_SESSION_TOKEN=\n"
        "AWS_REGION=us-east-1\n"
    )
    env_example_sha, env_example_blob = _git_loose_object(b"blob", env_example_body.encode("utf-8"))

    # config/ subtree
    config_tree_entries = _git_tree_entry("100644", "secrets.yml", secrets_sha)
    config_tree_sha, config_tree_blob = _git_loose_object(b"tree", config_tree_entries)

    # Root tree. Entries MUST be sorted lexicographically by name.
    # Order: ".env.example" < "README.md" < "config"
    root_tree_entries = (
        _git_tree_entry("100644", ".env.example", env_example_sha)
        + _git_tree_entry("100644", "README.md", readme_sha)
        + _git_tree_entry("40000", "config", config_tree_sha)
    )
    root_tree_sha, root_tree_blob = _git_loose_object(b"tree", root_tree_entries)

    commit_ts = int(time.time()) - 14 * 86400
    commit_body = (
        f"tree {root_tree_sha}\n"
        f"author {FAKE_GIT_AUTHOR} {commit_ts} +0000\n"
        f"committer {FAKE_GIT_AUTHOR} {commit_ts} +0000\n"
        "\n"
        f"{FAKE_GIT_COMMIT_MESSAGE}\n"
    ).encode("utf-8")
    commit_sha, commit_blob = _git_loose_object(b"commit", commit_body)

    def obj_path(sha: str) -> str:
        return f"/.git/objects/{sha[:2]}/{sha[2:]}"

    remote_url = _build_fake_git_remote_url(tracebit_response or {})
    config_text = (
        "[core]\n"
        "\trepositoryformatversion = 0\n"
        "\tfilemode = true\n"
        "\tbare = false\n"
        "\tlogallrefupdates = true\n"
        "[remote \"origin\"]\n"
        f"\turl = {remote_url}\n"
        "\tfetch = +refs/heads/*:refs/remotes/origin/*\n"
        "[branch \"main\"]\n"
        "\tremote = origin\n"
        "\tmerge = refs/heads/main\n"
    )

    reflog_line = (
        f"0000000000000000000000000000000000000000 {commit_sha} "
        f"{FAKE_GIT_AUTHOR} {commit_ts} +0000\tcommit (initial): {FAKE_GIT_COMMIT_MESSAGE}\n"
    )

    # A minimal valid .git/index header: signature "DIRC" + version 2 +
    # entry count 0. Real scanners (git-dumper, gitdumper.sh, etc.) request
    # /.git/index on first contact and treat a 404 there as evidence of a
    # fake repo. Returning zero entries is cheap and convincing: `git
    # ls-files` against the tree just prints nothing.
    git_index_body = b"DIRC" + (2).to_bytes(4, "big") + (0).to_bytes(4, "big") + b"\x00" * 20
    # Keys are lowercased so lookups from extract_git_path() (which returns
    # a lowercased key) match regardless of the case a scanner used on the
    # wire. `/.git/HEAD` on the wire and `/.git/head` on the wire both land
    # on the same response. Real git uses mixed-case filenames on disk, but
    # the on-wire paths are what matter for a dumb-HTTP clone — and no
    # harvester relies on HTTP paths being case-sensitive.
    # FETCH_HEAD shape: `<sha>\t\tbranch '<name>' of <remote>` (note the
    # double-tab — `git fetch` writes an empty middle field for the "for-merge"
    # column when the ref was the requested one).
    fetch_head_remote = (
        FAKE_GIT_REMOTE_URL
        if FAKE_GIT_REMOTE_URL
        else f"git@{FAKE_GIT_REMOTE_HOST}:{FAKE_GIT_REMOTE_PATH}"
    )
    fetch_head_line = f"{commit_sha}\t\tbranch 'main' of {fetch_head_remote}\n"
    # Apache-style autoindex body for `/.git/` and its subdirectories.
    # Scanners that probe a bare directory (top fake-git-miss key in fleet
    # logs) treat a 404 here as a "not real / restricted" tell, or move on
    # before they ever ask for `/.git/HEAD`. Serving a plausible listing
    # keeps them walking the tree — and every linked entry below is one we
    # do answer with real content, so this is pure trap deepening.
    def _autoindex(display_path: str, entries: tuple[str, ...]) -> bytes:
        # `display_path` is the /.git-relative path shown in the H1
        # ("/.git", "/.git/refs", …). `entries` are the child names to
        # link. Directories carry a trailing "/" in the entry string;
        # everything else renders as a file link. Matches nginx
        # `autoindex on` output shape closely enough that scanners hashing
        # against Apache/nginx autoindex fingerprints stay engaged.
        body = [
            "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 3.2 Final//EN\">\n",
            "<html>\n",
            " <head>\n",
            f"  <title>Index of {display_path}</title>\n",
            " </head>\n",
            " <body>\n",
            f"<h1>Index of {display_path}</h1>\n",
            "<pre>      <a href=\"?C=N;O=D\">Name</a>\n",
            "      <hr>\n",
            "      <a href=\"../\">Parent Directory</a>\n",
        ]
        for entry in entries:
            body.append(f"      <a href=\"{entry}\">{entry}</a>\n")
        body.append("      <hr>\n</pre>\n</body></html>\n")
        return "".join(body).encode("utf-8")

    git_root_index = _autoindex(
        "/.git",
        (
            "HEAD",
            "config",
            "description",
            "FETCH_HEAD",
            "ORIG_HEAD",
            "COMMIT_EDITMSG",
            "index",
            "packed-refs",
            "branches/",
            "hooks/",
            "info/",
            "logs/",
            "objects/",
            "refs/",
        ),
    )
    files: dict[str, bytes] = {
        "/.git/": git_root_index,
        "/.git/head": b"ref: refs/heads/main\n",
        "/.git/config": config_text.encode("utf-8"),
        # Some scanners ask for a credential-store file inside the exposed
        # repo metadata rather than the conventional home-directory
        # `/.git-credentials` path. Keep it in the fake repo so dispatch
        # records the request as fake-git while still handing out a GitLab
        # username/password canary.
        "/.git/credentials": render_git_credentials(tracebit_response or {}),
        "/.git/index": git_index_body,
        "/.git/description": b"Unnamed repository; edit this file 'description' to name the repository.\n",
        "/.git/packed-refs": (
            "# pack-refs with: peeled fully-peeled sorted \n"
            f"{commit_sha} refs/heads/main\n"
        ).encode("utf-8"),
        # Plumbing files that ship with any `git init`-fresh repo. Scanners
        # check for these to verify a /.git/ is real — returning 404 on
        # /.git/COMMIT_EDITMSG, /.git/ORIG_HEAD, /.git/FETCH_HEAD against
        # an otherwise-plausible /.git/HEAD is a strong "this is a honeypot"
        # tell. Keys are lowercased to match extract_git_path() output.
        "/.git/commit_editmsg": (FAKE_GIT_COMMIT_MESSAGE + "\n").encode("utf-8"),
        "/.git/orig_head": f"{commit_sha}\n".encode("utf-8"),
        "/.git/fetch_head": fetch_head_line.encode("utf-8"),
        "/.git/refs/heads/main": f"{commit_sha}\n".encode("utf-8"),
        # `master` as a co-located alias for `main`: many repos still have
        # both branches, and scanners enumerate the canonical default-branch
        # names. Pointing master at the same commit costs nothing.
        "/.git/refs/heads/master": f"{commit_sha}\n".encode("utf-8"),
        # Remote-tracking refs — a freshly-cloned repo always has these. The
        # `refs/remotes/origin/HEAD` symbolic ref points at the default
        # branch; the leaf refs hold the same commit as the local branch.
        "/.git/refs/remotes/origin/head": b"ref: refs/remotes/origin/main\n",
        "/.git/refs/remotes/origin/main": f"{commit_sha}\n".encode("utf-8"),
        "/.git/refs/remotes/origin/master": f"{commit_sha}\n".encode("utf-8"),
        "/.git/info/refs": f"{commit_sha}\trefs/heads/main\n".encode("utf-8"),
        "/.git/info/exclude": (
            "# git ls-files --others --exclude-from=.git/info/exclude\n"
            "*.log\n.DS_Store\n"
        ).encode("utf-8"),
        # Additional /.git/info/* files a real repo commonly has. Scanners
        # enumerate these as fingerprint checks after the main refs — a 404
        # on `/.git/info/attributes` against an otherwise-plausible
        # `/.git/info/exclude` is a "this isn't real" tell. `attributes` is
        # populated when a repo pins its own line-ending / merge rules;
        # `sparse-checkout` is populated when sparse checkout is enabled
        # (empty is a valid resting state on a freshly-init'd repo);
        # `packs` is written when `git repack` runs (empty is also valid on
        # a repo with only loose objects).
        "/.git/info/attributes": (
            "# .git/info/attributes — repo-local git attributes\n"
            "* text=auto eol=lf\n"
            "*.png binary\n"
            "*.jpg binary\n"
            "*.pdf binary\n"
        ).encode("utf-8"),
        "/.git/info/sparse-checkout": b"",
        "/.git/info/packs": b"",
        # Two entries repo dumpers ask for that a real checkout does have and
        # this tree was missing, so they fell out as misses mid-walk:
        #   * `branches/` is the legacy remote shorthand directory. Modern git
        #     still creates it and leaves it empty, so an empty autoindex is
        #     the faithful answer.
        #   * `remotes/origin/HEAD` is the symref recording the remote's
        #     default branch, written by `clone` and by `remote set-head`.
        "/.git/branches/": _autoindex("/.git/branches", ()),
        "/.git/remotes/origin/head": b"ref: refs/remotes/origin/main\n",
        "/.git/logs/head": reflog_line.encode("utf-8"),
        "/.git/logs/refs/heads/main": reflog_line.encode("utf-8"),
        "/.git/logs/refs/heads/master": reflog_line.encode("utf-8"),
        "/.git/logs/refs/remotes/origin/head": reflog_line.encode("utf-8"),
        "/.git/logs/refs/remotes/origin/main": reflog_line.encode("utf-8"),
        "/.git/logs/refs/remotes/origin/master": reflog_line.encode("utf-8"),
        "/.git/objects/info/packs": b"",
        # Loose-object paths are already lowercase (hex). No case fold needed.
        obj_path(commit_sha): commit_blob,
        obj_path(root_tree_sha): root_tree_blob,
        obj_path(config_tree_sha): config_tree_blob,
        obj_path(secrets_sha): secrets_blob,
        obj_path(readme_sha): readme_blob,
        obj_path(env_example_sha): env_example_blob,
    }
    for hook_name in _FAKE_GIT_HOOK_NAMES:
        files[f"/.git/hooks/{hook_name}.sample"] = _fake_git_hook_body(hook_name)

    # Extra branch refs (`refs/heads/<branch>`, `refs/remotes/origin/<branch>`,
    # and the matching reflog entries). Same commit_sha across all branches —
    # a synthesized fake repo with one commit projected onto many branch
    # heads is plausible (a freshly-tagged release would look like this) and
    # closes the gap where scanners enumerating standard branch names
    # (`develop` / `staging` / `production` / …) were getting a 404 on every
    # one of them — a strong "this isn't a real repo" tell.
    for branch in _FAKE_GIT_EXTRA_BRANCHES:
        files[f"/.git/refs/heads/{branch}"] = f"{commit_sha}\n".encode("utf-8")
        files[f"/.git/refs/remotes/origin/{branch}"] = f"{commit_sha}\n".encode("utf-8")
        files[f"/.git/logs/refs/heads/{branch}"] = reflog_line.encode("utf-8")
        files[f"/.git/logs/refs/remotes/origin/{branch}"] = reflog_line.encode("utf-8")

    # Lightweight tag refs (`refs/tags/<name>` -> commit sha). Scanners
    # enumerate these alongside branch names after `/.git/HEAD`; a repo
    # with any published release ships them. Same commit_sha across all
    # tags keeps the synthesized tree consistent — every tag points at
    # the one commit. Lightweight (bare-sha) form avoids the tag-object
    # plumbing that annotated tags need.
    #
    # Also write the matching `logs/refs/tags/<name>` reflog line for
    # every tag — `git tag <name>` creates it, so scanners walking
    # `/.git/logs/refs/tags/<name>` after `/.git/refs/tags/<name>` expect
    # a 200 there too. Historically only branches got their reflog written
    # (see _FAKE_GIT_EXTRA_BRANCHES loop above); the tag-side reflog was
    # asymmetric-missing and every tag walked from the miss log.
    for tag in _FAKE_GIT_TAG_REFS:
        files[f"/.git/refs/tags/{tag}"] = f"{commit_sha}\n".encode("utf-8")
        files[f"/.git/logs/refs/tags/{tag}"] = reflog_line.encode("utf-8")

    # git-stash refs: a real repo with any saved stash has these; their
    # absence is a banner-grab tell for scanners that enumerate
    # `/.git/refs/stash` after `/.git/HEAD`. Empty stash list (just the
    # stash commit ref itself + empty reflog) keeps the fingerprint
    # plausible without inventing a fake stash entry.
    files["/.git/refs/stash"] = f"{commit_sha}\n".encode("utf-8")
    files["/.git/logs/refs/stash"] = reflog_line.encode("utf-8")

    # git-wip extension refs (`refs/wip/index/...`, `refs/wip/wtree/...`).
    # The git-wip third-party extension snapshots staging area + working
    # tree under each branch on every save; scanners include these paths
    # in enumeration dictionaries because exposed repos using git-wip
    # are common at orgs that adopted it. Pointed at the same commit
    # for every covered branch (main, master, plus the extras).
    for branch in ("main", "master", *_FAKE_GIT_EXTRA_BRANCHES):
        files[f"/.git/refs/wip/index/refs/heads/{branch}"] = f"{commit_sha}\n".encode("utf-8")
        files[f"/.git/refs/wip/wtree/refs/heads/{branch}"] = f"{commit_sha}\n".encode("utf-8")

    # Subdirectory autoindexes. Scanners walk `/.git/<subdir>/` after the
    # bare directory — recent recon fleets (multi-IP, mixed ASN, plain
    # `git/N.NN` clients + browser-mimic HTTP/2) enumerate every listed
    # subdir; without an autoindex here they hit 404 fake-git-miss on the
    # subdirectory even though the leaf files under it (e.g.
    # `/.git/refs/heads/main`, `/.git/hooks/pre-commit.sample`) render fine.
    # Same "keep them walking the tree" rationale as the /.git/ root index.
    _hook_entries = tuple(sorted(f"{name}.sample" for name in _FAKE_GIT_HOOK_NAMES))
    _branch_entries = tuple(sorted({"main", "master", *_FAKE_GIT_EXTRA_BRANCHES}))
    _tag_entries = tuple(sorted(_FAKE_GIT_TAG_REFS))
    files["/.git/hooks/"] = _autoindex("/.git/hooks", _hook_entries)
    files["/.git/info/"] = _autoindex(
        "/.git/info",
        ("attributes", "exclude", "packs", "refs", "sparse-checkout"),
    )
    files["/.git/refs/"] = _autoindex(
        "/.git/refs",
        ("heads/", "remotes/", "stash", "tags/", "wip/"),
    )
    files["/.git/refs/heads/"] = _autoindex("/.git/refs/heads", _branch_entries)
    files["/.git/refs/tags/"] = _autoindex("/.git/refs/tags", _tag_entries)
    files["/.git/refs/remotes/"] = _autoindex("/.git/refs/remotes", ("origin/",))
    files["/.git/refs/remotes/origin/"] = _autoindex(
        "/.git/refs/remotes/origin",
        ("HEAD", *_branch_entries),
    )
    files["/.git/refs/wip/"] = _autoindex("/.git/refs/wip", ("index/", "wtree/"))
    files["/.git/refs/wip/index/"] = _autoindex("/.git/refs/wip/index", ("refs/",))
    files["/.git/refs/wip/wtree/"] = _autoindex("/.git/refs/wip/wtree", ("refs/",))
    files["/.git/refs/wip/index/refs/"] = _autoindex(
        "/.git/refs/wip/index/refs", ("heads/",),
    )
    files["/.git/refs/wip/wtree/refs/"] = _autoindex(
        "/.git/refs/wip/wtree/refs", ("heads/",),
    )
    files["/.git/refs/wip/index/refs/heads/"] = _autoindex(
        "/.git/refs/wip/index/refs/heads", _branch_entries,
    )
    files["/.git/refs/wip/wtree/refs/heads/"] = _autoindex(
        "/.git/refs/wip/wtree/refs/heads", _branch_entries,
    )
    files["/.git/objects/"] = _autoindex("/.git/objects", ("info/", "pack/"))
    files["/.git/objects/info/"] = _autoindex("/.git/objects/info", ("packs",))
    # Empty `pack/` — no pack files in the synthesized loose-only repo, but
    # scanners walk the directory anyway. An autoindex with just the
    # Parent Directory link matches the shape a fresh `git init` yields.
    files["/.git/objects/pack/"] = _autoindex("/.git/objects/pack", ())
    files["/.git/logs/"] = _autoindex("/.git/logs", ("HEAD", "refs/"))
    files["/.git/logs/refs/"] = _autoindex(
        "/.git/logs/refs", ("heads/", "remotes/", "stash", "tags/"),
    )
    files["/.git/logs/refs/heads/"] = _autoindex(
        "/.git/logs/refs/heads", _branch_entries,
    )
    files["/.git/logs/refs/tags/"] = _autoindex(
        "/.git/logs/refs/tags", _tag_entries,
    )
    files["/.git/logs/refs/remotes/"] = _autoindex(
        "/.git/logs/refs/remotes", ("origin/",),
    )
    files["/.git/logs/refs/remotes/origin/"] = _autoindex(
        "/.git/logs/refs/remotes/origin", ("HEAD", *_branch_entries),
    )
    # `/.git/branches/` is a legacy directory `git init` still creates,
    # empty on any modern repo. Scanners that walk the full tree hit it.
    files["/.git/branches/"] = _autoindex("/.git/branches", ())

    # Editor-swap / backup-rotation aliases for `/.git/config` and
    # `/.git/credentials`. Scanner dictionaries walk `.bak` / `.old` /
    # `.local` / `.orig` / `~` variants for every dotfile they enumerate;
    # unaliased, these show up as fake-git-miss noise instead of an
    # issued canary. `.personal` / `.work` / `.user` are the multi-config
    # `git config --file <name>` conventions harvester lists commonly
    # include. Payloads are the exact same body — the on-disk shape a
    # sloppy edit would leave behind.
    _config_body = files["/.git/config"]
    _credentials_body = files["/.git/credentials"]
    for _alias in (
        "/.git/config.bak", "/.git/config.old", "/.git/config.local",
        "/.git/config.orig", "/.git/config.orig.bak", "/.git/config.bak.bak",
        "/.git/config.save", "/.git/config.swp", "/.git/config.swo",
        "/.git/config~", "/.git/config.personal", "/.git/config.work",
        "/.git/config.user",
    ):
        files[_alias] = _config_body
    for _alias in (
        "/.git/credentials.bak", "/.git/credentials.old",
        "/.git/credentials.local", "/.git/credentials~",
    ):
        files[_alias] = _credentials_body
    meta: dict[str, object] = {
        "commitSha": commit_sha,
        "rootTreeSha": root_tree_sha,
        "configTreeSha": config_tree_sha,
        "secretsBlobSha": secrets_sha,
        "readmeBlobSha": readme_sha,
        "envExampleBlobSha": env_example_sha,
    }
    return files, meta


async def _fake_git_get_or_build(
    client_ip: str,
    request_id: str,
    host: str,
    user_agent: str,
    path: str,
    proto: str,
) -> tuple[dict[str, bytes], dict[str, object]] | None:
    """Return cached repo for this IP, or mint a new canary + repo.

    Cache is keyed by client IP with a TTL so objects stay consistent across
    the many requests a git-dumper-style scanner makes within one session.
    """
    now = time.monotonic()
    cache_key = client_ip or f"_anon-{request_id}"
    lock = _get_fake_git_lock()
    async with lock:
        entry = _FAKE_GIT_CACHE.get(cache_key)
        if entry and entry[0] > now:
            return entry[1], entry[2]
        inflight = _FAKE_GIT_INFLIGHT.get(cache_key)
        if inflight is not None:
            waiter = inflight
            is_issuer = False
        else:
            waiter = asyncio.get_event_loop().create_future()
            _FAKE_GIT_INFLIGHT[cache_key] = waiter
            is_issuer = True

    if not is_issuer:
        try:
            return await waiter
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            return None

    # Release the lock during the network call so different IPs can issue in
    # parallel; for the same IP, the in-flight gate above coalesces N hits
    # onto this one issuance.
    try:
        try:
            tracebit_response = await issue_credentials(request_id, client_ip, host, user_agent, path, proto)
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            async with lock:
                _FAKE_GIT_INFLIGHT.pop(cache_key, None)
            if not waiter.done():
                waiter.set_result(None)
            return None

        secrets_body = _format_secrets_yaml(tracebit_response)
        files, meta = _build_fake_repo(secrets_body, tracebit_response)
        meta["canaryTypes"] = [key for key, value in tracebit_response.items() if value]

        expiry = now + FAKE_GIT_CACHE_TTL_SECONDS
        async with lock:
            expired = [k for k, v in _FAKE_GIT_CACHE.items() if v[0] <= now]
            for k in expired:
                del _FAKE_GIT_CACHE[k]
            if len(_FAKE_GIT_CACHE) >= FAKE_GIT_CACHE_MAX_ENTRIES:
                oldest_key = min(_FAKE_GIT_CACHE, key=lambda k: _FAKE_GIT_CACHE[k][0])
                del _FAKE_GIT_CACHE[oldest_key]
            _FAKE_GIT_CACHE[cache_key] = (expiry, files, meta)
            _FAKE_GIT_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result((files, meta))
        return files, meta
    except BaseException:
        async with lock:
            _FAKE_GIT_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result(None)
        raise


# --- Fake /.svn/ working copy ---
#
# The Subversion sibling of _build_fake_repo() above. Two generations of
# working-copy layout are answered deliberately:
#
#   * pre-1.7 — `.svn/entries` in the plain-text record format, with
#     pristine copies under `.svn/text-base/<name>.svn-base`.
#   * 1.7+    — `.svn/wc.db`, a real SQLite database, with pristine copies
#     under `.svn/pristine/<xx>/<sha1>.svn-base`.
#
# Both are served because the trap exists to observe *which* generation a
# client implements and whether it follows the format it asked for through
# to the pristine copy that actually holds file contents. Answering only
# one layout drops half the population at its first request, and the two
# dictionaries are walked in comparable volume.
#
# There are three independent places a credential can be picked up, which
# is what makes the response worth more than a flat 200:
#
#   1. the repository URL in `entries` / `wc.db` carries the canary as
#      HTTPS Basic userinfo — a client that reads only the metadata file
#      still leaves with a live credential (same idea as the fake-git
#      remote-origin URL);
#   2. `.svn/auth/svn.simple/<realm-hash>` is Subversion's own saved
#      -credential cache, in its real hash-dump serialization;
#   3. the pristine copy of the config file holds the same canary in a
#      dotenv/YAML body.
#
# Which of the three a client takes is the measurement: it separates
# "grabbed the first file in the dictionary" from "implemented the
# working-copy format and walked it".

_FAKE_SVN_LOCK: asyncio.Lock | None = None
_FAKE_SVN_CACHE: dict[str, tuple[float, dict[str, bytes], dict[str, object]]] = {}
_FAKE_SVN_INFLIGHT: dict[str, "asyncio.Future[tuple[dict[str, bytes], dict[str, object]] | None]"] = {}


def _get_fake_svn_lock() -> asyncio.Lock:
    global _FAKE_SVN_LOCK
    if _FAKE_SVN_LOCK is None:
        _FAKE_SVN_LOCK = asyncio.Lock()
    return _FAKE_SVN_LOCK


def _build_fake_svn_repo_url(tracebit_response: dict[str, object]) -> str:
    """Build the repository root URL recorded in the working copy.

    Same rationale as _build_fake_git_remote_url(): when no operator
    override is set, the Tracebit AWS canary goes in as HTTPS Basic
    userinfo so a client that reads only `entries` (or only the
    REPOSITORY row of `wc.db`) still walks away with a live credential.
    Falls back to a bare URL with no secret material if the mint failed.
    """
    if FAKE_SVN_REPO_URL:
        return FAKE_SVN_REPO_URL
    base = f"{FAKE_SVN_REPO_HOST}/{FAKE_SVN_REPO_PATH}"
    aws = _aws(tracebit_response)
    access_key = str(aws.get("awsAccessKeyId") or "").strip()
    secret = str(aws.get("awsSecretAccessKey") or "").strip()
    if not access_key or not secret:
        return f"https://{base}"
    return f"https://{access_key}:{quote(secret, safe='')}@{base}"


def _svn_hash_dump(pairs: tuple[tuple[str, str], ...]) -> bytes:
    """Serialize key/value pairs in Subversion's hash-dump format.

    This is the on-disk format of `.svn/auth/svn.simple/<md5>` and
    `.svn/all-wcprops`: for each entry a `K <len>` line, the key, a
    `V <len>` line, the value, and a trailing `END`. Lengths are byte
    counts, so a tool validating them against the payload sees a
    well-formed file.
    """
    out: list[bytes] = []
    for key, value in pairs:
        key_bytes = key.encode("utf-8")
        value_bytes = value.encode("utf-8")
        out.append(b"K %d\n%s\n" % (len(key_bytes), key_bytes))
        out.append(b"V %d\n%s\n" % (len(value_bytes), value_bytes))
    out.append(b"END\n")
    return b"".join(out)


def _build_fake_svn_wc(
    tracebit_response: dict[str, object] | None = None,
) -> tuple[dict[str, bytes], dict[str, object]]:
    """Build a Subversion working copy as a path->bytes map.

    Layout: root/{.env, README.md, deploy.sh, config/database.yml}. The
    canary lives in the `.env` pristine copy, in the repository URL, and
    in the saved-credential cache.
    """
    response = tracebit_response or {}
    repo_url = _build_fake_svn_repo_url(response)
    # The realmstring is what svn hashes to name the auth-cache file, and
    # it never carries userinfo — so derive it from the bare host/path,
    # not from the canary-bearing URL above.
    realmstring = f"<https://{FAKE_SVN_REPO_HOST}:443> deploy-tools"
    realm_hash = hashlib.md5(realmstring.encode("utf-8")).hexdigest()
    repo_uuid = str(uuid.uuid5(uuid.NAMESPACE_URL, f"{FAKE_SVN_REPO_HOST}/{FAKE_SVN_REPO_PATH}"))
    revision = FAKE_SVN_REVISION
    committed = datetime.now(UTC) - timedelta(days=19)
    committed_iso = committed.strftime("%Y-%m-%dT%H:%M:%S.000000Z")

    readme_body = (
        "deploy-tools\n"
        "============\n\n"
        "Deploy helpers for the production stack.\n\n"
        "Credentials are read from `.env`; see `config/database.yml` for\n"
        "the per-environment database settings.\n"
    )
    deploy_body = (
        "#!/bin/sh\n"
        "# Wrapper around the release task. Reads credentials from .env.\n"
        "set -eu\n"
        ". \"$(dirname \"$0\")/.env\"\n"
        "exec ./bin/release \"$@\"\n"
    )
    database_body = (
        "production:\n"
        "  adapter: postgresql\n"
        "  host: db.internal\n"
        "  database: app_production\n"
        "  username: app_prod\n"
        f"  password: {_fake_db_password()}\n"
        "  pool: 25\n"
    )
    # The tracked `.env` — a dotenv body, not the YAML `secrets.yml` shape
    # the git tree uses, because that is what a checked-in `.env` beside a
    # `deploy.sh` that sources it actually looks like.
    aws = _aws(response)
    env_body = (
        "APP_ENV=production\n"
        "APP_DEBUG=false\n"
        f"AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}\n"
        f"AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}\n"
        f"AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}\n"
        "AWS_DEFAULT_REGION=us-east-1\n"
        "DATABASE_URL=postgresql://app_prod@db.internal/app_production\n"
    )

    # (working-copy relative path, body) in the order svn stores them.
    wc_files: tuple[tuple[str, str], ...] = (
        (".env", env_body),
        ("README.md", readme_body),
        ("config/database.yml", database_body),
        ("deploy.sh", deploy_body),
    )

    files: dict[str, bytes] = {}
    checksums: dict[str, str] = {}
    for relpath, body in wc_files:
        raw = body.encode("utf-8")
        sha1 = hashlib.sha1(raw).hexdigest()
        checksums[relpath] = sha1
        # 1.7+ pristine store: .svn/pristine/<first two hex>/<sha1>.svn-base
        files[f"/.svn/pristine/{sha1[:2]}/{sha1}.svn-base"] = raw
        # pre-1.7 pristine store: .svn/text-base/<name>.svn-base, which is
        # per-directory — only the root-level names live at the wc root.
        if "/" not in relpath:
            files[f"/.svn/text-base/{relpath}.svn-base"] = raw

    # --- pre-1.7 `.svn/entries` ---------------------------------------
    # Record format: a `\f`-separated list of entries, the first being the
    # directory itself. Field order is the one svn 1.6 writes; trailing
    # empty fields are meaningful and deliberately preserved.
    def _entry(name: str, kind: str, checksum: str = "") -> str:
        return "\n".join((
            name, kind, "", "", "", "", "", str(revision), committed_iso,
            checksum, committed_iso, str(revision), FAKE_SVN_AUTHOR,
        )) + "\n"

    entries_records = [
        "\n".join((
            "", "dir", "", repo_url, f"https://{FAKE_SVN_REPO_HOST}/{FAKE_SVN_REPO_PATH}",
            "", committed_iso, str(revision), FAKE_SVN_AUTHOR, "", "", "", "", "",
            repo_uuid,
        )) + "\n",
    ]
    for relpath, _body in wc_files:
        if "/" in relpath:
            continue
        entries_records.append(_entry(relpath, "file", checksums[relpath]))
    entries_records.append(_entry("config", "dir"))
    entries_body = f"{revision}\n\n" + "\x0c\n".join(entries_records)
    files["/.svn/entries"] = entries_body.encode("utf-8")
    files["/.svn/format"] = b"10\n"

    files["/.svn/all-wcprops"] = _svn_hash_dump((
        ("svn:wc:ra_dav:version-url", f"/{FAKE_SVN_REPO_PATH}/!svn/ver/{revision}"),
    ))
    files["/.svn/dir-prop-base"] = _svn_hash_dump((
        ("svn:ignore", "*.log\ntmp\n"),
    ))

    # --- Subversion's saved-credential cache --------------------------
    # `.svn/auth/svn.simple/<md5(realmstring)>` is where `svn --username
    # ... --password ...` parks credentials when the client is allowed to
    # cache them. Harvesters ask for it directly because, unlike the rest
    # of the working copy, it is a credential file by design.
    gitlab = _gitlab_creds(response, "gitlab-username-password")
    gitlab_credentials = gitlab.get("credentials") if isinstance(gitlab, dict) else None
    if isinstance(gitlab_credentials, dict):
        svn_username = str(gitlab_credentials.get("username") or "").strip()
        svn_password = str(gitlab_credentials.get("password") or "").strip()
    else:
        svn_username = ""
        svn_password = ""
    if svn_username and svn_password:
        auth_body = _svn_hash_dump((
            ("svn:realmstring", realmstring),
            ("username", svn_username),
            ("password", svn_password),
            ("passtype", "simple"),
        ))
        files[f"/.svn/auth/svn.simple/{realm_hash}"] = auth_body
        # Bare-directory probes are common — the dictionary asks for
        # `.svn/auth/svn.simple` far more often than for the hashed
        # filename it cannot guess. An autoindex is what an exposed
        # working copy would answer with, and it hands over the one
        # filename the client needs next.
        files["/.svn/auth/svn.simple/"] = _svn_autoindex(
            "/.svn/auth/svn.simple", (realm_hash,),
        )
        files["/.svn/auth/"] = _svn_autoindex("/.svn/auth", ("svn.simple/",))

    # --- 1.7+ `wc.db` --------------------------------------------------
    files["/.svn/wc.db"] = _build_fake_svn_wc_db(
        repo_url, repo_uuid, revision, checksums, committed,
    )

    root_entries = ["entries", "format", "all-wcprops", "dir-prop-base", "wc.db", "pristine/", "text-base/"]
    if f"/.svn/auth/svn.simple/{realm_hash}" in files:
        root_entries.insert(0, "auth/")
    files["/.svn/"] = _svn_autoindex("/.svn", tuple(root_entries))
    files["/.svn/text-base/"] = _svn_autoindex(
        "/.svn/text-base",
        tuple(f"{relpath}.svn-base" for relpath, _b in wc_files if "/" not in relpath),
    )
    files["/.svn/pristine/"] = _svn_autoindex(
        "/.svn/pristine",
        tuple(sorted({f"{sha1[:2]}/" for sha1 in checksums.values()})),
    )

    meta: dict[str, object] = {
        "svnRevision": revision,
        "svnRepoUuid": repo_uuid,
        "svnRealmHash": realm_hash,
        "svnFileCount": len(wc_files),
        "svnAuthCached": bool(svn_username and svn_password),
    }
    return files, meta


def _svn_autoindex(display_path: str, entries: tuple[str, ...]) -> bytes:
    """Apache-style autoindex body, matching the fake-git tree's listing.

    Same reasoning as there: a 404 on a bare directory reads as "not
    really exposed" and ends the walk, while a listing keeps the client
    moving toward files we do answer.
    """
    body = [
        "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 3.2 Final//EN\">\n",
        "<html>\n",
        " <head>\n",
        f"  <title>Index of {display_path}</title>\n",
        " </head>\n",
        " <body>\n",
        f"<h1>Index of {display_path}</h1>\n",
        "<pre>      <a href=\"?C=N;O=D\">Name</a>\n",
        "      <hr>\n",
        "      <a href=\"../\">Parent Directory</a>\n",
    ]
    for entry in entries:
        body.append(f"      <a href=\"{entry}\">{entry}</a>\n")
    body.append("      <hr>\n</pre>\n</body></html>\n")
    return "".join(body).encode("utf-8")


def _build_fake_svn_wc_db(
    repo_url: str,
    repo_uuid: str,
    revision: int,
    checksums: dict[str, str],
    committed: datetime,
) -> bytes:
    """Build a real SQLite `wc.db` for the 1.7+ working-copy layout.

    Tools that understand modern working copies open this with SQLite and
    read NODES to learn the file list and each file's `$sha1$...`
    checksum, which is what names the pristine file they fetch next. A
    stub or a text file breaks at the first query, so this builds a
    genuine database with the subset of the schema those queries touch.
    """
    connection = sqlite3.connect(":memory:")
    try:
        connection.executescript(
            """
            CREATE TABLE REPOSITORY (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              root TEXT UNIQUE NOT NULL,
              uuid TEXT NOT NULL
            );
            CREATE TABLE WCROOT (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              local_abspath TEXT UNIQUE
            );
            CREATE TABLE PRISTINE (
              checksum TEXT NOT NULL PRIMARY KEY,
              compression INTEGER,
              size INTEGER NOT NULL,
              refcount INTEGER NOT NULL,
              md5_checksum TEXT
            );
            CREATE TABLE NODES (
              wc_id INTEGER NOT NULL,
              local_relpath TEXT NOT NULL,
              op_depth INTEGER NOT NULL,
              parent_relpath TEXT,
              repos_id INTEGER,
              repos_path TEXT,
              revision INTEGER,
              presence TEXT NOT NULL,
              depth TEXT,
              kind TEXT NOT NULL,
              changed_revision INTEGER,
              changed_date INTEGER,
              changed_author TEXT,
              checksum TEXT,
              translated_size INTEGER,
              last_mod_time INTEGER,
              PRIMARY KEY (wc_id, local_relpath, op_depth)
            );
            CREATE TABLE ACTUAL_NODE (
              wc_id INTEGER NOT NULL,
              local_relpath TEXT NOT NULL,
              parent_relpath TEXT,
              PRIMARY KEY (wc_id, local_relpath)
            );
            """
        )
        connection.execute(
            "INSERT INTO REPOSITORY (id, root, uuid) VALUES (1, ?, ?)",
            (repo_url, repo_uuid),
        )
        connection.execute(
            "INSERT INTO WCROOT (id, local_abspath) VALUES (1, NULL)",
        )
        # svn stores changed_date as microseconds since the epoch.
        changed_date = int(committed.timestamp() * 1_000_000)
        last_mod_time = int(committed.timestamp())
        connection.execute(
            "INSERT INTO NODES (wc_id, local_relpath, op_depth, parent_relpath,"
            " repos_id, repos_path, revision, presence, depth, kind,"
            " changed_revision, changed_date, changed_author)"
            " VALUES (1, '', 0, NULL, 1, '', ?, 'normal', 'infinity', 'dir', ?, ?, ?)",
            (revision, revision, changed_date, FAKE_SVN_AUTHOR),
        )
        directories = {
            relpath.rsplit("/", 1)[0] for relpath in checksums if "/" in relpath
        }
        for directory in sorted(directories):
            connection.execute(
                "INSERT INTO NODES (wc_id, local_relpath, op_depth, parent_relpath,"
                " repos_id, repos_path, revision, presence, depth, kind,"
                " changed_revision, changed_date, changed_author)"
                " VALUES (1, ?, 0, '', 1, ?, ?, 'normal', 'infinity', 'dir', ?, ?, ?)",
                (directory, directory, revision, revision, changed_date, FAKE_SVN_AUTHOR),
            )
        for relpath, sha1 in sorted(checksums.items()):
            parent = relpath.rsplit("/", 1)[0] if "/" in relpath else ""
            connection.execute(
                "INSERT INTO NODES (wc_id, local_relpath, op_depth, parent_relpath,"
                " repos_id, repos_path, revision, presence, depth, kind,"
                " changed_revision, changed_date, changed_author, checksum,"
                " translated_size, last_mod_time)"
                " VALUES (1, ?, 0, ?, 1, ?, ?, 'normal', NULL, 'file', ?, ?, ?, ?, NULL, ?)",
                (
                    relpath, parent, relpath, revision, revision, changed_date,
                    FAKE_SVN_AUTHOR, f"$sha1${sha1}", last_mod_time,
                ),
            )
            connection.execute(
                "INSERT INTO PRISTINE (checksum, compression, size, refcount)"
                " VALUES (?, NULL, 0, 1)",
                (f"$sha1${sha1}",),
            )
            connection.execute(
                "INSERT INTO ACTUAL_NODE (wc_id, local_relpath, parent_relpath)"
                " VALUES (1, ?, ?)",
                (relpath, parent),
            )
        connection.commit()
        return connection.serialize()
    finally:
        connection.close()


async def _fake_svn_get_or_build(
    client_ip: str,
    request_id: str,
    host: str,
    user_agent: str,
    path: str,
    proto: str,
) -> tuple[dict[str, bytes], dict[str, object]] | None:
    """Return the cached working copy for this IP, or mint a canary and
    build one. Same per-IP cache + in-flight coalescing as fake-git, so a
    dictionary sweep across dozens of `.svn/*` paths costs one issuance
    and sees one self-consistent working copy.
    """
    now = time.monotonic()
    cache_key = client_ip or f"_anon-{request_id}"
    lock = _get_fake_svn_lock()
    async with lock:
        entry = _FAKE_SVN_CACHE.get(cache_key)
        if entry and entry[0] > now:
            return entry[1], entry[2]
        inflight = _FAKE_SVN_INFLIGHT.get(cache_key)
        if inflight is not None:
            waiter = inflight
            is_issuer = False
        else:
            waiter = asyncio.get_event_loop().create_future()
            _FAKE_SVN_INFLIGHT[cache_key] = waiter
            is_issuer = True

    if not is_issuer:
        try:
            return await waiter
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            return None

    try:
        try:
            tracebit_response = await issue_credentials(
                request_id, client_ip, host, user_agent, path, proto,
            )
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            async with lock:
                _FAKE_SVN_INFLIGHT.pop(cache_key, None)
            if not waiter.done():
                waiter.set_result(None)
            return None

        files, meta = _build_fake_svn_wc(tracebit_response)
        meta["canaryTypes"] = [key for key, value in tracebit_response.items() if value]

        expiry = now + FAKE_SVN_CACHE_TTL_SECONDS
        async with lock:
            expired = [k for k, v in _FAKE_SVN_CACHE.items() if v[0] <= now]
            for k in expired:
                del _FAKE_SVN_CACHE[k]
            if len(_FAKE_SVN_CACHE) >= FAKE_SVN_CACHE_MAX_ENTRIES:
                oldest_key = min(_FAKE_SVN_CACHE, key=lambda k: _FAKE_SVN_CACHE[k][0])
                del _FAKE_SVN_CACHE[oldest_key]
            _FAKE_SVN_CACHE[cache_key] = (expiry, files, meta)
            _FAKE_SVN_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result((files, meta))
        return files, meta
    except BaseException:
        async with lock:
            _FAKE_SVN_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result(None)
        raise


# --- Canary-backed file traps ---
#
# Each entry routes a set of exact paths to a render function that embeds
# a freshly-minted Tracebit canary credential into a plausible file format
# (wp-config.php, .aws/credentials, a SQL dump, etc.). Per-IP cache keeps
# repeated scanner fan-out from burning Tracebit quota.

_CANARY_LOCK: asyncio.Lock | None = None
_CANARY_CACHE: dict[tuple[str, tuple[str, ...]], tuple[float, dict[str, object]]] = {}
# In-flight issuance futures keyed identically to _CANARY_CACHE. Concurrent
# requests with the same (IP, types) tuple await one issuance instead of all
# racing into issue_credentials() and getting rate-limited by the canary API.
_CANARY_INFLIGHT: dict[tuple[str, tuple[str, ...]], "asyncio.Future[dict[str, object] | None]"] = {}
CANARY_TRAP_CACHE_TTL_SECONDS = max(
    int((os.environ.get("CANARY_TRAP_CACHE_TTL_SECONDS") or "3600").strip() or "3600"), 60,
)
CANARY_TRAP_CACHE_MAX_ENTRIES = max(
    int((os.environ.get("CANARY_TRAP_CACHE_MAX_ENTRIES") or "1024").strip() or "1024"), 16,
)
CANARY_TRAPS_ENABLED = _env_bool("CANARY_TRAPS_ENABLED")
# Whether an exact-path trap miss may retry after dropping known
# app-layout directory segments (see `resolve_canary_trap`). Separate
# switch so the walk can be turned off without disabling the traps
# themselves if it ever proves too permissive in the wild.
TRAP_PATH_WALK_ENABLED = _env_bool("HONEYPOT_TRAP_PATH_WALK_ENABLED")


def _get_canary_lock() -> asyncio.Lock:
    global _CANARY_LOCK
    if _CANARY_LOCK is None:
        _CANARY_LOCK = asyncio.Lock()
    return _CANARY_LOCK


async def _get_or_issue_canary(
    types: tuple[str, ...],
    client_ip: str,
    request_id: str,
    host: str,
    user_agent: str,
    path: str,
    proto: str,
) -> dict[str, object] | None:
    """Per-(IP, types) TTL-cached canary issuance.

    A scanner that fans out on the same trap (or different traps needing the
    same canary types) within the TTL gets one canary, not N. Concurrent
    requests that arrive before the first issuance returns share one in-flight
    Future via `_CANARY_INFLIGHT` — without this single-flight gate, a burst
    of N parallel hits on the same key all bypass the empty cache and all hit
    the upstream API, which then rate-limits and fails every trap response.
    """
    now = time.monotonic()
    cache_key = (client_ip or f"_anon-{request_id}", types)
    lock = _get_canary_lock()
    async with lock:
        entry = _CANARY_CACHE.get(cache_key)
        if entry and entry[0] > now:
            return entry[1]
        inflight = _CANARY_INFLIGHT.get(cache_key)
        if inflight is not None:
            waiter = inflight
            is_issuer = False
        else:
            waiter = asyncio.get_event_loop().create_future()
            _CANARY_INFLIGHT[cache_key] = waiter
            is_issuer = True

    if not is_issuer:
        try:
            return await waiter
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            return None

    try:
        try:
            resp = await issue_credentials(request_id, client_ip, host, user_agent, path, proto, types=types)
        except (aiohttp.ClientError, asyncio.TimeoutError, ValueError):
            async with lock:
                _CANARY_INFLIGHT.pop(cache_key, None)
            if not waiter.done():
                waiter.set_result(None)
            return None
        expiry = now + CANARY_TRAP_CACHE_TTL_SECONDS
        async with lock:
            expired = [k for k, v in _CANARY_CACHE.items() if v[0] <= now]
            for k in expired:
                del _CANARY_CACHE[k]
            if len(_CANARY_CACHE) >= CANARY_TRAP_CACHE_MAX_ENTRIES:
                oldest_key = min(_CANARY_CACHE, key=lambda k: _CANARY_CACHE[k][0])
                del _CANARY_CACHE[oldest_key]
            _CANARY_CACHE[cache_key] = (expiry, resp)
            _CANARY_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result(resp)
        return resp
    except BaseException:
        async with lock:
            _CANARY_INFLIGHT.pop(cache_key, None)
        if not waiter.done():
            waiter.set_result(None)
        raise


# --- Canary-echo observer: remember what we issued, notice it coming back ---

def canary_echo_note_issued(key_id: str) -> None:
    """Record one access key id this server has served.

    Called from `_aws()`, which every renderer that embeds an AWS canary
    goes through — so a new renderer is covered the day it is written and
    cannot forget to register. Keeping the registry keyed on what was
    actually served, rather than on a configured pattern, is also what
    keeps the issuing account out of this file.
    """
    if not CANARY_ECHO_ENABLED or not key_id:
        return
    if not _AWS_KEY_ID_RE.fullmatch(key_id):
        return
    # Re-inserting moves a key to the newest position, so a credential
    # still in active use is not the one evicted.
    _CANARY_ECHO_ISSUED.pop(key_id, None)
    _CANARY_ECHO_ISSUED[key_id] = None
    while len(_CANARY_ECHO_ISSUED) > CANARY_ECHO_MAX_KEYS:
        # dicts iterate in insertion order, so this drops the oldest.
        del _CANARY_ECHO_ISSUED[next(iter(_CANARY_ECHO_ISSUED))]
    # Prefixes are never evicted: there are only ever a handful, and
    # forgetting one would silently downgrade `account` matches to
    # `foreign` after a busy day.
    _CANARY_ECHO_ACCOUNT_PREFIXES.add(key_id[:_CANARY_ECHO_PREFIX_LEN])


def _canary_echo_classify(key_id: str) -> str:
    """`own` when this process served the exact key, `account` when it
    came from the account we issue from, `foreign` otherwise.

    The three are worth separating. `own` is this host's credential
    coming home. `account` is a credential from a sibling host, which is
    the only evidence available that a harvest is being replayed across
    a fleet rather than at its source. `foreign` is somebody else's
    stolen key arriving here — not ours to alert on, but it says the
    sender is carrying loot from elsewhere.
    """
    if key_id in _CANARY_ECHO_ISSUED:
        return "own"
    if key_id[:_CANARY_ECHO_PREFIX_LEN] in _CANARY_ECHO_ACCOUNT_PREFIXES:
        return "account"
    return "foreign"


# Strongest first: one request carrying several keys is described by the
# closest relationship any of them has to us.
_CANARY_ECHO_RANK = ("own", "account", "foreign")


def canary_echo_scan(
    raw_target: str,
    headers: dict[str, object] | None,
    body: bytes,
) -> dict[str, object]:
    """Look for access key ids in an inbound request and describe what
    was found. Returns `{}` when there is nothing to say.

    Scans the request target (path and query together, pre-decode and
    decoded, because a key can arrive percent-encoded), the logged header
    subset, and the head of the body. The caller merges the result into
    the log context *before* dispatch, so whichever trap ends up
    answering carries the finding on its own line — a key echoed at a
    path that some other trap owns is exactly as interesting as one
    echoed at a path nothing serves.
    """
    if not CANARY_ECHO_ENABLED:
        return {}

    found: dict[str, str] = {}
    where: set[str] = set()

    def scan(text: str, location: str) -> None:
        for key_id in _AWS_KEY_ID_RE.findall(text):
            found.setdefault(key_id, location)
            where.add(location)

    if raw_target:
        scan(raw_target, "target")
        # A key in a query value is usually percent-encoded somewhere on
        # its way here; decode once and look again.
        try:
            decoded = unquote(raw_target)
        except (UnicodeDecodeError, ValueError):
            decoded = ""
        if decoded and decoded != raw_target:
            scan(decoded, "target")

    if headers:
        for name, value in headers.items():
            if isinstance(value, str) and value:
                scan(value, f"header:{name.lower()}")

    if body:
        scan(body[:CANARY_ECHO_BODY_SCAN_LIMIT].decode("utf-8", "replace"), "body")

    if not found:
        return {}

    classified = {k: _canary_echo_classify(k) for k in found}
    match = next(
        (rank for rank in _CANARY_ECHO_RANK if rank in classified.values()),
        "foreign",
    )
    # Report the most interesting keys first so the cap never truncates
    # an `own` match in favour of a foreign one.
    ordered = sorted(found, key=lambda k: (_CANARY_ECHO_RANK.index(classified[k]), k))
    reported = ordered[:CANARY_ECHO_MAX_REPORTED]
    return {
        # The key id is an identifier, not a secret — it is what joins
        # this line back to the issuance that produced it. The matching
        # secret is deliberately never logged, and never matched on.
        "canaryEchoKeyIds": reported,
        "canaryEchoMatch": match,
        "canaryEchoIn": sorted({found[k] for k in reported}),
        "canaryEchoCount": len(found),
    }


# --- Render functions: (tracebit_response) -> bytes ---

def _aws(r: dict[str, object]) -> dict[str, str]:
    aws = r.get("aws") if isinstance(r, dict) else None
    if not isinstance(aws, dict):
        return {}
    # Single chokepoint: every renderer that embeds an AWS canary reads
    # it through here, so registering the key id at this point covers
    # them all without each having to remember to.
    key_id = aws.get("awsAccessKeyId")
    if isinstance(key_id, str):
        canary_echo_note_issued(key_id)
    return aws


def _fake_db_password() -> str:
    # Per-hit synthetic DB password for renderers that embed a plaintext
    # DB cred alongside an AWS canary. NOT a Tracebit-backed canary — a
    # replay against MySQL/Postgres won't fire an alert (Tracebit's
    # gitlab-username-password type only fires against their hosted gitlab
    # URL, which wouldn't be where a wp-config-style probe replays this).
    # The point is to avoid shipping a *fixed literal* across every sensor,
    # which turns into a farm-wide fingerprint.
    return secrets.token_urlsafe(16)


def _gitlab_creds(r: dict[str, object], canary_type: str) -> dict[str, object]:
    http = r.get("http") if isinstance(r, dict) else None
    if not isinstance(http, dict):
        return {}
    details = http.get(canary_type)
    if not isinstance(details, dict):
        return {}
    return details


def render_aws_credentials_ini(r: dict[str, object]) -> bytes:
    aws = _aws(r)
    return (
        "[default]\n"
        f"aws_access_key_id = {aws.get('awsAccessKeyId', '')}\n"
        f"aws_secret_access_key = {aws.get('awsSecretAccessKey', '')}\n"
        f"aws_session_token = {aws.get('awsSessionToken', '')}\n"
        "region = us-east-1\n"
    ).encode("utf-8")


def render_aws_env_dotenv(r: dict[str, object]) -> bytes:
    """`/aws.env` — dotenv-shaped AWS credentials export. Same canary
    surface as env-production but a focused 'just AWS' file: matches the
    scanner-dictionary shape where operators dump `aws sts
    get-session-token` output into a bare `aws.env` for a tool that
    couldn't read `~/.aws/credentials` directly. Harvesters grep raw
    bytes for the AKIA / SECRET pair."""
    aws = _aws(r)
    return (
        "# AWS credentials (exported)\n"
        f"AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}\n"
        f"AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}\n"
        f"AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}\n"
        "AWS_DEFAULT_REGION=us-east-1\n"
        "AWS_REGION=us-east-1\n"
    ).encode("utf-8")


def render_shell_rc(r: dict[str, object]) -> bytes:
    """`~/.bashrc` / `~/.profile` / `~/.zshrc` — an interactive shell rc
    with cloud credentials exported from it.

    This is asked for because it is where credentials genuinely end up:
    the documented fix for "the CLI can't see my keys" is an `export`
    line in the rc file, and it survives there long after the tool that
    needed it is gone. A harvester greps the raw bytes for the AKIA /
    secret pair exactly as it would in a `.env`, so the file only has to
    read like a real one — hence the ordinary interactive-shell
    boilerplate around the block that matters.

    Every secret-shaped value is per-hit: the AWS pair is the issued
    canary, the registry token is a per-hit synthetic. The non-secret
    filler (paths, aliases, region, registry host) is fixed, which is
    what makes the file look lived-in rather than generated.
    """
    aws = _aws(r)
    return (
        "# ~/.bashrc: executed by bash(1) for non-login shells.\n"
        "case $- in\n"
        "    *i*) ;;\n"
        "      *) return;;\n"
        "esac\n"
        "\n"
        "HISTCONTROL=ignoreboth\n"
        "HISTSIZE=1000\n"
        "HISTFILESIZE=2000\n"
        "shopt -s histappend checkwinsize\n"
        "\n"
        "if [ -x /usr/bin/dircolors ]; then\n"
        "    alias ls='ls --color=auto'\n"
        "    alias grep='grep --color=auto'\n"
        "fi\n"
        "alias ll='ls -alF'\n"
        "alias ..='cd ..'\n"
        "alias dc='docker compose'\n"
        "alias k='kubectl'\n"
        "\n"
        "export EDITOR=vim\n"
        "export LANG=en_US.UTF-8\n"
        "export PATH=\"$HOME/.local/bin:$HOME/bin:$PATH\"\n"
        "\n"
        "# deploy creds - aws cli wasn't picking up ~/.aws/credentials\n"
        f"export AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}\n"
        f"export AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}\n"
        f"export AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}\n"
        "export AWS_DEFAULT_REGION=us-east-1\n"
        "\n"
        f"export REGISTRY_TOKEN={_fake_db_password()}\n"
        "export REGISTRY_HOST=registry.internal.svc.cluster.local\n"
        "\n"
        "[ -f ~/.bash_aliases ] && . ~/.bash_aliases\n"
        "[ -f ~/.nvm/nvm.sh ] && . ~/.nvm/nvm.sh\n"
    ).encode("utf-8")


def render_aws_credentials_json(r: dict[str, object]) -> bytes:
    """`/aws.json` — JSON-shaped AWS credentials object matching the
    `aws sts get-session-token --output json` envelope (capitalised
    keys: `AccessKeyId` / `SecretAccessKey` / `SessionToken` /
    `Expiration`). Several boto3 session caches, container-credential
    helpers, and ad-hoc `aws sts` redirects drop this exact shape;
    scanner dictionaries walk `/aws.json` and `/credentials.json`
    expecting the IAM CLI envelope."""
    aws = _aws(r)
    body = {
        "Version": 1,
        "Credentials": {
            "AccessKeyId": aws.get("awsAccessKeyId", ""),
            "SecretAccessKey": aws.get("awsSecretAccessKey", ""),
            "SessionToken": aws.get("awsSessionToken", ""),
            "Expiration": aws.get("awsExpiration", "2099-12-31T23:59:59Z"),
        },
        "Region": "us-east-1",
    }
    return (json.dumps(body, indent=2) + "\n").encode("utf-8")


def _cloud_imds_expiry() -> str:
    """`Expiration` value for a role-credential envelope.

    Computed per response rather than fixed so the window always looks
    live. A stale-looking expiry is the cheapest possible tell that the
    envelope was canned.
    """
    expires_at = datetime.now(UTC) + timedelta(seconds=CLOUD_IMDS_CREDENTIAL_TTL_S)
    return expires_at.strftime("%Y-%m-%dT%H:%M:%SZ")


def render_imds_role_credentials(r: dict[str, object]) -> bytes:
    """Instance-metadata role-credential envelope.

    The exact document a metadata service returns for
    `.../iam/security-credentials/<role>`: a `Code`/`LastUpdated` header
    pair, the `AWS-HMAC` type marker, then the key/secret/token triple
    and an expiry. Credential-stealing modules parse these field names
    directly rather than grepping bytes, so the envelope has to be shaped
    correctly for the canary to be picked up at all.
    """
    aws = _aws(r)
    now = datetime.now(UTC)
    body = {
        "Code": "Success",
        "LastUpdated": now.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "Type": "AWS-HMAC",
        "AccessKeyId": aws.get("awsAccessKeyId", ""),
        "SecretAccessKey": aws.get("awsSecretAccessKey", ""),
        "Token": aws.get("awsSessionToken", ""),
        "Expiration": _cloud_imds_expiry(),
    }
    return (json.dumps(body, indent=2) + "\n").encode("utf-8")


def render_ecs_task_credentials(r: dict[str, object]) -> bytes:
    """Container credential-provider envelope.

    Differs from the instance-metadata document in two ways that a client
    implementing the container provider actually keys on: there is a
    `RoleArn` instead of a `Code`/`Type` pair, and the field is `Token`
    rather than `SessionToken`. The ARN is non-credential filler.
    """
    aws = _aws(r)
    body = {
        "RoleArn": f"arn:aws:iam::{_CLOUD_IMDS_FILLER_ACCOUNT}:role/{CLOUD_IMDS_ROLE_NAME}",
        "AccessKeyId": aws.get("awsAccessKeyId", ""),
        "SecretAccessKey": aws.get("awsSecretAccessKey", ""),
        "Token": aws.get("awsSessionToken", ""),
        "Expiration": _cloud_imds_expiry(),
    }
    return (json.dumps(body, indent=2) + "\n").encode("utf-8")


def render_k8s_secret_manifest(r: dict[str, object]) -> bytes:
    """Kubernetes multi-document YAML — Secret + ConfigMap + Deployment.
    The Secret carries the Tracebit AWS canary as base64-encoded `data:`
    values (real Secret shape: harvesters that base64-decode and grep for
    `AKIA*` pick it up). The Deployment block ALSO embeds the canary as
    plaintext `env:` values so raw-byte greppers that skip base64 blobs
    still see it. Non-credential filler (image, replicas, host, bucket
    name) is plausible-fixed; the only per-hit unique fields are the
    canary + a synthetic DB password."""
    aws = _aws(r)
    def _b64(s: str) -> str:
        return base64.b64encode(s.encode("utf-8")).decode("ascii")
    ak = aws.get("awsAccessKeyId", "")
    sk = aws.get("awsSecretAccessKey", "")
    st = aws.get("awsSessionToken", "")
    db_pw = _fake_db_password()
    return (
        "---\n"
        "apiVersion: v1\n"
        "kind: Secret\n"
        "metadata:\n"
        "  name: aws-credentials\n"
        "  namespace: default\n"
        "type: Opaque\n"
        "data:\n"
        f"  AWS_ACCESS_KEY_ID: {_b64(ak)}\n"
        f"  AWS_SECRET_ACCESS_KEY: {_b64(sk)}\n"
        f"  AWS_SESSION_TOKEN: {_b64(st)}\n"
        f"  DB_PASSWORD: {_b64(db_pw)}\n"
        "---\n"
        "apiVersion: v1\n"
        "kind: ConfigMap\n"
        "metadata:\n"
        "  name: app-config\n"
        "  namespace: default\n"
        "data:\n"
        "  AWS_DEFAULT_REGION: us-east-1\n"
        "  S3_BUCKET: internal-tools-prod\n"
        "  DB_HOST: db.internal\n"
        "  DB_NAME: prod\n"
        "---\n"
        "apiVersion: apps/v1\n"
        "kind: Deployment\n"
        "metadata:\n"
        "  name: internal-tools\n"
        "  namespace: default\n"
        "spec:\n"
        "  replicas: 3\n"
        "  selector:\n"
        "    matchLabels:\n"
        "      app: internal-tools\n"
        "  template:\n"
        "    metadata:\n"
        "      labels:\n"
        "        app: internal-tools\n"
        "    spec:\n"
        "      containers:\n"
        "      - name: web\n"
        "        image: internal/tools:prod\n"
        "        ports:\n"
        "        - containerPort: 8080\n"
        "        env:\n"
        "        - name: AWS_ACCESS_KEY_ID\n"
        f"          value: \"{ak}\"\n"
        "        - name: AWS_SECRET_ACCESS_KEY\n"
        f"          value: \"{sk}\"\n"
        "        - name: AWS_SESSION_TOKEN\n"
        f"          value: \"{st}\"\n"
        "        - name: AWS_DEFAULT_REGION\n"
        "          value: us-east-1\n"
        "        envFrom:\n"
        "        - secretRef:\n"
        "            name: aws-credentials\n"
        "        - configMapRef:\n"
        "            name: app-config\n"
    ).encode("utf-8")


def render_openapi_spec(
    r: dict[str, object],
    host: str,
    *,
    yaml: bool = False,
) -> bytes:
    """Plausible OpenAPI 3.0.3 document with the canary embedded in places
    a credential-scraping bot reliably grabs:

      - `components.securitySchemes.bearerAuth.x-example` — bearer token
        examples are scraped by every `openapi-credential-extractor`-class
        tool. We park the AWS access key here as a "dev bearer".
      - `servers[0].variables.adminApiKey.default` — server-variable
        defaults are scraped because Swagger UI dropdowns autocomplete
        them; the AWS secret key lands here.
      - `info.description` — many enumerators do a plain-text key=value
        sweep of the description for `AKIA…` patterns. Same access key
        repeated so substring matches inside markdown find it.

    All three slots point at the same Tracebit issuance. The fake `paths`
    surface advertises plausible admin/auth endpoints so a follow-up
    enumeration walks our handler set (login, /actuator/env, /admin/config).
    `yaml=True` returns the same content as YAML for `/openapi.yaml`."""
    aws = _aws(r)
    access_key = aws.get("awsAccessKeyId", "")
    secret_key = aws.get("awsSecretAccessKey", "")
    safe_host = (host or "api.example.com").split(":", 1)[0] or "api.example.com"
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "api.example.com"
    spec: dict[str, object] = {
        "openapi": "3.0.3",
        "info": {
            "title": "Internal Platform API",
            "version": "1.4.2",
            "description": (
                "Internal REST surface for the platform. Staging access "
                f"uses the bearer token `{access_key}` (rotates "
                "monthly via the deploy pipeline). Production keys are "
                "issued via SSO."
            ),
            "contact": {"name": "Platform Team", "email": "platform@" + safe_host},
        },
        "servers": [
            {
                "url": "https://{host}/api/v1",
                "description": "Production API",
                "variables": {
                    "host": {"default": safe_host},
                    "adminApiKey": {
                        "default": secret_key,
                        "description": "Admin API key (development default)",
                    },
                },
            },
            {
                "url": "https://staging." + safe_host + "/api/v1",
                "description": "Staging API",
            },
        ],
        "components": {
            "securitySchemes": {
                "bearerAuth": {
                    "type": "http",
                    "scheme": "bearer",
                    "bearerFormat": "JWT",
                    "x-example": access_key,
                },
                "apiKeyAuth": {
                    "type": "apiKey",
                    "in": "header",
                    "name": "X-Api-Key",
                    "x-example": access_key,
                },
                "basicAuth": {"type": "http", "scheme": "basic"},
            },
        },
        "security": [{"bearerAuth": []}],
        "paths": {
            "/auth/login": {
                "post": {
                    "summary": "Authenticate a user",
                    "requestBody": {
                        "required": True,
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "object",
                                    "properties": {
                                        "username": {"type": "string"},
                                        "password": {"type": "string"},
                                    },
                                    "required": ["username", "password"],
                                },
                            },
                        },
                    },
                    "responses": {
                        "200": {"description": "OK — returns bearer token"},
                        "401": {"description": "Invalid credentials"},
                    },
                },
            },
            "/auth/token": {
                "post": {
                    "summary": "Exchange refresh token",
                    "security": [{"bearerAuth": []}],
                    "responses": {"200": {"description": "OK"}},
                },
            },
            "/admin/users": {
                "get": {
                    "summary": "List users (admin)",
                    "security": [{"bearerAuth": []}],
                    "responses": {
                        "200": {"description": "OK"},
                        "403": {"description": "Forbidden"},
                    },
                },
            },
            "/admin/config": {
                "get": {
                    "summary": "Fetch runtime configuration",
                    "security": [{"bearerAuth": []}],
                    "responses": {"200": {"description": "OK"}},
                },
            },
            "/actuator/env": {
                "get": {
                    "summary": "Spring Boot Actuator env dump",
                    "responses": {"200": {"description": "OK"}},
                },
            },
            "/healthz": {
                "get": {
                    "summary": "Health probe",
                    "responses": {"200": {"description": "OK"}},
                },
            },
        },
    }
    if yaml:
        return _openapi_spec_to_yaml(spec).encode("utf-8")
    return json.dumps(spec, indent=2).encode("utf-8")


def _openapi_spec_to_yaml(spec: dict[str, object]) -> str:
    """Tiny stdlib-only JSON→YAML rendering of the spec dict. Good enough
    for a credential-scraper to grep the `AKIA…` substring out — full PyYAML
    semantics aren't required and bringing PyYAML in for one renderer would
    break flux's stdlib-only invariant."""
    def emit(value: object, indent: int = 0) -> list[str]:
        pad = "  " * indent
        out: list[str] = []
        if isinstance(value, dict):
            if not value:
                return ["{}"]
            for k, v in value.items():
                key = str(k)
                if isinstance(v, (dict, list)) and v:
                    out.append(f"{pad}{key}:")
                    nested = emit(v, indent + 1)
                    out.extend(nested)
                else:
                    rendered = _yaml_scalar(v)
                    out.append(f"{pad}{key}: {rendered}")
            return out
        if isinstance(value, list):
            if not value:
                return [f"{pad}[]"]
            for item in value:
                if isinstance(item, (dict, list)) and item:
                    nested = emit(item, indent + 1)
                    if nested:
                        nested[0] = f"{pad}- " + nested[0].lstrip()
                        out.extend(nested)
                else:
                    out.append(f"{pad}- {_yaml_scalar(item)}")
            return out
        return [f"{pad}{_yaml_scalar(value)}"]
    return "\n".join(emit(spec)) + "\n"


def _yaml_scalar(v: object) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if v is None:
        return "null"
    if isinstance(v, (int, float)):
        return str(v)
    s = str(v)
    if any(c in s for c in ":#\n\"'{}[],&*!|>%@`"):
        return json.dumps(s)
    return s


def render_swagger_ui_html(host: str, spec_url: str = "/swagger.json") -> bytes:
    """Stock Swagger UI bootstrap. References /swagger.json so a scanner
    that fetches the UI then follows the spec lands on `_handle_openapi_swagger`
    again with `spec-json` and receives the canary-bearing document."""
    host = _appliance_display_host(host, "example.com")
    safe_host = (host or "").split(":", 1)[0]
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host)
    title_host = safe_host or "API"
    return (
        "<!DOCTYPE html>\n"
        "<html lang=\"en\">\n"
        "<head>\n"
        "  <meta charset=\"UTF-8\">\n"
        f"  <title>Swagger UI — {title_host}</title>\n"
        "  <link rel=\"stylesheet\" type=\"text/css\" "
        "href=\"https://unpkg.com/swagger-ui-dist@5/swagger-ui.css\">\n"
        "</head>\n"
        "<body>\n"
        "  <div id=\"swagger-ui\"></div>\n"
        "  <script src=\"https://unpkg.com/swagger-ui-dist@5/swagger-ui-bundle.js\"></script>\n"
        "  <script>\n"
        "    window.onload = function() {\n"
        "      window.ui = SwaggerUIBundle({\n"
        f"        url: \"{spec_url}\",\n"
        "        dom_id: \"#swagger-ui\",\n"
        "        deepLinking: true,\n"
        "        presets: [SwaggerUIBundle.presets.apis],\n"
        "        layout: \"BaseLayout\"\n"
        "      });\n"
        "    };\n"
        "  </script>\n"
        "</body>\n"
        "</html>\n"
    ).encode("utf-8")


def render_redoc_html(host: str, spec_url: str = "/openapi.json") -> bytes:
    """ReDoc bootstrap variant — same role as Swagger UI but the alternative
    renderer scanners check when Swagger UI 404s. Points at /openapi.json."""
    host = _appliance_display_host(host, "example.com")
    safe_host = (host or "").split(":", 1)[0]
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host)
    title_host = safe_host or "API"
    return (
        "<!DOCTYPE html>\n"
        "<html>\n"
        "<head>\n"
        "  <meta charset=\"utf-8\">\n"
        f"  <title>API Documentation — {title_host}</title>\n"
        "  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
        "</head>\n"
        "<body>\n"
        f"  <redoc spec-url=\"{spec_url}\"></redoc>\n"
        "  <script src=\"https://cdn.jsdelivr.net/npm/redoc@next/bundles/redoc.standalone.js\"></script>\n"
        "</body>\n"
        "</html>\n"
    ).encode("utf-8")


def render_graphiql_html(host: str, endpoint: str) -> bytes:
    """GraphiQL bootstrap page — the in-browser IDE bundled with most
    GraphQL servers (Apollo, graphql-yoga, graphene). Scanners that
    probe `/graphql` with a plain `GET` and check the response title
    accept this as proof the host is a GraphQL endpoint.

    The endpoint URL embedded in the bootstrap is per-request (the
    same path the scanner hit) so a multi-variant fanout sees
    consistent state.
    """
    host = _appliance_display_host(host, "example.com")
    safe_host = (host or "").split(":", 1)[0]
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "graphql"
    safe_endpoint = re.sub(r"[^a-zA-Z0-9/_\-.]", "", endpoint or "/graphql") or "/graphql"
    return (
        "<!DOCTYPE html>\n"
        "<html>\n"
        "<head>\n"
        "  <meta charset=\"utf-8\">\n"
        f"  <title>GraphiQL — {safe_host}</title>\n"
        "  <link href=\"https://unpkg.com/graphiql/graphiql.min.css\" rel=\"stylesheet\" />\n"
        "</head>\n"
        "<body style=\"margin: 0;\">\n"
        "  <div id=\"graphiql\" style=\"height: 100vh;\"></div>\n"
        "  <script crossorigin src=\"https://unpkg.com/react@17/umd/react.production.min.js\"></script>\n"
        "  <script crossorigin src=\"https://unpkg.com/react-dom@17/umd/react-dom.production.min.js\"></script>\n"
        "  <script crossorigin src=\"https://unpkg.com/graphiql/graphiql.min.js\"></script>\n"
        "  <script>\n"
        f"    const fetcher = GraphiQL.createFetcher({{ url: '{safe_endpoint}' }});\n"
        "    ReactDOM.render(React.createElement(GraphiQL, { fetcher }), document.getElementById('graphiql'));\n"
        "  </script>\n"
        "</body>\n"
        "</html>\n"
    ).encode("utf-8")


def render_graphql_introspection_response() -> bytes:
    """Plausible introspection response covering the field names the
    credential-scraper population walks (`apiToken`, `awsAccessKeyId`,
    `secretKey`, …). No canary lives in this response — the canary is
    issued one hop later when the scraper actually queries those
    fields with a data query against `currentUser` / `viewer`.

    Schema shape:
      Query.viewer: User
      Query.currentUser: User
      Query.users: [User!]!
      User.id / username / email / apiToken / accessToken /
        refreshToken / awsAccessKeyId / webhookSecret / role
      Mutation.login(username, password): AuthPayload
      Mutation.signIn(email, password): AuthPayload
      Mutation.createUser(input: CreateUserInput!): User
      AuthPayload.token / refreshToken / user: User
    """
    payload = {
        "data": {
            "__schema": {
                "queryType": {"name": "Query"},
                "mutationType": {"name": "Mutation"},
                "subscriptionType": None,
                "types": [
                    {
                        "kind": "OBJECT", "name": "Query",
                        "fields": [
                            {"name": "viewer", "type": {"kind": "OBJECT", "name": "User", "ofType": None}},
                            {"name": "currentUser", "type": {"kind": "OBJECT", "name": "User", "ofType": None}},
                            {"name": "users", "type": {"kind": "LIST", "name": None, "ofType": {"kind": "OBJECT", "name": "User"}}},
                            {"name": "user", "type": {"kind": "OBJECT", "name": "User", "ofType": None}},
                            {"name": "node", "type": {"kind": "INTERFACE", "name": "Node", "ofType": None}},
                        ],
                    },
                    {
                        "kind": "OBJECT", "name": "Mutation",
                        "fields": [
                            {"name": "login", "type": {"kind": "OBJECT", "name": "AuthPayload", "ofType": None}},
                            {"name": "signIn", "type": {"kind": "OBJECT", "name": "AuthPayload", "ofType": None}},
                            {"name": "signUp", "type": {"kind": "OBJECT", "name": "AuthPayload", "ofType": None}},
                            {"name": "createUser", "type": {"kind": "OBJECT", "name": "User", "ofType": None}},
                            {"name": "resetPassword", "type": {"kind": "SCALAR", "name": "Boolean", "ofType": None}},
                            {"name": "refreshToken", "type": {"kind": "OBJECT", "name": "AuthPayload", "ofType": None}},
                        ],
                    },
                    {
                        "kind": "OBJECT", "name": "User",
                        "fields": [
                            {"name": "id", "type": {"kind": "NON_NULL", "name": None, "ofType": {"kind": "SCALAR", "name": "ID"}}},
                            {"name": "username", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "email", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "role", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "apiToken", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "accessToken", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "refreshToken", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "awsAccessKeyId", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "awsSecretAccessKey", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "secretKey", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "webhookSecret", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "createdAt", "type": {"kind": "SCALAR", "name": "DateTime", "ofType": None}},
                        ],
                    },
                    {
                        "kind": "OBJECT", "name": "AuthPayload",
                        "fields": [
                            {"name": "token", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "refreshToken", "type": {"kind": "SCALAR", "name": "String", "ofType": None}},
                            {"name": "user", "type": {"kind": "OBJECT", "name": "User", "ofType": None}},
                        ],
                    },
                    {
                        "kind": "INPUT_OBJECT", "name": "CreateUserInput",
                        "inputFields": [
                            {"name": "username", "type": {"kind": "NON_NULL", "name": None, "ofType": {"kind": "SCALAR", "name": "String"}}},
                            {"name": "email", "type": {"kind": "NON_NULL", "name": None, "ofType": {"kind": "SCALAR", "name": "String"}}},
                            {"name": "password", "type": {"kind": "NON_NULL", "name": None, "ofType": {"kind": "SCALAR", "name": "String"}}},
                        ],
                    },
                    {"kind": "SCALAR", "name": "String", "fields": None},
                    {"kind": "SCALAR", "name": "ID", "fields": None},
                    {"kind": "SCALAR", "name": "Boolean", "fields": None},
                    {"kind": "SCALAR", "name": "DateTime", "fields": None},
                ],
            }
        }
    }
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_graphql_user_canary(r: dict[str, object]) -> bytes:
    """Data response to a `currentUser { apiToken ... }`-shape query.

    Embeds the Tracebit AWS canary as the `apiToken` / `accessToken` /
    `awsAccessKeyId` / `awsSecretAccessKey` values. A scraper that
    walked the introspection schema and is now harvesting the named
    credential fields lifts an AWS-replayable canary regardless of
    which field name it scraped. The `refreshToken` / `webhookSecret`
    are per-hit random synthetics — never fixed literals.
    """
    aws = _aws(r)
    access_key = aws.get("awsAccessKeyId", "") or ""
    secret_key = aws.get("awsSecretAccessKey", "") or ""
    session_token = aws.get("awsSessionToken", "") or ""
    refresh = secrets.token_urlsafe(32)
    webhook = secrets.token_urlsafe(24)
    payload = {
        "data": {
            "currentUser": {
                "id": "1",
                "username": "admin",
                "email": "admin@example.com",
                "role": "ADMIN",
                "apiToken": access_key,
                "accessToken": access_key,
                "refreshToken": refresh,
                "awsAccessKeyId": access_key,
                "awsSecretAccessKey": secret_key,
                "awsSessionToken": session_token,
                "secretKey": secret_key,
                "webhookSecret": webhook,
            }
        }
    }
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_graphql_auth_payload(r: dict[str, object]) -> bytes:
    """Response to a successful `mutation login(...) { token ... }`.

    The `token` is a Tracebit AWS access key — credential-stuffing
    fleets that capture session tokens for replay get an AWS-replayable
    canary. The `refreshToken` is a per-hit synthetic so it doesn't
    repeat across the fleet.
    """
    aws = _aws(r)
    access_key = aws.get("awsAccessKeyId", "") or ""
    refresh = secrets.token_urlsafe(32)
    payload = {
        "data": {
            "login": {
                "token": access_key,
                "refreshToken": refresh,
                "user": {
                    "id": "1",
                    "username": "admin",
                    "email": "admin@example.com",
                    "role": "ADMIN",
                },
            }
        }
    }
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_graphql_generic_error(message: str = "Syntax Error: Unexpected Name") -> bytes:
    """Error envelope returned for unparseable / unknown queries.

    Real graphql-core errors take this exact shape: `{"errors": [{...}]}`
    no `data` key. The message line is plausible — `graphql-core` emits
    `Syntax Error: Unexpected Name "..."` on a malformed query, and
    Apollo emits the same prefix.
    """
    payload = {"errors": [{"message": message[:240], "locations": [{"line": 1, "column": 1}]}]}
    return json.dumps(payload, separators=(",", ":")).encode("utf-8")


def render_fake_passwd() -> bytes:
    """Static `/etc/passwd`-shape body. Same content as the webshell trap's
    `cat /etc/passwd` simulation — kept identical so a scanner that probes
    both endpoints sees a consistent host."""
    return (
        "root:x:0:0:root:/root:/bin/bash\n"
        "daemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\n"
        "bin:x:2:2:bin:/bin:/usr/sbin/nologin\n"
        "sys:x:3:3:sys:/dev:/usr/sbin/nologin\n"
        "www-data:x:33:33:www-data:/var/www:/usr/sbin/nologin\n"
        "mysql:x:112:116:MySQL Server,,,:/nonexistent:/bin/false\n"
    ).encode("utf-8")


def render_stock_nginx_conf() -> bytes:
    """Stock distro `/etc/nginx/nginx.conf`. Deliberately the unmodified
    packaged file — the interesting thing about a scanner reading it is
    that it asked, not what it found. Anything bespoke here would leak
    real deployment shape, so the body carries no vhost, no upstream, no
    path that isn't in the distribution default."""
    return (
        "user www-data;\n"
        "worker_processes auto;\n"
        "pid /run/nginx.pid;\n"
        "include /etc/nginx/modules-enabled/*.conf;\n"
        "\n"
        "events {\n"
        "\tworker_connections 768;\n"
        "}\n"
        "\n"
        "http {\n"
        "\tsendfile on;\n"
        "\ttcp_nopush on;\n"
        "\ttypes_hash_max_size 2048;\n"
        "\tserver_tokens off;\n"
        "\n"
        "\tinclude /etc/nginx/mime.types;\n"
        "\tdefault_type application/octet-stream;\n"
        "\n"
        "\tssl_protocols TLSv1.2 TLSv1.3;\n"
        "\tssl_prefer_server_ciphers on;\n"
        "\n"
        "\taccess_log /var/log/nginx/access.log;\n"
        "\terror_log /var/log/nginx/error.log;\n"
        "\n"
        "\tgzip on;\n"
        "\n"
        "\tinclude /etc/nginx/conf.d/*.conf;\n"
        "\tinclude /etc/nginx/sites-enabled/*;\n"
        "}\n"
    ).encode("utf-8")


def render_printenv_dump(r: dict[str, object], *, host: str = "") -> bytes:
    """Plausible `printenv`/CGI-environment block with AWS_* values bound to
    a Tracebit canary. Synthesised non-credential context (hostname, PWD,
    PATH, USER) keeps the shape recognisable; the canary lives in AWS_*
    only — a replay against AWS fires Tracebit."""
    aws = _aws(r)
    safe_host = (host or "web-01").split(":", 1)[0] or "web-01"
    safe_host = re.sub(r"[^a-zA-Z0-9._-]", "", safe_host) or "web-01"
    db_pw = _fake_db_password()
    lines = [
        "PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
        f"HOSTNAME={safe_host}",
        "USER=www-data",
        "HOME=/var/www",
        "PWD=/var/www/html",
        "SHELL=/bin/bash",
        "LANG=C.UTF-8",
        "SERVER_SOFTWARE=Apache/2.4.41 (Ubuntu)",
        "SERVER_NAME=" + safe_host,
        "SERVER_PORT=443",
        "GATEWAY_INTERFACE=CGI/1.1",
        "REQUEST_METHOD=GET",
        f"AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}",
        f"AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}",
        f"AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}",
        "AWS_DEFAULT_REGION=us-east-1",
        f"DATABASE_URL=postgres://app:{db_pw}@db.internal:5432/app_prod",
        "RAILS_ENV=production",
        "NODE_ENV=production",
    ]
    return ("\n".join(lines) + "\n").encode("utf-8")


def render_aws_config_ini(r: dict[str, object]) -> bytes:
    # `~/.aws/config` is the sibling of `~/.aws/credentials`: region / output
    # format / profile definitions. Some SDK setups stash the access key here
    # too (in-profile `aws_access_key_id`), so embedding the canary is valid.
    aws = _aws(r)
    return (
        "[default]\n"
        "region = us-east-1\n"
        "output = json\n"
        f"aws_access_key_id = {aws.get('awsAccessKeyId', '')}\n"
        f"aws_secret_access_key = {aws.get('awsSecretAccessKey', '')}\n"
        "\n"
        "[profile prod]\n"
        "region = us-east-1\n"
        "output = json\n"
        f"aws_session_token = {aws.get('awsSessionToken', '')}\n"
    ).encode("utf-8")


def render_terraform_tfstate(r: dict[str, object]) -> bytes:
    # `terraform.tfstate` is the JSON snapshot Terraform writes when applying
    # against a non-remote backend. Provider credentials and resource IDs end
    # up in plaintext under `resources[].instances[].attributes`, so an
    # exposed tfstate is a one-shot AWS/GCP/Azure credential leak — exactly
    # the value scanners are after.
    #
    # Two design choices worth a comment:
    #
    # 1. `lineage` (uuid) and `serial` (monotonic int) are emitted random
    #    per-hit. Real tfstates have a stable lineage per state file; here
    #    they vary per request because every fetch should look like an
    #    independent leak (a fixed lineage across the fleet would itself be
    #    a fingerprint).
    #
    # 2. The canary AWS access key + secret are placed both in an
    #    `aws_iam_access_key` resource (where Terraform actually stores them)
    #    and in a top-level `outputs` block. Some scrapers extract via
    #    `outputs[].value`, others walk `resources[]`; covering both shapes
    #    means a field-keyed harvester catches the canary either way.
    aws = _aws(r)
    access_key = aws.get("awsAccessKeyId", "")
    secret_key = aws.get("awsSecretAccessKey", "")
    state = {
        "version": 4,
        "terraform_version": "1.7.5",
        "serial": secrets.randbelow(900) + 100,
        "lineage": str(uuid.uuid4()),
        "outputs": {
            "deploy_access_key_id": {
                "value": access_key,
                "type": "string",
            },
            "deploy_secret_access_key": {
                "value": secret_key,
                "type": "string",
                "sensitive": True,
            },
        },
        "resources": [
            {
                "mode": "managed",
                "type": "aws_iam_access_key",
                "name": "deploy",
                "provider": "provider[\"registry.terraform.io/hashicorp/aws\"]",
                "instances": [
                    {
                        "schema_version": 0,
                        "attributes": {
                            "id": access_key,
                            "user": "deploy",
                            "secret": secret_key,
                            "status": "Active",
                            "create_date": "2024-08-01T00:00:00Z",
                            "pgp_key": "",
                            "key_fingerprint": "",
                        },
                        "sensitive_attributes": [],
                    },
                ],
            },
            {
                "mode": "managed",
                "type": "aws_s3_bucket",
                "name": "primary",
                "provider": "provider[\"registry.terraform.io/hashicorp/aws\"]",
                "instances": [
                    {
                        "schema_version": 0,
                        "attributes": {
                            "id": "app-prod-data",
                            "bucket": "app-prod-data",
                            "region": "us-east-1",
                            "arn": "arn:aws:s3:::app-prod-data",
                        },
                        "sensitive_attributes": [],
                    },
                ],
            },
        ],
        "check_results": None,
    }
    return (json.dumps(state, indent=2) + "\n").encode("utf-8")


# ---- Niche cloud-provider credential files --------------------------------
# A growing population of credential-scanner tools enumerates config files
# for smaller cloud providers alongside mainstream AWS/GCP/Azure paths.
# Each renderer below produces a format-accurate file with the Tracebit
# AWS canary embedded in the field a credential-extractor would grab.


def render_oci_config(r: dict[str, object]) -> bytes:
    aws = _aws(r)
    return (
        "[DEFAULT]\n"
        "user=ocid1.user.oc1..aaaaaaaaexample\n"
        "fingerprint=ab:cd:ef:01:23:45:67:89:ab:cd:ef:01:23:45:67:89\n"
        f"key_file=~/.oci/oci_api_key.pem\n"
        "tenancy=ocid1.tenancy.oc1..aaaaaaaaexample\n"
        "region=us-ashburn-1\n"
        f"pass_phrase={aws.get('awsSecretAccessKey', '')}\n"
    ).encode("utf-8")


def render_oci_api_key_pem(r: dict[str, object]) -> bytes:
    aws = _aws(r)
    tag = aws.get("awsAccessKeyId", "") + aws.get("awsSecretAccessKey", "")
    fake_b64 = base64.b64encode(tag.encode() + secrets.token_bytes(128)).decode()
    lines = [fake_b64[i:i + 64] for i in range(0, len(fake_b64), 64)]
    return (
        "-----BEGIN RSA PRIVATE KEY-----\n"
        + "\n".join(lines) + "\n"
        "-----END RSA PRIVATE KEY-----\n"
    ).encode("utf-8")


