def render_serverless_yml(r: dict[str, object]) -> bytes:
    """Serverless Framework service definition.

    `provider.environment` is the block that matters: it is the
    documented place to put runtime secrets, so a committed
    `serverless.yml` that was never moved to SSM carries them in clear.
    """
    aws = _aws(r)
    return (
        "service: internal-tools-api\n"
        "frameworkVersion: '3'\n\n"
        "provider:\n"
        "  name: aws\n"
        "  runtime: nodejs20.x\n"
        "  region: us-east-1\n"
        "  stage: prod\n"
        "  environment:\n"
        "    NODE_ENV: production\n"
        f"    AWS_ACCESS_KEY_ID: {aws.get('awsAccessKeyId', '')}\n"
        f"    AWS_SECRET_ACCESS_KEY: {aws.get('awsSecretAccessKey', '')}\n"
        f"    AWS_SESSION_TOKEN: {aws.get('awsSessionToken', '')}\n"
        f"    DATABASE_URL: postgres://app:{_fake_db_password()}@db.internal:5432/app\n"
        "  iam:\n"
        "    role:\n"
        "      statements:\n"
        "        - Effect: Allow\n"
        "          Action: ['s3:GetObject', 's3:PutObject']\n"
        "          Resource: 'arn:aws:s3:::internal-tools-prod-userfiles/*'\n\n"
        "functions:\n"
        "  api:\n"
        "    handler: src/handler.main\n"
        "    events:\n"
        "      - httpApi: '*'\n"
    ).encode("utf-8")


def render_docker_config(r: dict[str, object]) -> bytes:
    aws = _aws(r)
    import base64
    auth = base64.b64encode(
        f"AWS:{aws.get('awsSecretAccessKey', '')}".encode("utf-8"),
    ).decode("ascii")
    return json.dumps({
        "auths": {
            "123456789012.dkr.ecr.us-east-1.amazonaws.com": {
                "auth": auth,
                "identitytoken": aws.get("awsSessionToken", ""),
            },
        },
        "credsStore": "ecr-login",
        "HttpHeaders": {"User-Agent": "Docker-Client/24.0.7 (linux)"},
    }, indent=2).encode("utf-8")


