        f"<tr><th>AWS_SECRET_ACCESS_KEY</th><td>{sk}</td></tr>"
        f"<tr><th>AWS_SESSION_TOKEN</th><td>{st}</td></tr>"
        "<tr><th>AWS_DEFAULT_REGION</th><td>us-east-1</td></tr>"
        "<tr><th>S3_BUCKET</th><td>prod-uploads</td></tr>"
