            "/root/.kube/config",
            "/home/.kube/config",
            "/home/ubuntu/.kube/config",
            "/home/runner/.kube/config",
            "/home/ec2-user/.kube/config",
            "/home/admin/.kube/config",
            "/home/app/.kube/config",
            "/home/node/.kube/config",
            "/home/deploy/.kube/config",
            "/home/www-data/.kube/config",
