            "/app/vercel.json",
            "/var/task/vercel.json",
            "/usr/src/app/vercel.json",
            "/srv/app/vercel.json",
            "/home/node/app/vercel.json",
            "/opt/app/vercel.json",
            "/workspace/vercel.json",
