            "/remote-sync.json",
            "/ftp-sync.json",
            "/deployment-config.json",
            "/ftpsync.settings",
            "/.ftpsync.settings",
            "/.vscode/remote-sync.json",
            "/.vscode/deployment-config.json",
            "/deploy-config.json",
            "/deploy.json",
