            "/key.pem",
            "/privkey.pem",
            "/ssl/server.key",
            "/ssl/localhost.key",
            "/ssl/private.key",
            "/ssl/key.pem",
            "/ssl/privkey.pem",
            "/certs/server.key",
            "/certs/privkey.pem",
            "/private/server.key",
