def _render_nginx_status() -> bytes:
    up = max(_observability_uptime_s(), 1)
    accepts = 41 * up + 1187
    return (
        "Active connections: 17 \n"
        "server accepts handled requests\n"
        f" {accepts} {accepts} {accepts * 3} \n"
        "Reading: 0 Writing: 4 Waiting: 13 \n"
    ).encode("utf-8")


def _render_elmah_html(host: str) -> tuple[bytes, str]:
    """ELMAH error log. The top entry's detail text carries a connection
    string whose password is a per-hit synthetic — never a fixed literal,
    which across a fleet would be one shared string and zero detection."""
    password = _fake_db_password()
    app = OBSERVABILITY_APP_NAME
    conn = (
        f"Server={OBSERVABILITY_DB_HOST};Database={app};"
        f"User Id={app}_svc;Password={password};MultipleActiveResultSets=true"
    )
    body = (
        "<!DOCTYPE html><html><head><title>Error log for "
        f"{html.escape(host)}</title></head><body>"
        f"<h1>Error Log for {html.escape(app)} (on {html.escape(host)})</h1>"
        "<p>Errors 1 to 3 of 3</p>"
        "<table border=\"1\" cellspacing=\"0\"><tr><th>Host</th><th>Code</th>"
        "<th>Type</th><th>Error</th><th>User</th><th>Date</th></tr>"
        "<tr><td>web-prod-02</td><td>500</td><td>SqlException</td>"
        "<td>A network-related or instance-specific error occurred while "
        "establishing a connection to SQL Server. "
        f"ConnectionString: {html.escape(conn)}</td>"
        "<td>svc_report</td><td>2 minutes ago</td></tr>"
        "<tr><td>web-prod-02</td><td>500</td><td>InvalidOperationException</td>"
        f"<td>Unable to resolve service for type 'ICacheClient' "
        f"({html.escape(OBSERVABILITY_CACHE_HOST)}:6379)</td>"
        "<td>svc_report</td><td>3 hours ago</td></tr>"
        "<tr><td>web-prod-02</td><td>404</td><td>HttpException</td>"
        "<td>The file '/admin/config.aspx' does not exist.</td>"
        "<td>anonymous</td><td>yesterday</td></tr>"
        "</table></body></html>\n"
    ).encode("utf-8")
    return body, conn


def _render_profiler_index(base: str) -> bytes:
    app = OBSERVABILITY_APP_NAME
    rows = "".join(
        f"<tr><td><a href=\"{base}/_profiler/{token}\">{token}</a></td>"
        f"<td>200</td><td>GET</td><td>{url}</td></tr>"
        for token, url in (
            ("a3f19c", "/api/v1/payments"),
            ("b71e40", "/actuator/env"),
            ("c02d8a", "/login"),
        )
    )
    return (
        "<!DOCTYPE html><html><head><title>Symfony Profiler</title></head>"
        f"<body><h1>Profiler — {html.escape(app)} (env: prod, debug: true)</h1>"
        "<p>Latest requests. Configuration is loaded from "
        "<code>config/packages/prod/framework.yaml</code> and "
        "<code>.env.local</code>.</p>"
        "<table><tr><th>Token</th><th>Status</th><th>Method</th><th>URL</th></tr>"
        f"{rows}</table></body></html>\n"
    ).encode("utf-8")


async def _handle_observability(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    kind: str,
) -> web.Response:
    """Serve one operational-endpoint disclosure.

    Issues no canary on any branch — see the config block. The bodies
    name follow-up targets that have their own canary-backed handlers,
    so the spend happens when a lead is followed rather than when the
    surface is swept.
    """
    host = str(log_context.get("host", "")) or "localhost"
    base = ""
    extra: dict[str, object] = {}
    server_header: str | None = None

    if kind == "actuator-index":
        body = _render_actuator_index(base)
        content_type = "application/vnd.spring-boot.actuator.v3+json"
        extra["obsAdvertised"] = len(_ACTUATOR_INDEX_ENDPOINTS)
    elif kind == "metrics":
        body = _render_prometheus_metrics()
        content_type = "text/plain; version=0.0.4; charset=utf-8"
    elif kind == "actuator-info":
        body = _render_actuator_info()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "actuator-metrics":
        body = _render_actuator_metrics_names()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
        extra["obsMeterCount"] = len(_ACTUATOR_METER_NAMES)
    elif kind == "actuator-metric":
        meter = path.split("?", 1)[0][len("/actuator/metrics/"):]
        body = _render_actuator_metric(meter)
        content_type = "application/vnd.spring-boot.actuator.v3+json"
        # The name a client comes back for is the measurement: it says
        # whether the meter index was read or the name was guessed.
        extra["obsMeterName"] = meter[:120]
        extra["obsMeterKnown"] = meter in _ACTUATOR_METER_NAMES
    elif kind == "actuator-beans":
        body = _render_actuator_beans()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "actuator-loggers":
        body = _render_actuator_loggers()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "actuator-auditevents":
        body = _render_actuator_auditevents()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "actuator-sessions":
        body = _render_actuator_sessions()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "expvar":
        body = _render_expvar()
        content_type = "application/json; charset=utf-8"
    elif kind == "health":
        body = _render_health_json()
        content_type = "application/vnd.spring-boot.actuator.v3+json"
    elif kind == "server-info":
        body = _render_server_info_html(host)
        content_type = "text/html; charset=utf-8"
        server_header = SERVER_STATUS_APACHE_VERSION
    elif kind == "nginx-status":
        body = _render_nginx_status()
        content_type = "text/plain; charset=utf-8"
        server_header = "nginx/1.24.0"
    elif kind == "elmah":
        body, conn = _render_elmah_html(host)
        content_type = "text/html; charset=utf-8"
        server_header = "Microsoft-IIS/10.0"
        # Log the synthetic so a later replay attempt can be tied back to
        # the hit that handed it out. The password itself is per-hit.
        extra["obsConnectionString"] = conn
    else:  # profiler-index
        body = _render_profiler_index(base)
        content_type = "text/html; charset=utf-8"

    headers = {"Content-Type": content_type, "Cache-Control": "no-store"}
    if server_header:
        headers["Server"] = server_header

    append_log({
        **log_context,
        "status": 200,
        "result": f"observability-{kind}",
        "obsKind": kind,
        "obsPath": path.split("?", 1)[0],
        "bytes": len(body),
        **extra,
    })
    return web.Response(status=200, body=body, headers=headers)


async def _handle_geoserver(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    lpath = path.lower()
    method = request.method
    host = str(log_context.get("host", ""))
    query = str(log_context.get("query", "") or "")

    body_preview = ""
    if request_body:
        try:
            body_preview = request_body[:512].decode("utf-8", errors="replace")
        except UnicodeDecodeError:
            body_preview = ""

    has_ognl = _geoserver_has_ognl(query, body_preview)

    log_extra: dict[str, object] = {
        "geoserverPath": path,
        "geoserverMethod": method,
        "geoserverHasOgnl": has_ognl,
    }
    if has_ognl:
        # Truncate aggressively: a single OGNL payload can run multi-KB and
        # the existing log fields stay compact.
        log_extra["geoserverPayloadPreview"] = (query + " | " + body_preview)[:400]

    # /geoserver and /geoserver/ -> 302 to /geoserver/web/. Real GeoServer
    # redirects this way, and a 302 keeps banner-grab fleets happy without
    # rendering any content.
    if lpath in {"/geoserver", "/geoserver/"}:
        append_log({
            **log_context,
            "status": 302,
            "result": "geoserver-redirect-root",
            **log_extra,
            "bytes": 0,
        })
        return web.Response(
            status=302,
            body=b"",
            headers={"Location": "/geoserver/web/", "Cache-Control": "no-store"},
        )

    # /geoserver/index.html and the /geoserver/web/ admin shell.
    if lpath == "/geoserver/index.html" or lpath.startswith("/geoserver/web"):
        # Distinguish the AboutGeoServerPage CVE trigger from the generic
        # admin shell so analysis can grep for it directly.
        if "aboutgeoserverpage" in lpath:
            result_tag = "geoserver-about-page"
            body = render_geoserver_about(host, GEOSERVER_VERSION)
        else:
            result_tag = "geoserver-web-landing"
            body = render_geoserver_landing(host, GEOSERVER_VERSION)
        append_log({
            **log_context,
            "status": 200,
            "result": result_tag,
            **log_extra,
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={
                "Content-Type": "text/html; charset=utf-8",
                "Cache-Control": "no-store",
            },
        )

    # The landing page's own Spring Security submit target. Until it was
    # answered, the admin login form rendered and everything posted to it
    # fell through to a 404 — GeoServer's default `admin` account is a
    # standing credential-stuffing target, so that was the submission
    # most worth having.
    if lpath == "/geoserver/j_spring_security_check" and request.method != "POST":
        # Spring Security registers this filter for POST only; a non-POST
        # probe gets the admin shell rather than a credential-post row.
        body = render_geoserver_landing(host, GEOSERVER_VERSION)
        append_log({
            **log_context, "status": 200, "result": "geoserver-web-landing",
            **log_extra, "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={"Content-Type": "text/html; charset=utf-8",
                     "Cache-Control": "no-store"},
        )

    if lpath == "/geoserver/j_spring_security_check":
        creds = extract_geoserver_login_creds(
            request.headers.get("Content-Type", ""), request_body,
        )
        body = render_geoserver_landing(host, GEOSERVER_VERSION)
        append_log({
            **log_context,
            "status": 200,
            "result": "geoserver-credential-post",
            **log_extra,
            "geoserverUsername": creds.get("username", ""),
            "geoserverHasPwd": creds.get("hasPwd", "") == "true",
            **({"geoserverPwdLen": creds["pwdLen"]} if creds.get("pwdLen") else {}),
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={
                "Content-Type": "text/html; charset=utf-8",
                "Cache-Control": "no-store",
            },
        )

    # Wicket-served stylesheet the landing page names for itself.
    if lpath.startswith("/geoserver/wicket/resource/") and lpath.endswith(".css"):
        css = render_geoserver_screen_css()
        append_log({
            **log_context,
            "status": 200,
            "result": "geoserver-asset",
            **log_extra,
            "bytes": len(css),
        })
        return web.Response(
            status=200, body=css,
            headers={"Content-Type": "text/css; charset=utf-8"},
        )

    # OGC service endpoints — same surface as the wicket page for CVE-2024-36401.
    for svc_path, svc in (
        ("/geoserver/ows", "wfs"),
        ("/geoserver/wfs", "wfs"),
        ("/geoserver/wms", "wms"),
        ("/geoserver/wcs", "wcs"),
        ("/geoserver/wps", "wps"),
    ):
        if lpath == svc_path:
            body = render_geoserver_capabilities(svc, GEOSERVER_VERSION)
            append_log({
                **log_context,
                "status": 200,
                "result": f"geoserver-ogc-{svc}",
                **log_extra,
                "bytes": len(body),
            })
            return web.Response(
                status=200, body=body,
                headers={
                    "Content-Type": "application/xml; charset=utf-8",
                    "Cache-Control": "no-store",
                },
            )

    # /geoserver/rest/... — 401 Basic. Real GeoServer requires HTTP Basic
    # auth on the REST API; serving a 401 with the proper challenge keeps
    # tooling like geoserver-cli happy.
    if lpath.startswith("/geoserver/rest"):
        append_log({
            **log_context,
            "status": 401,
            "result": "geoserver-rest-401",
            **log_extra,
            "bytes": 0,
        })
        return web.Response(
            status=401, body=b"",
            headers={
                "WWW-Authenticate": 'Basic realm="GeoServer Realm"',
                "Cache-Control": "no-store",
            },
        )

    # Anything else under /geoserver/ — log + 404.
    append_log({
        **log_context,
        "status": 404,
        "result": "geoserver-miss",
        **log_extra,
        "bytes": 0,
    })
    return web.Response(
        status=404, body=b"not found\n",
        headers={"Content-Type": "text/plain; charset=utf-8"},
    )


async def _handle_liferay(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    """Liferay Portal JSON Web Services discovery + invoke (CVE-2020-7961
    marshaller RCE bait). Mints a per-request Tracebit AWS canary and
    embeds it in a fake S3-backed Document Library service description
    so scrapers walking the discovery page (or the per-service signature
    JSON) harvest a replay-fireable key. POST /api/jsonws/invoke captures
    the JSON-RPC body and flips `liferayHasMarshallerPayload` on the
    canonical CVE-2020-7961 sink indicators."""
    lpath = path.lower().split("?", 1)[0]
    method = request.method
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    body_preview = ""
    if request_body:
        try:
            body_preview = request_body[:LIFERAY_BODY_DECODE_LIMIT].decode(
                "utf-8", errors="replace",
            )
        except UnicodeDecodeError:
            body_preview = ""

    has_marshaller = _liferay_has_marshaller(request_body)

    service_class = ""
    if query_string:
        try:
            qs = parse_qs(query_string, keep_blank_values=True)
        except (ValueError, UnicodeDecodeError):
            qs = {}
        for key_name in ("serviceClassName", "serviceclassname"):
            values = qs.get(key_name)
            if values and values[0]:
                service_class = values[0][:200]
                break

    log_extra: dict[str, object] = {
        "liferayPath": path,
        "liferayMethod": method,
        "liferayHasMarshallerPayload": has_marshaller,
    }
    if service_class:
        log_extra["liferayServiceClassName"] = service_class
    if has_marshaller:
        # Truncate aggressively — a single marshaller payload can be
        # multi-KB and the existing log fields stay compact.
        log_extra["liferayPayloadPreview"] = body_preview[:400]

    tracebit_response = None
    if API_KEY:
        tracebit_response = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
    if tracebit_response is None:
        # Keyless deployments (or upstream failure) still serve a
        # plausible discovery page so banner-grab scanners keep walking;
        # the canary slots just go empty.
        tracebit_response = {}
    aws = _aws(tracebit_response)
    canary_types = [k for k, v in tracebit_response.items() if v]

    common_headers = {
        "Server": "Apache-Coyote/1.1",
        "Liferay-Portal": f"Liferay Community Edition {LIFERAY_VERSION} (Build {LIFERAY_BUILD_NUMBER})",
        "Cache-Control": "no-store",
    }

    # /api/jsonws/invoke — the CVE-2020-7961 sink. Capture the body and
    # return a generic Liferay JSON-WS error envelope (a real vulnerable
    # build returns the same shape when the marshaller fails before the
    # JNDI lookup completes; the scanner expects a non-200 here on
    # success path anyway).
    if lpath == "/api/jsonws/invoke":
        envelope = (
            b'{"exception":"com.liferay.portal.kernel.jsonwebservice.'
            b'JSONWebServiceInvocationException: Unable to convert '
            b'parameters"}'
        )
        append_log({
            **log_context,
            "status": 500,
            "result": "liferay-jsonws-invoke",
            **log_extra,
            "canaryTypes": canary_types,
            "bytes": len(envelope),
        })
        return web.Response(
            status=500, body=envelope,
            headers={**common_headers, "Content-Type": "application/json; charset=utf-8"},
        )

    # GET (or HEAD) with ?serviceClassName=... — single-service catalog.
    if service_class:
        body = render_liferay_jsonws_service_signature(
            service_class, aws, LIFERAY_VERSION, LIFERAY_BUILD_NUMBER,
        )
        append_log({
            **log_context,
            "status": 200,
            "result": "liferay-jsonws-service-signature",
            **log_extra,
            "canaryTypes": canary_types,
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": "application/json; charset=utf-8"},
        )

    # Bare /api/jsonws or /api/jsonws/ — landing HTML.
    if lpath in {"/api/jsonws", "/api/jsonws/"}:
        body = render_liferay_jsonws_landing(
            host, aws, LIFERAY_VERSION, LIFERAY_BUILD_NUMBER,
        )
        append_log({
            **log_context,
            "status": 200,
            "result": "liferay-jsonws-landing",
            **log_extra,
            "canaryTypes": canary_types,
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": "text/html; charset=utf-8"},
        )

    # Anything else under /api/jsonws/ — log + Liferay-shaped 404.
    envelope = (
        b'{"exception":"com.liferay.portal.kernel.jsonwebservice.'
        b'JSONWebServiceInvocationException: Path not mapped"}'
    )
    append_log({
        **log_context,
        "status": 404,
        "result": "liferay-jsonws-miss",
        **log_extra,
        "canaryTypes": canary_types,
        "bytes": len(envelope),
    })
    return web.Response(
        status=404, body=envelope,
        headers={**common_headers, "Content-Type": "application/json; charset=utf-8"},
    )


async def _handle_gravity_smtp(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
) -> web.Response:
    """Gravity SMTP WordPress plugin REST namespace
    (`/wp-json/gravitysmtp/v1/...`). Routes the per-endpoint surface
    described in the config block above:

      - `/settings`, `/tests/mock-data`, `/data/debug` → plausible
        diagnostic JSON (no credentials in the payload).
      - `/config` and `/connector/<known>` → Tracebit AWS canary in
        the AWS SES slot plus per-hit synthetic secrets for the other
        connectors. Connector names outside the published Gravity
        SMTP set 404 through the `gravitysmtp-miss` branch.

    Logs `gravitysmtpPath`, `gravitysmtpMethod`, `gravitysmtpConnector`
    (when a `/connector/<name>` request resolves), `result`,
    `canaryTypes`, and `bytes`."""
    lpath = path.lower().split("?", 1)[0]
    # Sub-directory placements (`/blog/wp-json/...`, `/wordpress/wp-json/...`)
    # normalise to the bare WP-REST namespace before the trailing-component
    # dispatch — keeps a single trailing-switch path that doesn't care
    # whether WordPress is mounted at the webroot or under a sub-dir.
    lpath = _gravity_smtp_strip_subdir(lpath)
    method = request.method
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    # Strip the namespace prefix to dispatch on the trailing component
    # of the path. The prefix-match in `is_gravity_smtp_path` guarantees
    # at least one of these starts-with checks fires when we reach here.
    trailing = ""
    if lpath.startswith(GRAVITY_SMTP_PATH_PREFIX + "/"):
        trailing = lpath[len(GRAVITY_SMTP_PATH_PREFIX) + 1:]
    elif lpath == GRAVITY_SMTP_PATH_PREFIX:
        trailing = ""
    # Trailing slash on `/v1/connector/gmail/` is equivalent to the
    # un-slashed form for dispatch purposes.
    trailing = trailing.rstrip("/")

    log_extra: dict[str, object] = {
        "gravitysmtpPath": path,
        "gravitysmtpMethod": method,
    }

    common_headers = {
        "Server": "Apache/2.4.58 (Ubuntu)",
        "X-Powered-By": "PHP/8.1.0",
        "Cache-Control": "no-store",
    }
    json_ct = "application/json; charset=utf-8"

    # `/settings` — namespace-wide settings.
    if trailing == "settings":
        body = render_gravity_smtp_settings(host)
        append_log({
            **log_context,
            "status": 200,
            "result": "gravitysmtp-settings",
            **log_extra,
            "canaryTypes": [],
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": json_ct},
        )

    # `/tests/mock-data` (any query string allowed — the plugin's
    # settings page passes `?page=gravitysmtp-settings`, also covered
    # by stripping the query string before the dispatch).
    if trailing == "tests/mock-data":
        body = render_gravity_smtp_mock_data(host)
        append_log({
            **log_context,
            "status": 200,
            "result": "gravitysmtp-mock-data",
            **log_extra,
            "canaryTypes": [],
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": json_ct},
        )

    # `/data/debug` — debug-panel slice.
    if trailing == "data/debug":
        body = render_gravity_smtp_debug(host)
        append_log({
            **log_context,
            "status": 200,
            "result": "gravitysmtp-debug",
            **log_extra,
            "canaryTypes": [],
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": json_ct},
        )

    # `/config` — credential-disclosure surface. Mints a per-request
    # AWS canary for the SES slot; on keyless deployments still serves
    # the response (with empty AWS slots) so banner-grab scanners walk
    # the namespace, but no canary issuance fires.
    if trailing == "config":
        tracebit_response: dict[str, object] = {}
        if API_KEY:
            issued = await _get_or_issue_canary(
                ("aws",), client_ip, request_id, host, user_agent, path, proto,
            )
            if issued is not None:
                tracebit_response = issued
        canary_types = [k for k, v in tracebit_response.items() if v]
        body = render_gravity_smtp_config(tracebit_response, host)
        append_log({
            **log_context,
            "status": 200,
            "result": "gravitysmtp-config",
            **log_extra,
            "canaryTypes": canary_types,
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**common_headers, "Content-Type": json_ct},
        )

    # `/connector/<name>` — single-connector slice. Known names get
    # a credential-shaped response (Tracebit AWS canary for SES, per-
    # hit synthetics otherwise); unknown names fall through to miss.
    if trailing.startswith("connector/"):
        connector = trailing.split("/", 1)[1].split("/", 1)[0]
        if connector in _GRAVITY_SMTP_KNOWN_CONNECTORS:
            tracebit_response = {}
            if API_KEY and connector == "amazonses":
                issued = await _get_or_issue_canary(
                    ("aws",), client_ip, request_id, host, user_agent, path, proto,
                )
                if issued is not None:
                    tracebit_response = issued
            canary_types = [k for k, v in tracebit_response.items() if v]
            body = render_gravity_smtp_connector(
                tracebit_response, connector, host,
            )
            append_log({
                **log_context,
                "status": 200,
                "result": f"gravitysmtp-connector-{connector}",
                **log_extra,
                "gravitysmtpConnector": connector,
                "canaryTypes": canary_types,
                "bytes": len(body),
            })
            return web.Response(
                status=200, body=body,
                headers={**common_headers, "Content-Type": json_ct},
            )

    # Everything else under the namespace — log + WP-REST-shaped 404.
    envelope = (
        b'{"code":"rest_no_route",'
        b'"message":"No route was found matching the URL and request method.",'
        b'"data":{"status":404}}'
    )
    append_log({
        **log_context,
        "status": 404,
        "result": "gravitysmtp-miss",
        **log_extra,
        "canaryTypes": [],
        "bytes": len(envelope),
    })
    return web.Response(
        status=404, body=envelope,
        headers={**common_headers, "Content-Type": json_ct},
    )


async def _handle_telescope(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
) -> web.Response:
    """Laravel Telescope debug-panel surface (`/telescope/...`). Routes:

      - `/telescope`, `/telescope/`, `/telescope/<panel>` → SPA HTML
        shell (`telescope-shell` result tag).
      - `/telescope/telescope-api/<panel>` (and `/api/<panel>` proxy
        placement) → panel JSON. The `requests`, `queries`,
        `exceptions`, `mail`, `logs` panels each mint a per-request
        AWS canary and embed it in the credential slot a real
        Telescope install would have shown there. Other known
        panels return an empty `entries[]` (`telescope-api-empty`
        result tag). Unknown panel names take the
        `telescope-api-miss` 404 branch.
      - Any other `/telescope/<...>` path falls through to the SPA
        HTML shell — real Telescope mounts the Vue router on every
        unknown sub-path.

    The `/admin/`, `/dashboard/`, `/panel/`, `/backend/`, `/app/`,
    `/laravel/`, `/monitor/`, `/dev/`, `/internal/` prefix
    placements are accepted by the predicate; the trailing
    `/telescope/...` is what dispatches here. Logs `telescopePath`,
    `telescopePanel`, `telescopeMethod`, `result`, `canaryTypes`,
    and `bytes`."""
    lpath = path.lower().split("?", 1)[0]

    # Published package assets the SPA shell names. Answered before the
    # panel routing so an asset fetch is not counted as a panel visit,
    # and none of them mints a canary.
    vendor_asset = _TELESCOPE_VENDOR_ASSETS.get(lpath)
    if vendor_asset is not None:
        asset_tag, asset_content_type = vendor_asset
        if lpath.endswith(".js"):
            asset_body = render_telescope_app_js()
        elif lpath.endswith(".css"):
            asset_body = render_telescope_app_css()
        else:
            asset_body = render_telescope_favicon_svg()
        append_log({
            **log_context, "status": 200, "result": asset_tag,
            "telescopePath": path, "telescopeMethod": request.method,
            "bytes": len(asset_body),
        })
        return web.Response(
            status=200, body=asset_body,
            headers={"Content-Type": asset_content_type},
        )

    canonical = _telescope_strip_prefix(lpath)
    method = request.method
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    # Strip the `/telescope` namespace prefix to get the trailing
    # component. `/telescope` and `/telescope/` both collapse to "".
    trailing = ""
    if canonical.startswith("/telescope/"):
        trailing = canonical[len("/telescope/"):]
    elif canonical == "/telescope":
        trailing = ""
    trailing = trailing.rstrip("/")

    log_extra: dict[str, object] = {
        "telescopePath": path,
        "telescopeMethod": method,
    }

    common_headers = {
        "Server": "nginx/1.24.0",
        "X-Powered-By": "PHP/8.2.15",
        "Cache-Control": "no-store, no-cache, must-revalidate",
    }
    json_ct = "application/json; charset=utf-8"
    html_ct = "text/html; charset=utf-8"

    # Telescope JSON API — real path is `telescope-api/<panel>`; some
    # reverse-proxy rewrites map it as `api/<panel>`. Both shapes hit
    # the same dispatch (the front-end SPA does the request via the
    # axios instance the page's bootstrap script configures).
    api_panel = ""
    api_prefix = ""
    for prefix in ("telescope-api/", "api/"):
        if trailing.startswith(prefix):
            api_panel = trailing[len(prefix):].split("/", 1)[0]
            api_prefix = prefix
            break

    if api_panel:
        log_extra["telescopePanel"] = api_panel
        if api_panel in _TELESCOPE_PANELS:
            tracebit_response: dict[str, object] = {}
            canary_types: list[str] = []
            # Panels that materialise an AWS canary in their entry
            # content mint the canary on first request; the rest of
            # the known panel set returns an empty entries[] and
            # never burns a canary.
            credential_panels = {"requests", "queries", "exceptions", "mail", "logs"}
            if api_panel in credential_panels and API_KEY:
                issued = await _get_or_issue_canary(
                    ("aws",), client_ip, request_id, host, user_agent, path, proto,
                )
                if issued is not None:
                    tracebit_response = issued
            canary_types = [k for k, v in tracebit_response.items() if v]

            if api_panel == "requests":
                body = render_telescope_api_requests(tracebit_response, host)
                result_tag = "telescope-api-requests"
            elif api_panel == "queries":
                body = render_telescope_api_queries(tracebit_response, host)
                result_tag = "telescope-api-queries"
            elif api_panel == "exceptions":
                body = render_telescope_api_exceptions(tracebit_response, host)
                result_tag = "telescope-api-exceptions"
            elif api_panel == "mail":
                body = render_telescope_api_mail(tracebit_response, host)
                result_tag = "telescope-api-mail"
            elif api_panel == "logs":
                body = render_telescope_api_logs(tracebit_response, host)
                result_tag = "telescope-api-logs"
            else:
                body = render_telescope_api_empty()
                result_tag = f"telescope-api-{api_panel}"
            append_log({
                **log_context,
                "status": 200,
                "result": result_tag,
                **log_extra,
                "canaryTypes": canary_types,
                "bytes": len(body),
            })
            return web.Response(
                status=200, body=body,
                headers={**common_headers, "Content-Type": json_ct},
            )
        # Unknown API panel — Telescope's router returns 404 here.
        envelope = b'{"message":"Not Found."}'
        append_log({
            **log_context,
            "status": 404,
            "result": "telescope-api-miss",
            **log_extra,
            "canaryTypes": [],
            "bytes": len(envelope),
        })
        return web.Response(
            status=404, body=envelope,
            headers={**common_headers, "Content-Type": json_ct},
        )

    # Anything else under `/telescope/...` (bare, trailing-slash, or a
    # known/unknown panel name without the api prefix) → SPA HTML
    # shell. Real Telescope serves the same HTML for every Vue route.
    if trailing and trailing.split("/", 1)[0] in _TELESCOPE_PANELS:
        log_extra["telescopePanel"] = trailing.split("/", 1)[0]
    body = render_telescope_shell_html(host)
    append_log({
        **log_context,
        "status": 200,
        "result": "telescope-shell",
        **log_extra,
        "canaryTypes": [],
        "bytes": len(body),
    })
    return web.Response(
        status=200, body=body,
        headers={**common_headers, "Content-Type": html_ct},
    )


async def _handle_adminer(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Adminer login page. GET (or HEAD) on any `/<adminer-alias>`
    path renders the canonical Adminer 4.x login HTML with a per-hit
    hidden form token + per-hit `adminer_sid_<random>` cookie. POSTs
    that supply `auth[username]` / `auth[password]` are captured as
    an `adminer-credential-post` event and re-serve the login page
    with the standard "Invalid credentials" error notice — plus an
    embedded Tracebit AWS canary in the `<datalist>` server-history
    preset (only on the POST re-serve, so bare-GET banner-grab
    scanners can't harvest without going through credential capture
    first). Real Adminer returns 200 on both the bare GET and the
    failed POST, so the trap matches the on-the-wire shape brute
    clients expect.

    No fixed credential literals are ever emitted — the token, the
    session cookie, and every field value on the fresh-GET response
    are per-hit synthetics (uuid hex), per the flux
    every-credential-per-hit-unique design principle. The AWS canary
    is Tracebit-minted on POST via `_get_or_issue_canary(('aws',),
    ...)` with the per-IP cache bounding quota burn."""
    method = request.method
    lp = path.lower().split("?", 1)[0]
    content_type_req = request.headers.get("Content-Type", "")
    cookie_header = request.headers.get("Cookie", "")
    cookies = parse_cookies(cookie_header)
    submitted_session = ""
    for cname in list(cookies):
        if cname.startswith("adminer_sid_") or cname.startswith("adminer_key"):
            submitted_session = cookies[cname]
            break

    token = uuid.uuid4().hex[:32]
    session_id = uuid.uuid4().hex
    session_slot = uuid.uuid4().hex[:8]

    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    common_headers = {
        "Server": "Apache/2.4.41 (Ubuntu)",
        "X-Powered-By": f"PHP/8.1.27 Adminer/{ADMINER_VERSION}",
        "X-Frame-Options": "DENY",
        "Cache-Control": "no-store, no-cache, must-revalidate, pre-check=0, post-check=0, max-age=0",
        "Pragma": "no-cache",
        "X-Content-Type-Options": "nosniff",
        "Referrer-Policy": "origin-when-cross-origin",
    }
    set_cookie = (
        f"adminer_sid_{session_slot}={session_id}; Path=/; HttpOnly; SameSite=Strict"
    )

    if method == "POST":
        creds = extract_adminer_creds(request_body, content_type_req)
        body_preview = ""
        if request_body:
            body_preview = request_body[:ADMINER_BODY_DECODE_LIMIT].decode(
                "utf-8", errors="replace",
            )

        # Mint the AWS canary — only on POST, so bare-GET scanners
        # can't harvest without submitting credentials first. Cached
        # per-IP by `_get_or_issue_canary` so a brute burst reuses
        # one canary rather than N.
        tracebit_response = None
        if API_KEY:
            tracebit_response = await _get_or_issue_canary(
                ("aws",), client_ip, request_id, host, user_agent, path, proto,
            )
        if tracebit_response is None:
            tracebit_response = {}
        aws = _aws(tracebit_response)
        canary_types = [k for k, v in tracebit_response.items() if v]

        log_entry = {
            **log_context,
            "result": "adminer-credential-post",
            "status": 200,
            "adminerPath": path,
            "adminerUsername": creds.get("auth_username", ""),
            "adminerServer": creds.get("auth_server", ""),
            "adminerDb": creds.get("auth_db", ""),
            "adminerDriver": creds.get("auth_driver", ""),
            "adminerHasPwd": creds.get("hasPwd", "") == "true",
            "adminerPwdLen": creds.get("pwdLen", ""),
            "adminerPermanent": creds.get("auth_permanent", "") == "1",
            "adminerTokenSubmitted": creds.get("token", "")[:48],
            "adminerSessionCookiePresent": bool(submitted_session),
            "canaryTypes": canary_types,
            "contentType": content_type_req[:120],
        }
        if body_preview:
            log_entry["bodyPreview"] = body_preview
        html = render_adminer_login_html(
            version=ADMINER_VERSION,
            token=token,
            aws=aws,
            error="Invalid credentials.",
            submitted_user=creds.get("auth_username", ""),
            submitted_server=creds.get("auth_server", ""),
            submitted_db=creds.get("auth_db", ""),
        )
        log_entry["bytes"] = len(html)
        append_log(log_entry)
        return web.Response(
            status=200, body=html,
            headers={
                **common_headers,
                "Content-Type": "text/html; charset=utf-8",
                "Set-Cookie": set_cookie,
                "Content-Length": str(len(html)),
            },
        )

    # GET / HEAD — render the bare login page. No canary on this
    # branch: it only mints on POST after a credential capture.
    html = render_adminer_login_html(version=ADMINER_VERSION, token=token)
    response_body = b"" if method == "HEAD" else html
    log_entry = {
        **log_context,
        "result": "adminer-login",
        "status": 200,
        "adminerPath": path,
        "adminerMethod": method,
        "adminerSessionCookiePresent": bool(submitted_session),
        "bytes": len(html),
    }
    append_log(log_entry)
    return web.Response(
        status=200, body=response_body,
        headers={
            **common_headers,
            "Content-Type": "text/html; charset=utf-8",
            "Set-Cookie": set_cookie,
            "Content-Length": str(len(html)),
        },
    )


async def _handle_whm(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """cPanel WHM login page. GET / HEAD renders the WHM 11.x login
    HTML with a per-request `cpsess<hex>` token embedded in the form
    action + asset URLs plus a per-request `cprelogin` cookie. POST
    that supplies `user` + `pass` is captured as a `whm-credential-post`
    event and re-serves the login page with the standard "The login
    is invalid." error notice.

    No fixed credential literals: the cpsess token, the cprelogin
    cookie value, the goto_uri echo, and every field value on the
    fresh-GET response are per-hit synthetics (uuid hex), per the
    every-credential-per-hit-unique design principle."""
    method = request.method
    lp = path.lower().split("?", 1)[0]
    content_type_req = request.headers.get("Content-Type", "")
    query_string = request.query_string or ""
    cookie_header = request.headers.get("Cookie", "")
    cookies = parse_cookies(cookie_header)
    submitted_session = ""
    for cname in list(cookies):
        if cname.startswith("cprelogin") or cname.startswith("cpsession"):
            submitted_session = cookies[cname]
            break

    # cpsess tokens are lowercase hex; extract from URL when the
    # scanner hit a `/cpsess<hex>/…` alias so the same token flows
    # through form action + asset URLs (real cpsrvd preserves the
    # session token across the login page → POST cycle).
    cpsess_in_path = ""
    m = re.match(r"^/cpsess([0-9a-f]{16,64})/", lp)
    if m:
        cpsess_in_path = m.group(1)
    cpsess = cpsess_in_path or uuid.uuid4().hex + uuid.uuid4().hex[:16]

    cprelogin_id = uuid.uuid4().hex
    hostname = str(log_context.get("host", "")) or "server"

    # Preserve the `goto_uri` from a form-submit or query string so
    # the login page's hidden goto field echoes what the scanner
    # sent (real WHM does this).
    goto_uri = "/whm/"
    if query_string:
        try:
            qparsed = parse_qs(query_string, keep_blank_values=True)
            gvals = qparsed.get("goto_uri") or qparsed.get("goto")
            if gvals and gvals[0]:
                goto_uri = gvals[0][:200]
        except Exception:
            pass

    request_id = str(log_context.get("requestId", ""))

    common_headers = {
        "Server": f"cpsrvd/{WHM_VERSION}",
        "X-Frame-Options": "SAMEORIGIN",
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "no-store, no-cache, must-revalidate",
        "Pragma": "no-cache",
        "Referrer-Policy": "same-origin",
        "Strict-Transport-Security": "max-age=31536000",
    }
    set_cookie = (
        f"cprelogin={cprelogin_id}; Path=/; HttpOnly; SameSite=Strict"
    )

    if method == "POST":
        creds = extract_whm_creds(request_body, content_type_req)
        body_preview = ""
        if request_body:
            body_preview = request_body[:WHM_BODY_DECODE_LIMIT].decode(
                "utf-8", errors="replace",
            )
        if creds.get("goto_uri"):
            goto_uri = creds["goto_uri"]

        log_entry = {
            **log_context,
            "result": "whm-credential-post",
            "status": 200,
            "whmPath": path,
            "whmUsername": creds.get("user", ""),
            "whmHasPwd": creds.get("hasPwd", "") == "true",
            "whmPwdLen": creds.get("pwdLen", ""),
            "whmGotoUri": creds.get("goto_uri", ""),
            "whmGotoApp": creds.get("goto_app", ""),
            "whmSessionCookiePresent": bool(submitted_session),
            "whmCpsessFromPath": bool(cpsess_in_path),
            "contentType": content_type_req[:120],
        }
        if body_preview:
            log_entry["bodyPreview"] = body_preview
        html = render_whm_login_html(
            version=WHM_VERSION,
            cpsess=cpsess,
            hostname=hostname,
            goto_uri=goto_uri,
            error="The login is invalid.",
            submitted_user=creds.get("user", ""),
        )
        log_entry["bytes"] = len(html)
        append_log(log_entry)
        return web.Response(
            status=200, body=html,
            headers={
                **common_headers,
                "Content-Type": "text/html; charset=utf-8",
                "Set-Cookie": set_cookie,
                "Content-Length": str(len(html)),
            },
        )

    # GET / HEAD — render the bare login page.
    html = render_whm_login_html(
        version=WHM_VERSION,
        cpsess=cpsess,
        hostname=hostname,
        goto_uri=goto_uri,
    )
    response_body = b"" if method == "HEAD" else html
    log_entry = {
        **log_context,
        "result": "whm-login",
        "status": 200,
        "whmPath": path,
        "whmMethod": method,
        "whmSessionCookiePresent": bool(submitted_session),
        "whmCpsessFromPath": bool(cpsess_in_path),
        "bytes": len(html),
    }
    append_log(log_entry)
    return web.Response(
        status=200, body=response_body,
        headers={
            **common_headers,
            "Content-Type": "text/html; charset=utf-8",
            "Set-Cookie": set_cookie,
            "Content-Length": str(len(html)),
        },
    )


async def _handle_weblogic_console(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Oracle WebLogic AdminServer console. GET/HEAD returns the login
    HTML with a per-request `ADMINCONSOLESESSION` cookie. POST is
    treated as a credential submission: captures `j_username` +
    `j_password`-presence, re-serves the login page with the
    "Authentication Denied" error notice, and mints a fresh session
    cookie so the JSESSIONID / ADMINCONSOLESESSION replay chain
    stays alive past the first POST. No fixed credential literals are
    emitted; the session cookie is per-hit `uuid4().hex`."""
    method = request.method
    content_type_req = request.headers.get("Content-Type", "")
    cookie_header = request.headers.get("Cookie", "")
    cookies = parse_cookies(cookie_header)
    submitted_session = cookies.get("ADMINCONSOLESESSION") or cookies.get("JSESSIONID") or ""

    # Skin assets the login page names. Answered before the login flow so
    # a stylesheet fetch is never mistaken for a console visit, and served
    # without a session cookie because a real static asset does not mint
    # one.
    lpath_console = path.lower().split("?", 1)[0]
    if lpath_console == "/console/framework/skins/wlsconsole/css/master.css":
        css = render_weblogic_console_css()
        append_log({
            **log_context, "status": 200,
            "result": "weblogic-console-asset",
            "weblogicConsolePath": path, "bytes": len(css),
        })
        return web.Response(
            status=200, body=css,
            headers={"Content-Type": "text/css; charset=utf-8"},
        )
    if lpath_console == "/console/framework/skins/wlsconsole/images/login_weblogic_branding.png":
        png = render_weblogic_console_branding_png()
        append_log({
            **log_context, "status": 200,
            "result": "weblogic-console-asset",
            "weblogicConsolePath": path, "bytes": len(png),
        })
        return web.Response(
            status=200, body=png,
            headers={"Content-Type": "image/png"},
        )

    host = str(log_context.get("host", ""))
    # Real WebLogic mints `ADMINCONSOLESESSION=<uppercased-alnum>` with
    # a `Path=/console; HttpOnly` scope. Per-request value keeps replay
    # attempts attributable to the issuance event in the trap log.
    session_id = uuid.uuid4().hex.upper()
    set_cookie = (
        f"ADMINCONSOLESESSION={session_id}; Path=/console; HttpOnly"
    )

    common_headers = {
        # Real WebLogic 14c AdminServer advertises this exact banner.
        "Server": f"WebLogic Server {WEBLOGIC_CONSOLE_VERSION}",
        # Framework identifier real WebLogic ships in the login flow;
        # `X-ORACLE-DMS-ECID` is the Diagnostic-Message-Service context
        # ID scanners cross-reference to confirm a WebLogic origin.
        "X-ORACLE-DMS-ECID": uuid.uuid4().hex,
        "X-ORACLE-DMS-RID": "0",
        "Cache-Control": "no-cache, no-store, must-revalidate",
        "Pragma": "no-cache",
        "X-Frame-Options": "SAMEORIGIN",
    }

    if method == "POST":
        creds = extract_weblogic_console_creds(request_body, content_type_req)
        body_preview = ""
        if request_body:
            body_preview = request_body[:WEBLOGIC_CONSOLE_BODY_DECODE_LIMIT].decode(
                "utf-8", errors="replace",
            )
        html = render_weblogic_console_login_html(
            host,
            WEBLOGIC_CONSOLE_VERSION,
            error="Authentication Denied",
            submitted_user=creds.get("username", ""),
        )
        log_entry: dict[str, object] = {
            **log_context,
            "result": "weblogic-console-credential-post",
            "status": 200,
            "weblogicConsolePath": path,
            "weblogicConsoleUsername": creds.get("username", ""),
            "weblogicConsoleHasPwd": creds.get("hasPwd", "") == "true",
            "weblogicConsolePwdLen": creds.get("pwdLen", ""),
            "weblogicConsoleSessionCookiePresent": bool(submitted_session),
            "contentType": content_type_req[:120],
            "bytes": len(html),
        }
        if body_preview:
            log_entry["bodyPreview"] = body_preview
        append_log(log_entry)
        return web.Response(
            status=200, body=html,
            headers={
                **common_headers,
                "Content-Type": "text/html; charset=utf-8",
                "Set-Cookie": set_cookie,
                "Content-Length": str(len(html)),
            },
        )

    html = render_weblogic_console_login_html(host, WEBLOGIC_CONSOLE_VERSION)
    response_body = b"" if method == "HEAD" else html
    log_entry = {
        **log_context,
        "result": "weblogic-console-login",
        "status": 200,
        "weblogicConsolePath": path,
        "weblogicConsoleMethod": method,
        "weblogicConsoleSessionCookiePresent": bool(submitted_session),
        "bytes": len(html),
    }
    append_log(log_entry)
    return web.Response(
        status=200, body=response_body,
        headers={
            **common_headers,
            "Content-Type": "text/html; charset=utf-8",
            "Set-Cookie": set_cookie,
            "Content-Length": str(len(html)),
        },
    )


async def _handle_ds_store(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
) -> web.Response:
    """Serve a plausible Finder `.DS_Store` binary. GET returns the
    binary body; HEAD returns 200 with the same headers and empty
    body. No credential capture — this trap's success signal is
    the follow-on probe volume for the embedded entry names, not
    the `.DS_Store` fetch itself."""
    body = render_ds_store_body(DS_STORE_ENTRY_NAMES)
    method = request.method
    response_body = b"" if method == "HEAD" else body
    log_entry = {
        **log_context,
        "result": "ds-store",
        "status": 200,
        "dsStorePath": path,
        "dsStoreMethod": method,
        "dsStoreEntryCount": len(DS_STORE_ENTRY_NAMES),
        "bytes": len(body),
    }
    append_log(log_entry)
    return web.Response(
        status=200,
        body=response_body,
        headers={
            # `.DS_Store` has no registered IANA MIME type — real
            # webservers serve it as application/octet-stream (nginx
            # default) or fall back to text/plain (apache). Match the
            # nginx shape; a scraper's file-command classifier looks
            # at the magic bytes, not the header.
            "Content-Type": "application/octet-stream",
            "Content-Length": str(len(body)),
            "Cache-Control": "no-store",
            # Real deployments that leak `.DS_Store` almost always sit
            # behind a stock nginx that ships the file with an ETag +
            # Last-Modified pair. Emit a per-hit ETag so the trap isn't
            # a fleet-wide fingerprint via `If-None-Match` on later hits.
            "ETag": f'"{uuid.uuid4().hex[:16]}"',
        },
    )


async def _handle_phpmyadmin(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """phpMyAdmin cookie-auth login page. GET (or HEAD) on any
    `/<pma-alias>/...` path renders the canonical PMA login HTML with
    a per-hit hidden token + a per-hit `phpMyAdmin` session cookie,
    and POSTs that supply `pma_username` / `pma_password` are captured
    as a `phpmyadmin-credential-post` event before the same login HTML
    is re-served with the standard "Cannot log in to the MySQL server"
    error notice. Real PMA returns 200 in both cases, so the trap
    matches the on-the-wire shape banner-grab + brute clients expect.

    No fixed credential literals are ever emitted — the token + session
    cookie are per-hit synthetics (random 32-hex), per the flux
    every-credential-per-hit-unique design principle. The trap deliberately
    has no canary issuance call: it captures already-submitted creds, it
    does not issue replay-fireable secrets, so it stays cheap to run."""
    method = request.method
    lp = path.lower().split("?", 1)[0]
    content_type_req = request.headers.get("Content-Type", "")
    cookie_header = request.headers.get("Cookie", "")
    cookies = parse_cookies(cookie_header)
    submitted_session = cookies.get("phpMyAdmin", "") or cookies.get("phpmyadmin", "")

    token = uuid.uuid4().hex[:32]
    session_id = uuid.uuid4().hex

    common_headers = {
        "Server": "Apache/2.4.41 (Ubuntu)",
        "X-Powered-By": f"PHP/8.1.27 phpMyAdmin/{PHPMYADMIN_VERSION}",
        "X-Frame-Options": "DENY",
        "Cache-Control": "no-store, no-cache, must-revalidate, pre-check=0, post-check=0, max-age=0",
        "Pragma": "no-cache",
        "X-Content-Type-Options": "nosniff",
    }
    set_cookie = (
        f"phpMyAdmin={session_id}; Path=/; HttpOnly; SameSite=Strict"
    )

    if method == "POST":
        creds = extract_phpmyadmin_creds(request_body, content_type_req)
        body_preview = ""
        if request_body:
            body_preview = request_body[:PHPMYADMIN_BODY_DECODE_LIMIT].decode(
                "utf-8", errors="replace",
            )
        log_entry = {
            **log_context,
            "result": "phpmyadmin-credential-post",
            "status": 200,
            "phpMyAdminPath": path,
            "phpMyAdminUsername": creds.get("pma_username", ""),
            "phpMyAdminHasPwd": creds.get("hasPwd", "") == "true",
            "phpMyAdminPwdLen": creds.get("pwdLen", ""),
            "phpMyAdminServer": creds.get("server", ""),
            "phpMyAdminTokenSubmitted": creds.get("token", "")[:48],
            "phpMyAdminSessionCookiePresent": bool(submitted_session),
            "contentType": content_type_req[:120],
        }
        if body_preview:
            log_entry["bodyPreview"] = body_preview
        html = render_phpmyadmin_login_html(
            version=PHPMYADMIN_VERSION,
            token=token,
            error="Cannot log in to the MySQL server",
            submitted_user=creds.get("pma_username", ""),
        )
        log_entry["bytes"] = len(html)
        append_log(log_entry)
        return web.Response(
            status=200, body=html,
            headers={
                **common_headers,
                "Content-Type": "text/html; charset=utf-8",
                "Set-Cookie": set_cookie,
                "Content-Length": str(len(html)),
            },
        )

    # GET / HEAD — render the bare login page. A `/setup/` probe gets
    # the same login since real PMA installs typically lock /setup/ to
    # disabled or redirect to the main login.
    is_setup = "/setup/" in lp or lp.endswith("/setup")
    result_tag = "phpmyadmin-setup-probe" if is_setup else "phpmyadmin-login"
    html = render_phpmyadmin_login_html(version=PHPMYADMIN_VERSION, token=token)
    response_body = b"" if method == "HEAD" else html
    log_entry = {
        **log_context,
        "result": result_tag,
        "status": 200,
        "phpMyAdminPath": path,
        "phpMyAdminMethod": method,
        "phpMyAdminSessionCookiePresent": bool(submitted_session),
        "bytes": len(html),
    }
    append_log(log_entry)
    return web.Response(
        status=200, body=response_body,
        headers={
            **common_headers,
            "Content-Type": "text/html; charset=utf-8",
            "Set-Cookie": set_cookie,
            "Content-Length": str(len(html)),
        },
    )


async def _handle_oidc_discovery(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
) -> web.Response:
    """OIDC / OAuth discovery JSON. Always 200 with the RFC-shaped doc;
    the embedded Tracebit AWS canary fires on credential replay.

    Realm name (Keycloak `/realms/<realm>/` placement) is logged for
    cross-sensor correlation — campaigns frequently target specific
    realm conventions (`master`, `default`, `<org>`, `<product>`). The
    method is logged because GET vs POST split distinguishes plain
    fingerprint walks from dynamic-client-registration probe flows."""
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))
    method = request.method

    normalised = _oidc_discovery_normalise(path).split("?", 1)[0]
    is_oauth_sibling = normalised.endswith(
        "/.well-known/oauth-authorization-server"
    )
    realm = _oidc_discovery_realm(path)

    log_extra: dict[str, object] = {
        "oidcDiscoveryPath": path,
        "oidcDiscoveryMethod": method,
        "oidcDiscoveryRealm": realm,
        "oidcDiscoveryKind": (
            "oauth-authorization-server" if is_oauth_sibling
            else "openid-configuration"
        ),
    }

    tracebit_response: dict[str, object] = {}
    if API_KEY:
        issued = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
        if issued is not None:
            tracebit_response = issued
    canary_types = [k for k, v in tracebit_response.items() if v]

    body = render_oidc_discovery_json(
        tracebit_response, host, realm, is_oauth_sibling, OIDC_DISCOVERY_VERSION,
    )
    headers = {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "Server": "nginx/1.24.0",
    }
    append_log({
        **log_context,
        "status": 200,
        "result": "oidc-discovery",
        **log_extra,
        "canaryTypes": canary_types,
        "bytes": len(body),
    })
    return web.Response(status=200, body=body, headers=headers)


# Fields worth lifting off an OAuth request. `client_secret` and
# `password` are recorded as a hash plus a short preview rather than in
# clear: the guess distribution is the intel, and grouping the same
# guessed secret across source IPs only needs the hash.
_OIDC_PLAIN_FIELDS = (
    "client_id", "grant_type", "response_type", "scope", "state",
    "nonce", "username", "code", "redirect_uri", "audience",
    "token_type_hint", "code_challenge", "code_challenge_method",
    "client_name", "device_code", "subject_token",
)
_OIDC_SECRET_FIELDS = ("client_secret", "password", "token", "refresh_token", "assertion")


# Below this length a first-n/last-n preview is not a fragment of the
# secret, it *is* the secret — most submitted passwords are shorter than
# this. The preview exists to make long machine-issued tokens readable in
# triage, so it is emitted only where it stays a fragment.
_OIDC_SECRET_PREVIEW_MIN_LENGTH = 32


def _oidc_secret_digest(value: str) -> dict[str, object]:
    """Hash + length for a credential-shaped field, plus a preview only
    when the value is long enough for the preview to remain a fragment.

    The hash is what groups the same guessed secret across source IPs,
    which is the measurement; the plaintext is never needed for that and
    is never recorded.
    """
    raw = value.encode("utf-8", "replace")
    out: dict[str, object] = {
        "sha256": hashlib.sha256(raw).hexdigest(),
        "length": len(value),
    }
    if len(value) >= _OIDC_SECRET_PREVIEW_MIN_LENGTH:
        out["preview"] = f"{value[:8]}…{value[-4:]}"
    return out


def _oidc_collect_fields(
    query_string: str, request_body: bytes, content_type: str,
) -> tuple[dict[str, object], dict[str, object]]:
    """Pull the OAuth parameters out of the query string and the body.

    Handles both `application/x-www-form-urlencoded` (what every OAuth
    POST uses) and JSON (what dynamic client registration uses). Returns
    the plain fields and the digested credential-shaped ones.
    """
    plain: dict[str, object] = {}
    secret: dict[str, object] = {}

    def _take(key: str, value: str) -> None:
        if not value:
            return
        if key in _OIDC_SECRET_FIELDS:
            secret.setdefault(key, _oidc_secret_digest(value))
        elif key in _OIDC_PLAIN_FIELDS:
            plain.setdefault(key, value[:256])

    if query_string:
        try:
            for key, value in parse_qsl(query_string, keep_blank_values=True):
                _take(key, value)
        except Exception:  # noqa: BLE001
            pass

    body = request_body[:OIDC_ENDPOINT_BODY_DECODE_LIMIT]
    if not body:
        return plain, secret
    text = body.decode("utf-8", "replace")
    if "json" in content_type.lower():
        try:
            parsed = json.loads(text)
        except Exception:  # noqa: BLE001
            parsed = None
        if isinstance(parsed, dict):
            for key, value in parsed.items():
                if isinstance(value, str):
                    _take(key, value)
                elif key == "redirect_uris" and isinstance(value, list):
                    # Dynamic client registration: the callback the
                    # caller wants tokens delivered to, i.e. their own
                    # infrastructure. Same class of signal as an
                    # out-of-band callback host lifted from an exploit
                    # body — durable across source-IP rotation.
                    plain.setdefault(
                        "redirect_uris",
                        [str(v)[:256] for v in value[:8]],
                    )
    else:
        try:
            for key, value in parse_qsl(text, keep_blank_values=True):
                _take(key, value)
        except Exception:  # noqa: BLE001
            pass
    return plain, secret


def _oidc_bearer_token(request: web.Request) -> str:
    """The presented bearer token, if any. A client reaching userinfo or
    registration with a token is replaying something it already holds,
    which is a different population from one probing the endpoint bare."""
    auth = request.headers.get("Authorization", "")
    if auth[:7].lower() == "bearer ":
        return auth[7:].strip()
    return ""


def _oidc_json_error(
    status: int, error: str, description: str,
    extra_headers: dict[str, str] | None = None,
) -> tuple[int, bytes, dict[str, str]]:
    body = json.dumps(
        {"error": error, "error_description": description},
        separators=(",", ":"),
    ).encode("utf-8")
    headers = {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "Pragma": "no-cache",
        "Server": "nginx/1.24.0",
    }
    if extra_headers:
        headers.update(extra_headers)
    return status, body, headers


async def _handle_oidc_endpoint(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
    match: "OidcEndpointMatch",
) -> web.Response:
    """The endpoints the discovery document advertises.

    Each answer is the one a real Keycloak gives an unauthenticated
    caller, because that is what tells the client the endpoint is
    registered. A 404 says the opposite, and said it for every address
    the document published until this handler existed.

    The credential-bearing endpoints answer `invalid_client` rather than
    accepting anything: accepting a guessed secret would mean the log
    could not distinguish a guess from a real credential, and the guess
    distribution is the measurement. What each request carried is logged
    either way.

    No canary is issued here. The discovery document already carries
    one, and this surface's signal is the submitted credential and the
    caller's own callback address rather than a replay.
    """
    method = request.method
    kind = match.kind
    realm = match.realm
    host = str(log_context.get("host", ""))
    content_type = request.headers.get("Content-Type", "")

    plain, secret = _oidc_collect_fields(query_string, request_body, content_type)
    bearer = _oidc_bearer_token(request)

    log_extra: dict[str, object] = {
        "oidcEndpointPath": path,
        "oidcEndpointKind": kind,
        "oidcEndpointMethod": method,
        "oidcEndpointRealm": realm,
    }
    if plain:
        log_extra["oidcEndpointFields"] = plain
    if secret:
        log_extra["oidcEndpointSecrets"] = secret
    if bearer:
        log_extra["oidcEndpointBearer"] = _oidc_secret_digest(bearer)

    result = f"oidc-{kind.replace('/', '-')}"

    if kind == "certs":
        body = render_oidc_jwks_json()
        status, headers = 200, {
            "Content-Type": "application/json; charset=utf-8",
            "Cache-Control": "no-store",
            "Server": "nginx/1.24.0",
        }
    elif kind == "auth":
        client_id = str(plain.get("client_id", ""))
        if client_id.lower() in _OIDC_BUILTIN_CLIENT_IDS:
            body = render_oidc_login_page(
                host, realm, client_id, OIDC_DISCOVERY_VERSION,
            )
            status = 200
            result = "oidc-auth-login-form"
        else:
            body = render_oidc_error_page(
                host, realm,
                "We are sorry... Invalid parameter: client_id",
            )
            status = 400
            result = "oidc-auth-unknown-client"
        headers = {
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "no-store",
            "Server": "nginx/1.24.0",
        }
    elif kind == _OIDC_LOGIN_ACTION_SUFFIX:
        # The login form's submit target. Real Keycloak re-renders the
        # form with an error notice on a bad password, so the caller
        # can keep trying — which is the behaviour that keeps a brute
        # loop submitting rather than moving on after one attempt.
        body = render_oidc_login_page(
            host, realm, str(plain.get("client_id", "")), OIDC_DISCOVERY_VERSION,
        )
        status, headers = 200, {
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "no-store",
            "Server": "nginx/1.24.0",
        }
        result = "oidc-login-credential-post" if secret.get("password") else "oidc-login-form"
    elif kind == "userinfo":
        status, body, headers = _oidc_json_error(
            401, "invalid_token", "Token verification failed",
            {"WWW-Authenticate": f'Bearer realm="{realm or "master"}", error="invalid_token"'},
        )
    elif kind == "clients-registrations/openid-connect":
        status, body, headers = _oidc_json_error(
            401, "invalid_token",
            "Failed to verify token: no initial access token provided",
        )
    elif kind == "logout":
        # Deliberately never redirects to a caller-supplied address.
        # Honouring `post_logout_redirect_uri` would turn the sensor
        # into an open redirector pointed wherever the caller likes,
        # which is a real capability to hand out for no extra signal —
        # the address is already logged from the query string.
        body = render_oidc_error_page(
            host, realm, "Invalid parameter: post_logout_redirect_uri",
        )
        status, headers = 400, {
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "no-store",
            "Server": "nginx/1.24.0",
        }
    else:
        # token, token/introspect, revoke — the form-POST endpoints.
        if method in {"GET", "HEAD"}:
            status, body, headers = _oidc_json_error(
                405, "invalid_request",
                "RESTEASY003065: Cannot consume content type",
            )
        else:
            status, body, headers = _oidc_json_error(
                401, "invalid_client",
                "Invalid client or Invalid client credentials",
            )

    append_log({
        **log_context,
        "status": status,
        "result": result,
        **log_extra,
        "bytes": len(body),
    })
    if method == "HEAD":
        return web.Response(status=status, headers=headers)
    return web.Response(status=status, body=body, headers=headers)


async def _handle_coldfusion(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    lpath = path.lower()
    method = request.method
    host = str(log_context.get("host", ""))
    query = str(log_context.get("query", "") or "")
    content_type_req = request.headers.get("Content-Type", "")
    has_auth = bool(request.headers.get("Authorization", "")) or bool(request.headers.get("Cookie", ""))

    body_preview = ""
    if request_body:
        body_preview = request_body[:512].decode("utf-8", errors="replace")

    has_exploit = _coldfusion_has_exploit(path, query, body_preview)
    query_params = parse_qs(query, keep_blank_values=True) if query else {}
    method_name = ""
    for key in ("method", "METHOD"):
        values = query_params.get(key)
        if values and values[0]:
            method_name = values[0][:120]
            break

    log_extra: dict[str, object] = {
        "coldfusionPath": path,
        "coldfusionMethod": method,
        "coldfusionHasAuth": has_auth,
        "coldfusionHasExploit": has_exploit,
        "contentType": content_type_req[:120],
    }
    if method_name:
        log_extra["coldfusionAction"] = method_name
    if body_preview:
        log_extra["bodyPreview"] = body_preview
    if has_exploit:
        log_extra["coldfusionPayloadPreview"] = (query + " | " + body_preview)[:400]

    if lpath in {"/indice.cfm", "/menu.cfm", "/base.cfm"}:
        result_tag = "coldfusion-public-cfm"
        body = render_coldfusion_public_page(path, host, COLDFUSION_VERSION)
        content_type = "text/html; charset=utf-8"
    elif lpath == "/cfide/componentutils" or lpath.startswith("/cfide/componentutils/"):
        result_tag = "coldfusion-componentutils"
        body = render_coldfusion_componentutils(host, COLDFUSION_VERSION)
        content_type = "text/html; charset=utf-8"
    elif lpath.startswith("/cfide/administrator/"):
        result_tag = "coldfusion-admin-post" if method == "POST" else "coldfusion-admin-login"
        if method == "POST":
            body = render_coldfusion_admin_dashboard(host, COLDFUSION_VERSION)
        else:
            body = render_coldfusion_admin_login(host, COLDFUSION_VERSION)
        content_type = "text/html; charset=utf-8"
    elif lpath.startswith("/cfide/adminapi/"):
        result_tag = "coldfusion-adminapi"
        body = render_coldfusion_adminapi(method_name, COLDFUSION_VERSION)
        content_type = "text/xml; charset=utf-8"
    else:
        append_log({**log_context, "status": 404, "result": "coldfusion-miss", **log_extra})
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    append_log({
        **log_context,
        "status": 200,
        "result": result_tag,
        **log_extra,
        "bytes": len(body),
    })
    return web.Response(
        status=200, body=body,
        headers={
            "Content-Type": content_type,
            "Cache-Control": "no-store",
        },
    )


async def _handle_confluence(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Fake Atlassian Confluence surface. Returns a plausible login page
    on the path matchers, the small JSON / HTML fragments real Confluence
    serves on `user-dark-features` / `editor-preload-container`, and a
    permissive 200 on any path containing an OGNL injection (the canonical
    CVE-2022-26134 shape, URL-encoded inside the path itself).

    The OAST callback hostname is extracted from path/query/body so the
    same probe is correlatable across sensors regardless of source IP."""
    lpath = path.lower()
    method = request.method
    host = str(log_context.get("host", ""))
    query = str(log_context.get("query", "") or "")

    body_preview = ""
    if request_body:
        body_preview = request_body[:WEBSHELL_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )

    has_ognl = _confluence_has_ognl(path, query, body_preview)
    oast_callback = _extract_oast_callback(path)
    if not oast_callback:
        oast_callback = _extract_oast_callback(query)
    if not oast_callback and body_preview:
        oast_callback = _extract_oast_callback(body_preview)

    log_extra: dict[str, object] = {
        "confluencePath": path,
        "confluenceMethod": method,
        "confluenceHasOgnl": has_ognl,
    }
    if oast_callback:
        log_extra["confluenceOastCallback"] = oast_callback[:253]
    if has_ognl:
        # OGNL payloads can run multi-KB; keep the log compact while still
        # carrying enough for triage / sensor-cross-correlation.
        log_extra["confluencePayloadPreview"] = (
            f"{path} | {query} | {body_preview}"
        )[:400]
    if body_preview and not has_ognl:
        # Plain login-form POSTs etc. — keep the preview short.
        log_extra["bodyPreview"] = body_preview[:400]

    # OGNL-injection paths, `*-entervariables.action` /
    # `doenterpagevariables.action`, and any `.action` whose query/body
    # carries an S2-* OGNL payload (Struts redirect/redirectAction/method
    # with `${#...ProcessBuilder...}`) all render the login HTML — that
    # response body is what real Confluence returns when the OGNL
    # expression evaluates successfully.
    if (
        "${@" in lpath
        or "%24%7b%40" in lpath
        or "createpage-entervariables.action" in lpath
        or "doenterpagevariables.action" in lpath
        or (has_ognl and lpath.endswith(".action"))
    ):
        result_tag = "confluence-ognl-probe" if has_ognl else "confluence-action"
        body = render_confluence_login_html(host, CONFLUENCE_VERSION)
        content_type = "text/html; charset=utf-8"
    elif lpath.endswith("/user-dark-features"):
        result_tag = "confluence-dark-features"
        body = render_confluence_dark_features_json()
        content_type = "application/json; charset=utf-8"
    elif lpath.endswith("/templates/editor-preload-container"):
        result_tag = "confluence-editor-preload"
        body = render_confluence_editor_preload_html(CONFLUENCE_VERSION)
        content_type = "text/html; charset=utf-8"
    elif method != "POST" and lpath.endswith("/dologin.action"):
        # Real Confluence has no GET route here -- a browser landing on it
        # is bounced back to the login page. Serving that keeps non-POST
        # probes out of the credential-post counts, which only mean
        # something if every row in them is an actual submission.
        result_tag = "confluence-login"
        body = render_confluence_login_html(host, CONFLUENCE_VERSION)
        content_type = "text/html; charset=utf-8"
    elif lpath.endswith("/dologin.action"):
        # The login page's own submit target. Real Confluence re-renders
        # the login page with an error notice on a bad credential, which
        # is also the only honest thing we can do — so the response is the
        # same page, and the value is in what gets logged off the body.
        creds = extract_confluence_login_creds(request_body, request.headers.get("Content-Type", ""))
        result_tag = "confluence-credential-post"
        log_extra["confluenceUsername"] = creds.get("username", "")
        log_extra["confluenceHasPwd"] = creds.get("hasPwd", "") == "true"
        if creds.get("pwdLen"):
            log_extra["confluencePwdLen"] = creds["pwdLen"]
        # `atl_token` is the per-render CSRF nonce the login page handed
        # out. A client that echoes it parsed our HTML and submitted the
        # real form; one that posts without it is replaying a canned
        # credential-stuffing request. That is the same follow-the-chain
        # distinction the metadata and debug-panel traps are built on.
        log_extra["confluenceAtlTokenPresent"] = creds.get("hasToken", "") == "true"
        body = render_confluence_login_html(
            host, CONFLUENCE_VERSION, error="Sorry, your username and password are incorrect.",
        )
        content_type = "text/html; charset=utf-8"
    elif lpath.endswith("/login.action") or lpath in CONFLUENCE_PATHS:
        result_tag = "confluence-login"
        body = render_confluence_login_html(host, CONFLUENCE_VERSION)
        content_type = "text/html; charset=utf-8"
    else:
        # Path matched the matcher (e.g. via the OGNL prefilter) but no
        # specific renderer claimed it — defensive 404 + log so analysis
        # can grep for it.
        append_log({
            **log_context,
            "status": 404,
            "result": "confluence-miss",
            **log_extra,
        })
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    append_log({
        **log_context,
        "status": 200,
        "result": result_tag,
        **log_extra,
        "bytes": len(body),
    })
    return web.Response(
        status=200, body=body,
        headers={
            "Content-Type": content_type,
            # Mirror the X-Confluence-Request-Time header real Confluence
            # emits — gives wicket-aware scanners one more reason to keep
            # going past the login page.
            "X-Confluence-Request-Time": str(int(time.time() * 1000)),
            "Cache-Control": "no-store",
        },
    )


def render_nextjs_page_data(path: str) -> bytes:
    """Plausible response body for a Next.js ISR data fetch. Real
    `_next/data/<buildId>/<page>.json` returns a wrapped pageProps
    object; an empty-but-shaped JSON keeps Next.js-aware scanners
    moving past the fingerprint check without leaking specifics."""
    payload = {
        "pageProps": {},
        "__N_SSG": True,
    }
    return json.dumps(payload).encode("utf-8")


def render_nextjs_static_chunk() -> bytes:
    """`_next/static/chunks/pages/...js` is the build-output chunk; a
    minimal valid JS module is enough to look like a real chunk
    response."""
    body = (
        "(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push("
        "[[404],{}]);\n"
    )
    return body.encode("utf-8")


_NEXTJS_OVERLAY_SOURCES = (
    "app/page.tsx",
    "app/api/route.ts",
    "app/layout.tsx",
    "components/Header.tsx",
    "pages/index.tsx",
    "pages/_app.tsx",
    "src/server/handlers.ts",
)


def render_nextjs_error_overlay() -> bytes:
    """Plausible dev-mode error-overlay fragment with a per-hit
    synthetic source path. Real Next.js dev-mode error responses are
    HTML stack frames pointing at the offending source file; emitting
    one keeps Next.js-aware scanners moving without shipping a fixed
    literal across the sensor fleet."""
    source = secrets.choice(_NEXTJS_OVERLAY_SOURCES)
    line = secrets.randbelow(180) + 1
    col = secrets.randbelow(80) + 1
    body = (
        "<!doctype html>\n"
        "<html><body>\n"
        '<div data-nextjs-dialog>\n'
        f"  <pre>TypeError: undefined is not iterable\n"
        f"    at &lt;anonymous&gt; ({source}:{line}:{col})</pre>\n"
        "</div>\n"
        "</body></html>\n"
    )
    return body.encode("utf-8")


_NEXTJS_DEVMODE_QUERY_KEYS = ("file", "fileName", "line", "column", "name", "args", "path")


def _nextjs_extract_devmode_query(query_string: str) -> dict[str, str] | None:
    """Pull out the interesting query args scanners send to the
    dev-mode endpoints — `file=` is the IDE-launch file path, `name=`
    / `args=` / `path=` are the Server-Action variants. Empty result
    becomes None so we don't bloat the log on bare GETs."""
    if not query_string:
        return None
    out: dict[str, str] = {}
    try:
        parsed = parse_qsl(query_string, keep_blank_values=True)
    except Exception:
        return None
    for key, value in parsed:
        if key in _NEXTJS_DEVMODE_QUERY_KEYS and value:
            out[key] = value[:256]
    return out or None


async def _handle_sap_metadatauploader(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Fake SAP NetWeaver Visual Composer MetadataUploader (CVE-2025-31324
    / CVE-2017-9844 bait).

    GET → small SAP-formatted error envelope (real NetWeaver returns the
    same shape when invoked without a multipart body).
    POST → parse multipart parts, log filename/content-type/payload
    indicators, return the "OK: stored …" plaintext receipt scanners look
    for as a "shell installed" success marker. The handler does not
    actually store anything; the follow-up GET to the supposed shell URL
    still hits flux's path classifier and lands in the access log.
    """
    method = request.method
    content_type = request.headers.get("Content-Type", "")
    names: list[str] = []
    filenames: list[str] = []
    part_content_types: list[str] = []
    has_php_shell = False  # reused multipart helper flag; named _php for legacy
    if method not in {"GET", "HEAD"}:
        names, filenames, part_content_types, has_php_shell = extract_multipart_parts(
            request_body, content_type, FILE_UPLOAD_MAX_PARTS,
        )

    body_preview = ""
    if request_body:
        body_preview = request_body[:SAP_METADATAUPLOADER_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )

    lower_body = request_body[:SAP_METADATAUPLOADER_BODY_DECODE_LIMIT].lower() if request_body else b""
    has_jsp_shell = any(needle in lower_body for needle in _SAP_METADATAUPLOADER_SHELL_INDICATORS)
    has_xxe = any(needle in lower_body for needle in _SAP_METADATAUPLOADER_XXE_INDICATORS)

    if method in {"GET", "HEAD"}:
        result_tag = "sap-metadatauploader-probe"
    elif filenames:
        result_tag = "sap-metadatauploader-upload"
    else:
        # POST with no multipart filename — typically a CVE-2017-9844 XXE
        # or a malformed exploit. Distinguish so triage can sort the two.
        result_tag = "sap-metadatauploader-noupload"

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": result_tag,
        "sapMetadataUploaderPath": path,
        "sapMetadataUploaderMethod": method,
        "sapMetadataUploaderHasMultipart": "multipart/form-data" in content_type.lower(),
        "sapMetadataUploaderPartCount": len(names),
        "sapMetadataUploaderFieldNames": sorted(set(names))[:32],
        "sapMetadataUploaderFilenames": filenames[:32],
        "sapMetadataUploaderPartContentTypes": sorted(set(part_content_types))[:32],
        "sapMetadataUploaderHasJspShell": has_jsp_shell or has_php_shell,
        "sapMetadataUploaderHasXxe": has_xxe,
        "contentType": content_type[:120],
    }
    if body_preview:
        log_entry["bodyPreview"] = body_preview[:400]
    append_log(log_entry)

    headers = {
        # Banner pinned to a build in the CVE-2025-31324 public-disclosure
        # window — scanners deciding whether to ship the upload body don't
        # bail on a patched banner.
        "Server": "SAP NetWeaver Application Server / ABAP (7.50)",
        "Cache-Control": "no-store",
    }

    if method in {"GET", "HEAD"}:
        return web.Response(
            status=200,
            body=render_sap_metadatauploader_get_error(),
            headers={**headers, "Content-Type": "application/xml; charset=utf-8"},
        )

    # POST — return the "OK: stored …" receipt with the (first) uploaded
    # filename echoed back. The receipt path mirrors the documented SAP
    # `j2ee/cluster/apps` layout; scanners parse it to know which URL to
    # GET next for shell execution.
    receipt = render_sap_metadatauploader_post_ok(filenames[0] if filenames else "metadata.xml")
    return web.Response(
        status=200,
        body=receipt,
        headers={**headers, "Content-Type": "text/plain; charset=utf-8"},
    )


async def _handle_drupal(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    """Fake Drupal 8/9 `/user/register` endpoint with CVE-2018-7600
    payload capture.

    GET `/user/register` → minimal Drupal user-registration HTML with
    per-request `form_build_id` and `form_token` values (so a
    follow-up POST passes the framework-level form-cache lookup in a
    real installation).
    POST `/user/register` → Drupal AJAX-form JSON envelope; captures
    the full body (Drupalgeddon2 `mail[#post_render]` / `element_parents`
    chain) and flags `drupalHasDrupalgeddon2` + `drupalHasRcePayload`
    for triage.
    """
    method = request.method
    query_lower = (query_string or "").lower().encode("latin-1", errors="replace")

    body_preview = ""
    if request_body:
        body_preview = request_body[:DRUPAL_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )
    lower_body = request_body[:DRUPAL_BODY_DECODE_LIMIT].lower() if request_body else b""

    has_drupalgeddon2 = any(
        needle in query_lower or needle in lower_body
        for needle in _DRUPAL_DRUPALGEDDON2_INDICATORS
    )
    has_rce_payload = any(needle in lower_body for needle in _DRUPAL_RCE_PAYLOAD_INDICATORS)

    # Result tag picks the most specific applicable shape.
    if method in {"POST", "PUT"}:
        if has_drupalgeddon2 and has_rce_payload:
            result_tag = "drupal-user-register-rce-attempt"
        elif has_drupalgeddon2:
            result_tag = "drupal-user-register-drupalgeddon2"
        else:
            result_tag = "drupal-user-register-post"
    else:
        result_tag = "drupal-user-register-probe"

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": result_tag,
        "drupalPath": path,
        "drupalMethod": method,
        "drupalHasDrupalgeddon2": has_drupalgeddon2,
        "drupalHasRcePayload": has_rce_payload,
    }
    if body_preview:
        log_entry["bodyPreview"] = body_preview[:400]
    if query_string:
        log_entry["queryPreview"] = query_string[:400]
    append_log(log_entry)

    headers = {
        # The X-Generator response header is the Drupal fingerprint
        # scanners grep when a meta tag would be filtered by an
        # upstream proxy. Mirror Drupal's default banner.
        "X-Generator": f"Drupal {DRUPAL_VERSION} (https://www.drupal.org)",
        "Cache-Control": "no-store, private",
    }

    if method in {"POST", "PUT"}:
        body = render_drupal_ajax_response()
        return web.Response(
            status=200,
            body=body,
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    form_build_id = "form-" + secrets.token_urlsafe(20)
    form_token = secrets.token_urlsafe(32)
    body = render_drupal_user_register_html(
        DRUPAL_VERSION, form_build_id, form_token,
    )
    return web.Response(
        status=200,
        body=body,
        headers={**headers, "Content-Type": "text/html; charset=utf-8"},
    )


async def _handle_joomla4_config(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
) -> web.Response:
    """Joomla 4 `/api/index.php/v1/config/application` — CVE-2023-23752
    unauth WebService config-disclosure trap.

    The `?public=true` query flips the vulnerability from
    `{"errors":[...access denied...]}` to a full JSON dump of
    `configuration.php`; we mirror both shapes so non-trigger probes
    still get a plausible auth-failure envelope and exploit probes get
    a configuration-shaped JSON with a replay-fireable canary.
    """
    method = request.method
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    # The Joomla WebService endpoint accepts `?public=true` as the
    # disclosure trigger. Match the presence of `public=true` anywhere
    # in the query string — scanners often tack on additional params.
    public = "public=true" in (query_string or "").lower()
    # Pull the component slug from the trailing path segment so
    # `/api/index.php/v1/config/com_users` reflects back as `com_users`
    # in the response (real Joomla 4 WebService behavior).
    lpath = path.lower().rstrip("/")
    component = lpath.rsplit("/", 1)[-1] or "application"

    tracebit_response: dict[str, object] | None = None
    if API_KEY and public:
        tracebit_response = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
    if tracebit_response is None:
        tracebit_response = {}

    body = render_joomla4_config_application(tracebit_response, component, public)

    if public:
        result_tag = "joomla4-config-disclosure"
    else:
        result_tag = "joomla4-config-access-denied"

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": result_tag,
        "joomla4ConfigPath": path,
        "joomla4ConfigMethod": method,
        "joomla4ConfigComponent": component,
        "joomla4ConfigPublic": public,
        "joomla4ConfigVersion": JOOMLA4_CONFIG_VERSION,
        "bytes": len(body),
    }
    if query_string:
        log_entry["queryPreview"] = query_string[:400]
    append_log(log_entry)

    headers = {
        # Real Joomla 4 ships behind PHP — `X-Powered-By` is the
        # fingerprint slot scanners diff. Pinned version inside the
        # CVE-2023-23752 public-disclosure window so version-gated
        # scanners don't bail.
        "X-Powered-By": "PHP/8.1.27",
        "Cache-Control": "no-store, private",
        "Content-Type": "application/vnd.api+json",
    }
    return web.Response(status=200, body=body, headers=headers)


async def _handle_tomcat_path_bypass(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
) -> web.Response:
    """Tomcat `/..;/env.*` path-normalization bypass + env-file harvest.

    Returns a plausible frontend env-config JS body with the Tracebit
    AWS canary embedded in `REACT_APP_AWS_*` / `VITE_AWS_*` /
    `NEXT_PUBLIC_AWS_*` slots scrapers grep on. Logs
    `tomcatHasPathNormBypass=true` so the evasion-aware scanner shape
    is separately triageable from generic env-file canary hits.
    """
    method = request.method
    host = str(log_context.get("host", ""))
    request_id = str(log_context.get("requestId", ""))
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    # Extract the filename for the body comment + log.
    filename = path.rsplit("/", 1)[-1] or "env.js"

    tracebit_response: dict[str, object] | None = None
    if API_KEY:
        tracebit_response = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
    if tracebit_response is None:
        tracebit_response = {}

    body = render_tomcat_path_bypass_env_js(tracebit_response, filename)

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": "tomcat-path-bypass-env",
        "tomcatBypassPath": path,
        "tomcatBypassMethod": method,
        "tomcatBypassFilename": filename,
        "tomcatHasPathNormBypass": True,
        "bytes": len(body),
    }
    if query_string:
        log_entry["queryPreview"] = query_string[:400]
    append_log(log_entry)

    headers = {
        # Real Tomcat sets the `Server` header; pin a recent 9.x build
        # inside the public-disclosure window for the path-parameter
        # bypass family so version-gated scanners don't bail.
        "Server": "Apache-Coyote/1.1",
        "Cache-Control": "no-store, private",
        "Content-Type": "application/javascript; charset=utf-8",
    }
    return web.Response(status=200, body=body, headers=headers)


def webhook_receiver_token(path: str) -> str | None:
    """Return the token out of a webhook-delivery path, or None.

    Deliberately narrow. `/api/v1/webhook/<token>/event` and its close
    spellings are a delivery address: the token identifies a
    subscription and the trailing verb says what is being delivered.
    `/api/v1/webhooks` (the management collection) and
    `/api/v1/webhook/<token>` (the subscription itself) are different
    surfaces with different responses, so neither is claimed here.
    """
    if not WEBHOOK_RECEIVER_ENABLED:
        return None
    m = _WEBHOOK_RECEIVER_RE.match(path)
    return m.group("token") if m else None


def is_webhook_receiver_path(path: str) -> bool:
    return webhook_receiver_token(path) is not None


async def _handle_webhook_receiver(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Accept a webhook delivery and keep what was in it.

    A delivery endpoint that 404s gets one attempt and a body hash. One
    that acknowledges gets the payload, and — because senders retry and
    batch against an endpoint that works — usually more than one.

    The acknowledgement carries no credential-shaped field at all: a
    receiver has no reason to hand the sender a secret, so there is
    nothing here that could become a fixed literal. `deliveryId` is a
    per-request uuid4, which is what a real receiver echoes back.
    """
    token = webhook_receiver_token(path) or ""
    preview = request_body[:WEBHOOK_RECEIVER_BODY_PREVIEW_LIMIT].decode("utf-8", "replace")
    payload = {
        "ok": True,
        "deliveryId": str(uuid.uuid4()),
        "receivedAt": utc_now(),
    }
    body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    append_log({
        **log_context,
        "status": 200,
        "result": "webhook-delivery",
        # The token is the sender's own identifier for wherever it
        # thought it was posting. When it is a credential shape, the
        # echo observer has already classified it on this same line.
        "webhookToken": token[:128],
        "webhookMethod": request.method,
        "webhookContentType": request.headers.get("Content-Type", "")[:120],
        "webhookBodyPreview": preview,
        "bytes": len(body),
    })
    return web.Response(
        status=200, body=body,
        headers={"Content-Type": "application/json; charset=utf-8"},
    )


async def _handle_graphql(
    request: web.Request,
    log_context: dict[str, object],
    request_id: str,
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    """Fake GraphQL endpoint — dispatches by query classification.

    GET    → GraphiQL bootstrap HTML.
    POST `?query=` / `{"query":"... __schema ..."}`
           → introspection schema (no canary; baited at the data hop).
    POST `{"query":"mutation { login(username, password) { token } }"}`
           → AuthPayload with the Tracebit AWS canary as `token`,
           captures the username, logs `graphqlHasPassword`.
    POST `{"query":"{ currentUser { apiToken awsAccessKeyId ... } }"}`
           → data response with the canary in every credential-shaped
           field; per-hit synthetic for `refreshToken` / `webhookSecret`.
    Anything else (malformed body, unrecognised query) → a plausible
    `Syntax Error` envelope so the scanner doesn't bail on us.
    """
    method = request.method
    host = str(log_context.get("host", ""))
    content_type_req = request.headers.get("Content-Type", "")
    client_ip = str(log_context.get("clientIp", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    if method in {"GET", "HEAD"}:
        body = render_graphiql_html(host, path)
        append_log({
            **log_context, "status": 200, "result": "graphql-playground",
            "graphqlPath": path, "graphqlMethod": method, "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={"Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store"},
        )

    query_text = _graphql_extract_query(request_body, content_type_req, query_string)
    classification = _graphql_classify(query_text)
    operation_name = _graphql_extract_operation_name(request_body, query_string)

    log_extra: dict[str, object] = {
        "graphqlPath": path,
        "graphqlMethod": method,
        "graphqlClassification": classification or "empty",
    }
    if operation_name:
        log_extra["graphqlOperationName"] = operation_name
    if query_text:
        log_extra["graphqlQueryPreview"] = _graphql_redact_passwords(query_text)[:400]

    if classification == "introspection":
        body = render_graphql_introspection_response()
        result_tag = "graphql-introspection"
        append_log({**log_context, "status": 200, "result": result_tag, **log_extra, "bytes": len(body)})
        return web.Response(
            status=200, body=body,
            headers={"Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store"},
        )

    tracebit_response: dict[str, object] | None = None
    canary_status = ""
    if classification in {"credential-field", "auth-mutation"} and API_KEY:
        tracebit_response = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
        if tracebit_response is None:
            canary_status = "issue-failed"

    if classification == "credential-field" and tracebit_response is not None:
        body = render_graphql_user_canary(tracebit_response)
        result_tag = "graphql-credential-canary"
        canary_status = "issued"
    elif classification == "auth-mutation":
        username = _graphql_extract_username(query_text, request_body)
        has_password = _graphql_has_password(query_text, request_body)
        if username:
            log_extra["graphqlUsername"] = username
        log_extra["graphqlHasPassword"] = has_password
        if tracebit_response is not None:
            body = render_graphql_auth_payload(tracebit_response)
            result_tag = "graphql-auth-canary"
            canary_status = "issued"
        else:
            # No API key — return a generic InvalidCredentials so the
            # scanner doesn't bail on "endpoint is broken", but no
            # canary leaves the host.
            body = render_graphql_generic_error("Invalid credentials")
            result_tag = "graphql-auth-error"
    elif classification == "mutation":
        body = render_graphql_generic_error("Cannot execute mutation: permission denied")
        result_tag = "graphql-mutation-denied"
    elif classification == "query":
        body = render_graphql_generic_error("Cannot query field on type 'Query'")
        result_tag = "graphql-query-unknown"
    else:
        # Empty / unparseable body — a Syntax Error envelope is what a
        # real graphql server emits.
        body = render_graphql_generic_error()
        result_tag = "graphql-syntax-error"

    log_entry: dict[str, object] = {
        **log_context, "status": 200, "result": result_tag, **log_extra, "bytes": len(body),
    }
    if canary_status:
        log_entry["canaryStatus"] = canary_status
    if tracebit_response is not None:
        log_entry["canaryTypes"] = [k for k, v in tracebit_response.items() if v]
    append_log(log_entry)
    return web.Response(
        status=200, body=body,
        headers={"Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store"},
    )


async def _handle_spring_gateway(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    """Fake Spring Cloud Gateway Actuator surface (CVE-2022-22947 bait).

    GET  `/actuator/gateway/routes`                → fake routes list
        with embedded AWS canary in route metadata.
    GET  `/actuator/gateway/routes/{id}`           → individual route
        echo (same canary content).
    POST `/actuator/gateway/routes/{id}`           → accept SpEL-laden
        body, capture it, return 201 Created.
    POST `/actuator/gateway/refresh`               → 200 OK empty body.
    DELETE `/actuator/gateway/routes/{id}`         → 200 OK.
    GET  `/actuator/gateway/globalfilters`         → fake filter chain.
    GET  `/actuator/gateway/routefilters`          → empty filter set.
    GET  `/actuator/gateway/routepredicates`       → empty predicate set.

    The canary requirement gates the `tracebit_response` injection at
    dispatch time (handler is only reached when `API_KEY` is set —
    matches the `actuator-env` CanaryTrap behaviour).
    """
    method = request.method
    lpath = path.lower().rstrip("/")
    query_lower = (query_string or "").lower().encode("latin-1", errors="replace")

    body_preview = ""
    if request_body:
        body_preview = request_body[:SPRING_GATEWAY_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )
    lower_body = request_body[:SPRING_GATEWAY_BODY_DECODE_LIMIT].lower() if request_body else b""

    has_spel = any(
        needle in query_lower or needle in lower_body
        for needle in _SPRING_GATEWAY_SPEL_INDICATORS
    )

    # Identify which Spring Cloud Gateway sub-endpoint this is.
    is_refresh = lpath.endswith("/gateway/refresh")
    is_globalfilters = lpath.endswith("/gateway/globalfilters")
    is_routefilters = lpath.endswith("/gateway/routefilters")
    is_routepredicates = lpath.endswith("/gateway/routepredicates")
    is_routes_root = (
        lpath.endswith("/gateway/routes")
        and not (
            is_refresh or is_globalfilters or is_routefilters or is_routepredicates
        )
    )
    # `/gateway/routes/{id}` — id is everything after the last `routes/`
    # segment. Empty id = routes_root.
    route_id = ""
    if "/gateway/routes/" in lpath:
        route_id = lpath.rsplit("/gateway/routes/", 1)[-1]

    headers = {
        # Pin a banner inside the CVE-2022-22947 public-disclosure window —
        # Spring Cloud Gateway 3.1.0 is the canonical vulnerable build.
        "Server": "Spring Cloud Gateway/3.1.0",
        "Cache-Control": "no-store",
    }

    if method in {"POST", "PUT"} and route_id:
        result_tag = (
            "spring-gateway-spel-rce-attempt" if has_spel
            else "spring-gateway-route-add"
        )
        body = render_spring_gateway_route_created(route_id)
        log_entry: dict[str, object] = {
            **log_context,
            "status": 201,
            "result": result_tag,
            "springGatewayPath": path,
            "springGatewayMethod": method,
            "springGatewayRouteId": route_id[:120],
            "springGatewayHasSpel": has_spel,
        }
        if body_preview:
            log_entry["bodyPreview"] = body_preview[:400]
        append_log(log_entry)
        return web.Response(
            status=201,
            body=body,
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    if method == "DELETE" and route_id:
        append_log({
            **log_context,
            "status": 200,
            "result": "spring-gateway-route-delete",
            "springGatewayPath": path,
            "springGatewayMethod": method,
            "springGatewayRouteId": route_id[:120],
            "springGatewayHasSpel": False,
        })
        return web.Response(
            status=200, body=b"",
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    if is_refresh:
        append_log({
            **log_context,
            "status": 200,
            "result": "spring-gateway-refresh",
            "springGatewayPath": path,
            "springGatewayMethod": method,
            "springGatewayHasSpel": has_spel,
        })
        return web.Response(
            status=200, body=render_spring_gateway_refresh_ok(),
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    if is_globalfilters:
        body = render_spring_gateway_global_filters()
        append_log({
            **log_context,
            "status": 200,
            "result": "spring-gateway-globalfilters",
            "springGatewayPath": path,
            "springGatewayMethod": method,
            "bytes": len(body),
        })
        return web.Response(
            status=200, body=body,
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    if is_routefilters or is_routepredicates:
        # Empty arrays are the real response for stock deployments.
        tag = "spring-gateway-routefilters" if is_routefilters else "spring-gateway-routepredicates"
        append_log({
            **log_context, "status": 200, "result": tag,
            "springGatewayPath": path, "springGatewayMethod": method,
        })
        return web.Response(
            status=200, body=b"{}\n",
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    # GET /actuator/gateway/routes — the credential-leak endpoint. Needs
    # a Tracebit AWS canary to embed in the response. Match the
    # CanaryTrap issuance pattern.
    if is_routes_root or route_id:
        # Issue a per-request canary; falls back to a "no canary" envelope
        # if Tracebit is unreachable so we still capture a probe.
        request_id = str(log_context.get("requestId", ""))
        client_ip = str(log_context.get("clientIp", ""))
        host = str(log_context.get("host", ""))
        user_agent = str(log_context.get("userAgent", ""))
        proto = str(log_context.get("protocol", "http"))
        tb = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
        if tb is None:
            # Without a canary, return the routes list with empty AWS
            # values; the probe still lands in the log.
            tb = {"aws": {"awsAccessKeyId": "", "awsSecretAccessKey": "", "awsSessionToken": ""}}
        body = render_spring_gateway_routes_get(tb)
        tag = "spring-gateway-routes-list" if is_routes_root else "spring-gateway-route-get"
        log_entry = {
            **log_context,
            "status": 200,
            "result": tag,
            "springGatewayPath": path,
            "springGatewayMethod": method,
            "springGatewayRouteId": route_id[:120],
            "canaryTypes": [k for k, v in tb.items() if v],
            "bytes": len(body),
        }
        append_log(log_entry)
        return web.Response(
            status=200, body=body,
            headers={**headers, "Content-Type": "application/json; charset=utf-8"},
        )

    # Anything else under /actuator/gateway/* — log + 404.
    append_log({
        **log_context, "status": 404, "result": "spring-gateway-unknown",
        "springGatewayPath": path, "springGatewayMethod": method,
    })
    return web.Response(
        status=404, body=b"{}\n",
        headers={**headers, "Content-Type": "application/json; charset=utf-8"},
    )


async def _handle_nextjs(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    """Fake Next.js surface that catches server-side-JavaScript
    injection probes via `?cmd=<base64>`. Decodes the payload, logs the
    probe shape, and reflects a simulated `echo` result back when the
    payload contains a literal `var cmd = "echo X"` — designed to
    invite a follow-up exploitation request."""
    body_preview = ""
    if request_body:
        body_preview = request_body[:NEXTJS_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )

    decoded_cmd = _nextjs_decode_cmd_param(query_string)
    has_ssjs = _nextjs_has_ssjs(decoded_cmd) or _nextjs_has_ssjs(body_preview)
    cmd_literal = (
        _nextjs_extract_cmd_literal(decoded_cmd)
        or _nextjs_extract_cmd_literal(body_preview)
    )

    log_extra: dict[str, object] = {
        "nextjsPath": path,
        "nextjsHasSsjs": has_ssjs,
    }
    if decoded_cmd:
        log_extra["nextjsCmdDecoded"] = decoded_cmd[:512]
    if cmd_literal:
        log_extra["nextjsCmdLiteral"] = cmd_literal[:256]
    if body_preview:
        log_extra["bodyPreview"] = body_preview[:400]

    lpath = _nextjs_normalize_path(path).rstrip("/")
    devmode_qs = _nextjs_extract_devmode_query(query_string)
    if devmode_qs:
        log_extra["nextjsDevModeQuery"] = devmode_qs
    if has_ssjs:
        # Reflect a simulated echo so scanner thinks SSJS evaluation
        # worked. Anything other than `echo <safe-token>` falls back to
        # "ERROR" — matches the scanner's own catch-block sentinel and
        # avoids reflecting attacker bytes verbatim.
        result_tag = "nextjs-ssjs-probe"
        body = _nextjs_simulate_command(cmd_literal).encode("utf-8")
        content_type = "text/plain; charset=utf-8"
    elif lpath.startswith("/_next/data/"):
        result_tag = "nextjs-page-data"
        body = render_nextjs_page_data(path)
        content_type = "application/json; charset=utf-8"
    elif lpath.startswith("/_next/static/chunks/pages/"):
        result_tag = "nextjs-static-chunk"
        body = render_nextjs_static_chunk()
        content_type = "application/javascript; charset=utf-8"
    elif lpath == "/__nextjs_action" or lpath.startswith("/__nextjs_action/"):
        # Server Actions endpoint. POST bodies are React Server
        # Component payloads (multipart or RSC text/x-component); any
        # bytes here are interesting capture. Return the empty 200
        # shape a real Server Action returns when the action resolves
        # to `void` — invites the scanner's follow-up exploit body.
        result_tag = "nextjs-server-action"
        body = b""
        content_type = "text/x-component; charset=utf-8"
    elif lpath == "/__nextjs_launch-editor":
        # Dev-mode IDE-launch endpoint. Real Next.js calls the
        # configured editor to open a file at the path given by the
        # `file=` query arg; in vulnerable versions this has been a
        # pre-auth RCE shape (CVE-2021-37699-class). Returning
        # `{"opened":true}` makes the scanner believe the launch
        # succeeded, inviting a second probe with a more interesting
        # file path.
        result_tag = "nextjs-launch-editor"
        body = b'{"opened":true}'
        content_type = "application/json; charset=utf-8"
    elif lpath in (
        "/__nextjs_error_overlay",
        "/__nextjs_original-stack-frame",
        "/__nextjs_stack_frame",
    ):
        # Dev-mode error overlay endpoints. Real Next.js returns an
        # HTML fragment naming the source file + line; emit one with a
        # per-hit synthetic file path so the response varies per hit
        # (no fixed literal across sensors) while staying plausible.
        result_tag = "nextjs-error-overlay"
        body = render_nextjs_error_overlay()
        content_type = "text/html; charset=utf-8"
    elif lpath.startswith("/__nextjs_"):
        # Any other dev-mode `__nextjs_*` endpoint — log under a
        # dedicated tag so we can see what variants scanners probe
        # next, and return the empty-but-shaped 200 a real dev-mode
        # surface usually emits.
        result_tag = "nextjs-devmode-other"
        body = b"{}"
        content_type = "application/json; charset=utf-8"
    else:
        # `/api/*` route hit without an SSJS payload — return an empty
        # JSON object, the canonical "endpoint exists but returned
        # nothing" shape from a Next.js API route.
        result_tag = "nextjs-api"
        body = b"{}"
        content_type = "application/json; charset=utf-8"

    append_log({
        **log_context,
        "status": 200,
        "result": result_tag,
        **log_extra,
        "bytes": len(body),
    })
    return web.Response(
        status=200, body=body,
        headers={
            "Content-Type": content_type,
            "Cache-Control": "no-store",
            # Set a plausible build-id header — real Next.js does not emit
            # this on every response, but emitting it on the data routes
            # mirrors the shape scanners look for.
            "X-Powered-By": "Next.js",
        },
    )


async def _handle_webshell(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
) -> web.Response:
    query_params = parse_qs(query_string, keep_blank_values=True) if query_string else {}
    content_type = request.headers.get("Content-Type", "")
    form_params = parse_form_body(request_body, content_type)
    cookies = parse_cookies(request.headers.get("Cookie", ""))
    command_source, command_key, command = extract_webshell_command(
        query_params, form_params, cookies, request.headers,
    )

    body_preview = ""
    if request_body:
        body_preview = request_body[:WEBSHELL_BODY_DECODE_LIMIT].decode("utf-8", errors="replace")

    output = simulate_command_output(command) if command else ""
    payload = render_webshell_page(command=command, output=output)

    log_entry = {
        **log_context,
        "status": 200,
        "result": "webshell-command" if command else "webshell-probe",
        "webshellPath": path,
        "commandSource": command_source,
        "commandKey": command_key,
        "command": command,
        "simulatedOutputBytes": len(output),
        "cookieNames": sorted(cookies.keys()),
        "queryParamNames": sorted(query_params.keys()),
        "formParamNames": sorted(form_params.keys()),
        "contentType": content_type[:120],
    }
    if body_preview:
        log_entry["bodyPreview"] = body_preview
    append_log(log_entry)

    return web.Response(
        status=200, body=payload,
        headers={
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "no-store",
        },
    )


async def _handle_file_upload(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    request_body: bytes,
) -> web.Response:
    """Respond to KCFinder / jquery.filer / blueimp file-upload probe paths.

    GET → return a presence-detection-friendly response per family.
    POST → parse multipart parts (filenames, content-types, php-shell
    indicator) and return a plausible "uploaded" envelope so the scanner
    sends its next request (e.g. fetching the uploaded shell via GET).
    All multipart bytes are already covered by the request envelope's
    bodySha256; this handler adds per-part fields for triage.
    """
    family = _file_upload_family(path)
    method = request.method
    content_type = request.headers.get("Content-Type", "")
    names, filenames, part_content_types, has_php_shell = (
        ([], [], [], False)
        if method in {"GET", "HEAD"}
        else extract_multipart_parts(request_body, content_type, FILE_UPLOAD_MAX_PARTS)
    )
    body_preview = ""
    if request_body:
        # Decoded preview is best-effort — multipart bytes are mostly text
        # in the parts we care about (filenames, php source), and the
        # `replace` errors handler keeps the field safe to JSON-encode.
        body_preview = request_body[:FILE_UPLOAD_BODY_DECODE_LIMIT].decode(
            "utf-8", errors="replace",
        )

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": "file-upload-attempt" if method == "POST" else "file-upload-probe",
        "fileUploadFamily": family,
        "fileUploadPath": path,
        "fileUploadMethod": method,
        "fileUploadHasMultipart": "multipart/form-data" in content_type.lower(),
        "fileUploadPartCount": len(names),
        "fileUploadFieldNames": sorted(set(names))[:32],
        "fileUploadFilenames": filenames[:32],
        "fileUploadPartContentTypes": sorted(set(part_content_types))[:32],
        "fileUploadHasPhpShell": has_php_shell,
        "contentType": content_type[:120],
    }
    if body_preview:
        log_entry["bodyPreview"] = body_preview
    append_log(log_entry)

    # Build per-family response. HEAD shares the GET response shape so
    # the Content-Type advertised is correct; aiohttp strips the body.
    body: bytes
    response_content_type: str
    if family == "kcfinder":
        if method == "POST":
            body = render_kcfinder_upload_response(filenames or ["upload.txt"])
            response_content_type = "text/plain; charset=utf-8"
        elif "browse" in path.lower() or "kcfinder.php" in path.lower():
            body = render_kcfinder_browse_html()
            response_content_type = "text/html; charset=utf-8"
        else:
            # GET to upload.php → return an "ok, ready to receive" page that
            # still references the upload form, so the scanner POSTs next.
            body = render_kcfinder_browse_html()
            response_content_type = "text/html; charset=utf-8"
    elif family == "jquery-filer":
        if method == "POST":
            body = render_jquery_filer_upload_response(filenames)
            response_content_type = "application/json; charset=utf-8"
        elif path.lower().endswith("readme.txt"):
            body = render_jquery_filer_readme()
            response_content_type = "text/plain; charset=utf-8"
        else:
            # GET on /<prefix>/jquery.filer/php/upload.php → JSON empty-OK
            # so scanners that probe with GET-before-POST see a 200.
            body = b'{"OK":1,"files":[]}\n'
            response_content_type = "application/json; charset=utf-8"
    else:
        # blueimp-jquery-file-upload — server/php/ enumerates already-uploaded
        # files on GET (we return an empty list) and accepts POST uploads.
        body = render_blueimp_upload_response(filenames if method == "POST" else [])
        response_content_type = "application/json; charset=utf-8"

    return web.Response(
        status=200, body=body,
        headers={
            "Content-Type": response_content_type,
            "Cache-Control": "no-store",
        },
    )


async def _handle_cmd_injection(
    request: web.Request,
    log_context: dict[str, object],
    path: str,
    query_string: str,
    request_body: bytes,
    request_id: str,
) -> web.Response:
    """Respond to admin-config command-injection probes and CGI printenv
    leaks. See the CMD_INJECTION_ENABLED block at the top of this module
    for the design — most cmds get plausible static output, credential-file
    cmds get a fresh Tracebit canary in the response body."""
    method = request.method
    lpath = path.lower()
    is_printenv = lpath in {"/printenv", "/cgi-bin/printenv", "/cgi-bin/test-cgi"}

    query_params = parse_qs(query_string, keep_blank_values=True) if query_string else {}
    content_type_req = request.headers.get("Content-Type", "")
    form_params = parse_form_body(request_body, content_type_req)
    cmd_source, cmd_key, command = extract_cmd_injection_command(query_params, form_params)

    # /printenv-shape paths behave as if the cmd was 'printenv' regardless
    # of any query — that's the whole point of those CGI scripts.
    family = ""
    if is_printenv:
        family = "env"
    elif command:
        family = classify_cmd_injection_command(command)

    # Decide whether to mint a canary. Only the credential-file probes get
    # one; everything else returns static text. Per-IP cache caps the
    # quota burn from repeated `cat .aws/credentials` from the same source.
    needs_canary = family in {"creds-aws", "creds-aws-config", "env"}
    tracebit_response: dict[str, object] | None = None
    canary_status = ""
    client_ip = str(log_context.get("clientIp", ""))
    host = str(log_context.get("host", ""))
    user_agent = str(log_context.get("userAgent", ""))
    proto = str(log_context.get("protocol", ""))

    if needs_canary and API_KEY:
        tracebit_response = await _get_or_issue_canary(
            ("aws",), client_ip, request_id, host, user_agent, path, proto,
        )
        if tracebit_response is None:
            canary_status = "issue-failed"
            # Fall through to a static response — better to look alive
            # than to 502 and tell the scanner to skip us.
            needs_canary = False

    body: bytes = b""
    if family == "creds-aws" and tracebit_response is not None:
        body = render_aws_credentials_ini(tracebit_response)
        canary_status = "issued"
    elif family == "creds-aws-config" and tracebit_response is not None:
        body = render_aws_config_ini(tracebit_response)
        canary_status = "issued"
    elif family == "env" and tracebit_response is not None:
        body = render_printenv_dump(tracebit_response, host=host)
        canary_status = "issued"
    elif family == "passwd":
        body = render_fake_passwd()
    elif family in {"id", "whoami", "hostname", "uname", "pwd", "ls"}:
        body = simulate_command_output(command).encode("utf-8")
    elif command and family == "unknown":
        # Many shells produce no output for builtins / assignments. Empty
        # body avoids leaking a "this is fake" canned error message.
        body = b""
    elif not command and not is_printenv:
        # GET /admin/config with no cmd — return a small landing page so
        # the scanner moves on to its next step instead of bailing.
        body = (
            b"<!doctype html>\n<html><head><title>Admin Config</title></head>"
            b"<body><h1>Admin Configuration</h1>"
            b"<p>Use ?cmd=&lt;command&gt; to inspect runtime state.</p>"
            b"</body></html>\n"
        )

    if is_printenv:
        result_tag = "cmd-injection-printenv"
        content_type = "text/plain; charset=utf-8"
    elif family in {"creds-aws", "creds-aws-config", "env"} and tracebit_response is not None:
        result_tag = "cmd-injection-creds-leak"
        # Mimic the file the cmd asked for.
        content_type = "text/plain; charset=utf-8"
    elif command:
        result_tag = f"cmd-injection-command"
        content_type = "text/plain; charset=utf-8" if family != "" else "text/plain; charset=utf-8"
    else:
        result_tag = "cmd-injection-probe"
        content_type = "text/html; charset=utf-8"

    log_entry: dict[str, object] = {
        **log_context,
        "status": 200,
        "result": result_tag,
        "cmdInjectionPath": path,
        "cmdSource": cmd_source,
        "cmdKey": cmd_key,
        "cmd": command,
        "cmdFamily": family,
        "method": method,
        "outputBytes": len(body),
    }
    if canary_status:
        log_entry["canaryStatus"] = canary_status
    if tracebit_response is not None:
        log_entry["canaryTypes"] = [k for k, v in tracebit_response.items() if v]
    append_log(log_entry)

    return web.Response(
        status=200, body=body,
        headers={
            "Content-Type": content_type,
            "Cache-Control": "no-store",
        },
    )


async def _send_canary_trap(
    request: web.Request,
    trap: "CanaryTrap",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
    result_prefix: str = "",
    extra_log: "dict[str, object] | None" = None,
) -> web.Response:
    """Serve `trap`'s renderer with a freshly issued canary.

    `result_prefix` and `extra_log` let a caller that reached this trap by
    an indirect route (currently the `/@fs/` resolver) keep its own
    result tag and log fields without duplicating the issue/render/log
    body. They default to empty so the direct path is unchanged.
    """
    log_context = {**log_context, **(extra_log or {})}
    tag = f"{result_prefix}{trap.name}"
    if trap.canary_types:
        tracebit_response = await _get_or_issue_canary(
            trap.canary_types, client_ip, request_id, host, user_agent, path, proto,
        )
        if tracebit_response is None:
            append_log({**log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": f"{tag}-error"})
            return _credential_failure_response()
    else:
        # Traps whose renderer mints its own per-hit credential need no
        # Tracebit issuance. Calling the API anyway would spend quota on
        # a canary nothing reads and would make an upstream blip 404 a
        # trap that has no upstream dependency.
        tracebit_response = {}

    try:
        # Renderers that need to stay self-consistent with the host the
        # client actually asked for read `_requestHost`. A deploy config
        # naming `deploy.internal` is obviously bait; one naming the host
        # the scanner just fetched it from is what a real checked-in
        # config looks like. Enriching only the dict handed to `render`
        # keeps `canaryTypes` below computed over the unmodified Tracebit
        # response.
        body = trap.render({
            **tracebit_response,
            "_requestHost": host,
            "_requestId": request_id,
        })
    except Exception as exc:  # noqa: BLE001 — render bugs shouldn't crash the sensor
        append_log({
            **log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": f"{tag}-render-error",
            "error": _exc_detail(exc)[:400],
        })
        return _credential_failure_response()

    response = web.Response(status=200, body=body)
    response.headers["Content-Type"] = trap.content_type
    response.headers["Cache-Control"] = "no-store"
    for header_name, header_value in trap.extra_headers(tracebit_response):
        response.headers[header_name] = header_value

    append_log({
        **log_context,
        "status": 200,
        "result": tag,
        "canaryTypes": [k for k, v in tracebit_response.items() if v],
        "bytes": len(body),
    })
    return response


_DEBUGBAR_SAMPLE_ROUTES: tuple[tuple[str, str], ...] = (
    ("GET", "/admin/settings"),
    ("POST", "/admin/settings/storage"),
    ("GET", "/api/v1/orders"),
    ("POST", "/api/v1/auth/login"),
    ("GET", "/dashboard"),
)


def _debugbar_meta(host: str, stored_id: str, index: int) -> dict[str, object]:
    """The `__meta` block Debugbar stores alongside every captured request.

    Times run backwards from a fixed offset per index rather than from the
    clock, so two fetches of the same id do not disagree about when the
    request happened.
    """
    method, uri = _DEBUGBAR_SAMPLE_ROUTES[index % len(_DEBUGBAR_SAMPLE_ROUTES)]
    utime = 1755000000.0 - (index * 137.42)
    return {
        "id": stored_id,
        "datetime": time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(utime)),
        "utime": utime,
        "method": method,
        "uri": uri,
        "ip": "10.0.0.%d" % (11 + index),
    }


def render_debugbar_listing(host: str) -> bytes:
    """`op=list` — stored-request metadata only, no secret anywhere.

    This is deliberately not worth harvesting. It exists to name the ids
    that make step two reachable, which is what separates a client that
    reads our response from one walking a path list.
    """
    ids = _debugbar_stored_ids(host)
    listing = [_debugbar_meta(host, sid, i) for i, sid in enumerate(ids)]
    return json.dumps(listing, indent=2).encode("utf-8")


def render_debugbar_stored_request(
    r: dict[str, object], host: str, stored_id: str, index: int,
) -> bytes:
    """`op=get&id=<id>` — one captured request, in full.

    The AWS canary goes in the `request.env` dump, which is the slot a
    real Debugbar RequestDataCollector fills from `$_ENV` and the slot a
    harvester greps. It is repeated in a query binding because the
    `queries` panel is the other place a Laravel app leaks credentials,
    and a payload that carried it in only one of the two would read as
    hand-made to anyone who has seen a real dump. Every other
    credential-shaped field is a per-hit synthetic.
    """
    aws = _aws(r)
    key_id = str(aws.get("awsAccessKeyId", "") or "")
    secret = str(aws.get("awsSecretAccessKey", "") or "")
    token = str(aws.get("awsSessionToken", "") or "")
    meta = _debugbar_meta(host, stored_id, index)
    db_password = _fake_db_password()
    app_key = "base64:" + base64.b64encode(secrets.token_bytes(32)).decode("ascii")

    payload: dict[str, object] = {
        "__meta": meta,
        "php": {"version": "8.2.12", "interface": "fpm-fcgi"},
        "messages": {
            "count": 1,
            "messages": [{
                "message": "settings.storage.updated",
                "message_html": None,
                "is_string": True,
                "label": "info",
                "time": meta["utime"],
            }],
        },
        "time": {
            "start": meta["utime"],
            "end": float(meta["utime"]) + 0.184,
            "duration": 0.184,
            "duration_str": "184ms",
        },
        "memory": {"peak_usage": 4194304, "peak_usage_str": "4MB"},
        "queries": {
            "nb_statements": 2,
            "statements": [
                {
                    "sql": "select * from `settings` where `key` = ? limit 1",
                    "type": "query",
                    "bindings": ["storage.s3"],
                    "duration": 0.0021,
                    "connection": "mysql",
                },
                {
                    "sql": (
                        "update `settings` set `value` = ?, `secret` = ? "
                        "where `key` = ?"
                    ),
                    "type": "query",
                    "bindings": [key_id, secret, "storage.s3"],
                    "duration": 0.0038,
                    "connection": "mysql",
                },
            ],
        },
        "request": {
            "path_info": meta["uri"],
            "status_code": 200,
            "request_query": [],
            "request_request": {"driver": "s3"},
            "session_attributes": {
                "_token": secrets.token_urlsafe(24),
                "login_web": secrets.token_hex(20),
            },
            "env": {
                "APP_ENV": "production",
                "APP_DEBUG": "true",
                "APP_KEY": app_key,
                "APP_URL": f"https://{host}",
                "DB_CONNECTION": "mysql",
                "DB_HOST": "127.0.0.1",
                "DB_DATABASE": "app_prod",
                "DB_USERNAME": "app_prod",
                "DB_PASSWORD": db_password,
                "REDIS_PASSWORD": _fake_db_password(),
                "MAIL_PASSWORD": _fake_db_password(),
                "FILESYSTEM_DISK": "s3",
                "AWS_ACCESS_KEY_ID": key_id,
                "AWS_SECRET_ACCESS_KEY": secret,
                "AWS_SESSION_TOKEN": token,
                "AWS_DEFAULT_REGION": "us-east-1",
                "AWS_BUCKET": "app-prod-uploads",
            },
        },
    }
    return json.dumps(payload, indent=2).encode("utf-8")


# Assets carry no secret; they exist so a client that renders the toolbar
# does not get a broken page and give up before step two.
_DEBUGBAR_JS = (
    b"/*! DebugBar | (c) Maxime Bouroumeau-Fuseau and contributors */\n"
    b"if(typeof PhpDebugBar==='undefined'){var PhpDebugBar={};}\n"
    b"(function(w){PhpDebugBar.DebugBar=function(){};"
    b"PhpDebugBar.DebugBar.prototype.openHandler=null;})(window);\n"
)
_DEBUGBAR_CSS = (
    b"/*! DebugBar */\n"
    b"div.phpdebugbar{font-size:13px;background:#fff;border-top:1px solid #ccc}\n"
    b"div.phpdebugbar-header{background:#f5f5f5;min-height:37px}\n"
)


async def _send_laravel_debugbar(
    request: web.Request,
    dbg: "LaravelDebugbarRequest",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.Response:
    """Answer one step of the Debugbar stored-request protocol.

    `debugbarOp` and `debugbarIdKnown` go in the log line for every step,
    so a `open-list` followed by an `open-get` naming an id from that
    listing is reconstructable from the log alone — that chain is the
    behaviour this trap exists to separate from a flat path sweep.
    """
    log_context = {
        **log_context,
        "debugbarOp": dbg.kind,
        "debugbarStoredId": dbg.stored_id,
        "debugbarIdKnown": dbg.id_known,
    }

    if not dbg.issues_canary:
        if dbg.kind == "asset-js":
            body, ctype = _DEBUGBAR_JS, "application/javascript; charset=utf-8"
        elif dbg.kind == "asset-css":
            body, ctype = _DEBUGBAR_CSS, "text/css; charset=utf-8"
        elif dbg.kind == "clockwork":
            # Debugbar ships a Clockwork-compatible shim that returns an
            # empty object when the integration is not configured.
            body, ctype = b"{}\n", "application/json"
        else:
            # `index` and `open-list` both answer with the listing. A bare
            # `/_debugbar` is what a scanner tries before it knows the
            # `open` sub-path exists, and answering it with the listing is
            # what makes the sub-path discoverable at all.
            body = render_debugbar_listing(host)
            ctype = "application/json"
        append_log({
            **log_context, "status": 200,
            "result": f"laravel-debugbar-{dbg.kind}", "bytes": len(body),
        })
        return web.Response(
            status=200,
            body=b"" if request.method == "HEAD" else body,
            headers={
                "Content-Type": ctype,
                "Cache-Control": "no-store",
                "Content-Length": str(len(body)),
            },
        )

    tracebit_response = await _get_or_issue_canary(
        ("aws",), client_ip, request_id, host, user_agent, path, proto,
    )
    if tracebit_response is None:
        append_log({
            **log_context, "status": CREDENTIAL_FAILURE_STATUS,
            "result": "laravel-debugbar-open-get-error",
        })
        return _credential_failure_response()

    ids = _debugbar_stored_ids(host)
    # An id we never advertised still gets a payload — a client that
    # guessed is worth keeping on the hook, and Debugbar itself does not
    # distinguish. Which of the two happened is already in the log line.
    index = ids.index(dbg.stored_id) if dbg.id_known else 0
    stored_id = dbg.stored_id or ids[0]
    body = render_debugbar_stored_request(tracebit_response, host, stored_id, index)
    append_log({
        **log_context, "status": 200, "result": "laravel-debugbar-open-get",
        "canaryTypes": [k for k, v in tracebit_response.items() if v],
        "bytes": len(body),
    })
    return web.Response(
        status=200,
        body=b"" if request.method == "HEAD" else body,
        headers={
            "Content-Type": "application/json",
            "Cache-Control": "no-store",
            "Content-Length": str(len(body)),
        },
    )


async def _send_cloud_imds(
    request: web.Request,
    imds: "CloudImdsRequest",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
    result_prefix: str = "cloud-imds",
) -> web.Response:
    """Answer one step of the role-credential protocol.

    The listing steps are served straight from a constant: they contain no
    secret, so they need no canary and cost nothing upstream. Only a
    request that names a role — or hits a container credential-provider
    endpoint — mints one.

    `imdsRole` goes in the log line for every step so the two-request
    chain is reconstructable: a `role-list` followed by a
    `role-credentials` naming the role we just handed out is a client that
    parsed our response, which is the behaviour this trap is here to
    separate from a flat dictionary sweep.

    `result_prefix` distinguishes how the request arrived. The metadata
    tree is reachable directly at our webroot and indirectly through the
    SSRF relay, and the two say different things about the client, so
    they must not share a result tag — but they serve byte-identical
    bodies, because a relay that returned something other than what the
    metadata service returns is not worth following.
    """
    log_context = {
        **log_context,
        "imdsKind": imds.kind,
        "imdsRole": imds.role,
    }

    if not imds.issues_canary:
        # The task-metadata step is the only listing that speaks JSON —
        # the ECS endpoint serves a document, not a directory — so it
        # picks its own content type below.
        body = (
            _cloud_imds_ecs_metadata_body() if imds.kind == "ecs-metadata"
            else _CLOUD_IMDS_IAM_INDEX_BODY if imds.kind == "iam-index"
            else _CLOUD_IMDS_INDEX_BODY if imds.kind == "index"
            else (CLOUD_IMDS_ROLE_NAME + "\n").encode("utf-8")
        )
        append_log({
            **log_context, "status": 200, "result": f"{result_prefix}-{imds.kind}",
            "bytes": len(body),
        })
        return web.Response(
            status=200,
            body=b"" if request.method == "HEAD" else body,
            headers={
                "Content-Type": (
                    "application/json; charset=utf-8"
                    if imds.kind == "ecs-metadata" else "text/plain"
                ),
                "Cache-Control": "no-store",
                # Real metadata services advertise the document size even
                # on HEAD; keeping it consistent avoids a length mismatch
                # between the HEAD probe and the GET that follows it.
                "Content-Length": str(len(body)),
            },
        )

    tracebit_response = await _get_or_issue_canary(
        ("aws",), client_ip, request_id, host, user_agent, path, proto,
    )
    if tracebit_response is None:
        append_log({
            **log_context, "status": CREDENTIAL_FAILURE_STATUS,
            "result": f"{result_prefix}-{imds.kind}-error",
        })
        return _credential_failure_response()

    render = (
        render_ecs_task_credentials if imds.kind == "ecs-credentials"
        else render_imds_role_credentials
    )
    body = render(tracebit_response)
    append_log({
        **log_context, "status": 200, "result": f"{result_prefix}-{imds.kind}",
        "canaryTypes": [k for k, v in tracebit_response.items() if v],
        "bytes": len(body),
    })
    return web.Response(
        status=200,
        body=b"" if request.method == "HEAD" else body,
        headers={
            "Content-Type": "application/json",
            "Cache-Control": "no-store",
            "Content-Length": str(len(body)),
        },
    )


def _ssrf_plain_response(request: web.Request, body: bytes) -> web.Response:
    return web.Response(
        status=200,
        body=b"" if request.method == "HEAD" else body,
        headers={
            "Content-Type": "text/plain",
            "Cache-Control": "no-store",
            "Content-Length": str(len(body)),
        },
    )


def _ssrf_json_response(request: web.Request, body: bytes) -> web.Response:
    """As above, for the trees that speak JSON rather than plain text.

    Azure answers every step with JSON, including the listing steps, so
    content type is part of looking like the real service.
    """
    return web.Response(
        status=200,
        body=b"" if request.method == "HEAD" else body,
        headers={
            "Content-Type": "application/json; charset=utf-8",
            "Cache-Control": "no-store",
            "Content-Length": str(len(body)),
        },
    )


async def _send_ssrf_relay(
    request: web.Request,
    relay: "SsrfRelayRequest",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.Response:
    """Answer a fetch-style request that pointed at a metadata endpoint.

    flux makes no outbound request here — the target is resolved against
    a table and answered from the same renderers the direct metadata trap
    uses. What comes back is therefore what the metadata service would
    have returned, which is the only response a client that chained this
    can act on.

    Every line carries `ssrfParam` and `ssrfTarget`. That is as much the
    point of the trap as the credential is: the client sweeps parameter
    spellings against one entry path because it cannot know which name
    the application used, so the log records the dictionary it is working
    from. A second request naming the role from our first response —
    through the relay — is a client that parsed the metadata document,
    not one replaying a static list.
    """
    log_context = {
        **log_context,
        "ssrfParam": relay.param,
        "ssrfTarget": relay.target,
        "ssrfHost": relay.host,
        "ssrfTargetPath": relay.target_path,
        "ssrfCloud": relay.cloud,
    }

    if relay.fs is not None:
        # The `file://` leg of the same sweep. Resolved through the shared
        # file-read table, so the body is byte-identical to what a bare
        # probe for the same file would get, and a credential file answers
        # with the same monitored canary a direct read would get. The
        # prefix keeps this population separable from the other read
        # surfaces.
        return await _send_fs_read(
            request, relay.fs, request_id, path,
            client_ip, host, user_agent, proto, log_context,
            result_prefix="ssrf-relay-file-",
            extra_log={
                "ssrfFsRequestedPath": relay.fs.requested_path[:512],
                "ssrfFsMatchDepth": relay.fs.match_depth,
            },
        )

    if relay.cloud == "azure" and relay.azure_kind in ("instance", "versions"):
        body = (
            _SSRF_AZURE_VERSIONS_BODY if relay.azure_kind == "versions"
            else _ssrf_azure_instance_body()
        )
        append_log({
            **log_context, "status": 200,
            "result": f"ssrf-relay-azure-{relay.azure_kind}", "bytes": len(body),
        })
        return _ssrf_json_response(request, body)

    if relay.cloud == "azure" and relay.azure_kind == "token":
        body = _ssrf_azure_token_body(relay.azure_resource)
        append_log({
            **log_context, "status": 200, "result": "ssrf-relay-azure-token",
            # The audience is the intent: which Azure service the client
            # wanted this identity's token for.
            "azureResource": relay.azure_resource[:256],
            "syntheticToken": True, "bytes": len(body),
        })
        return _ssrf_json_response(request, body)

    if relay.imds is not None:
        return await _send_cloud_imds(
            request, relay.imds, request_id, path,
            client_ip, host, user_agent, proto, log_context,
            result_prefix="ssrf-relay-aws",
        )

    if relay.cloud == "gcp" and relay.gcp_kind in ("index", "sa-index", "email"):
        body = (
            _SSRF_GCP_SA_INDEX_BODY if relay.gcp_kind == "sa-index"
            else (SSRF_GCP_SERVICE_ACCOUNT + "\n").encode("utf-8")
            if relay.gcp_kind == "email"
            else _SSRF_GCP_INDEX_BODY
        )
        append_log({
            **log_context, "status": 200,
            "result": f"ssrf-relay-gcp-{relay.gcp_kind}", "bytes": len(body),
        })
        return _ssrf_plain_response(request, body)

    if relay.cloud == "gcp" and relay.gcp_kind == "token":
        # Per-hit synthetic. Tracebit issues no GCP-shaped credential, so
        # this cannot be a monitored canary — but it must still be unique
        # per hit, because a fixed literal would be one string shared
        # across every deployment, and worth nothing on replay anyway.
        # What this branch measures is whether the client walked the tree
        # to reach it, which the log records either way.
        token = "ya29.c." + secrets.token_urlsafe(96)
        payload = {
            "access_token": token,
            "expires_in": 3599,
            "token_type": "Bearer",
        }
        body = json.dumps(payload).encode("utf-8")
        append_log({
            **log_context, "status": 200, "result": "ssrf-relay-gcp-token",
            "syntheticToken": True, "bytes": len(body),
        })
        return web.Response(
            status=200,
            body=b"" if request.method == "HEAD" else body,
            headers={
                "Content-Type": "application/json",
                "Cache-Control": "no-store",
                "Content-Length": str(len(body)),
            },
        )

    # A metadata host we serve, asked for a document we do not emulate
    # (`/latest/user-data`, an instance-identity document, a project-level
    # GCP key). A real metadata service 404s an unknown key, so this is
    # the honest answer as well as the cheap one — and the log still keeps
    # the target, which is the part worth having: it names the next
    # documents this tooling wants.
    append_log({
        **log_context, "status": 404, "result": "ssrf-relay-unmatched",
    })
    return web.Response(
        status=404, body=b"not found\n",
        headers={"Content-Type": "text/plain; charset=utf-8"},
    )


async def _send_vite_fs(
    request: web.Request,
    resolution: "ViteFsResolution",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.Response:
    """Answer a `/@fs/<absolute path>` read.

    Hit: delegate to the resolved trap so the body is byte-identical to
    what a bare probe for the same file would get, tagged `vite-fs-<trap>`
    so the FS-walk population stays separable from the webroot one.

    Miss: 404, which is what a real dev server returns for a file that
    isn't there. The requested path is logged either way — the dictionary
    is the point, and the misses describe the parts of the filesystem the
    scanner expects to find that we've chosen not to furnish.
    """
    extra_log: dict[str, object] = {
        # The absolute path the scanner named. This is the whole point of
        # the trap: it is the only field anywhere in flux that records an
        # attacker's belief about the target's on-disk layout.
        "viteFsRequestedPath": resolution.requested_path[:512],
        "viteFsRawSuffix": resolution.raw_suffix[:512],
        # 0 means the absolute path matched a trap entry outright; higher
        # means we had to strip that many leading directories to find the
        # file, i.e. the scanner used a prefix we've never catalogued.
        "viteFsMatchDepth": resolution.match_depth,
    }
    return await _send_fs_read(
        request, resolution, request_id, path,
        client_ip, host, user_agent, proto, log_context,
        result_prefix="vite-fs-", extra_log=extra_log,
    )


async def _send_fs_read(
    request: web.Request,
    target: "FsReadTarget | ViteFsResolution",
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
    result_prefix: str,
    extra_log: dict[str, object],
    miss_status: int = 404,
    miss_body: bytes = b"not found\n",
    miss_content_type: str = "text/plain; charset=utf-8",
) -> web.Response:
    """Serve one resolved arbitrary-file read, whatever surface asked.

    Hit: delegate to the resolved trap so the body is byte-identical to
    what a bare probe for the same file would get, tagged
    `<result_prefix><trap>` so each read surface's population stays
    separable from the webroot one and from the other surfaces.

    Miss: whatever the surface's own not-found looks like. A dev server
    404s; an appliance read primitive returns an empty 200, because the
    file simply was not there and the endpoint still worked. The
    requested path is logged either way — the dictionary is the point,
    and the misses describe the parts of the filesystem the scanner
    expects to find that we have chosen not to furnish.
    """
    if not target.resolved:
        append_log({
            **log_context, **extra_log,
            "status": miss_status, "result": f"{result_prefix}miss",
        })
        return web.Response(
            status=miss_status, body=miss_body,
            headers={"Content-Type": miss_content_type},
        )
    if target.system_file:
        # World-readable system file. Static body, no canary spent — the
        # signal is the request, and the response exists so the read
        # primitive behaves like a real one for the scanner's own
        # confirmation step.
        tag, render, content_type = _VITE_FS_SYSTEM_FILES[target.system_file]
        body = render()
        append_log({
            **log_context, **extra_log,
            "status": 200, "result": f"{result_prefix}{tag}",
        })
        return web.Response(
            status=200, body=body,
            headers={"Content-Type": content_type},
        )
    if target.trap is None:
        # Bare `/.env` — served by the original handler, not the table.
        return await _send_env(
            request, request_id, path,
            client_ip, host, user_agent, proto, log_context,
            result_prefix=result_prefix, extra_log=extra_log,
        )
    return await _send_canary_trap(
        request, target.trap, request_id, path,
        client_ip, host, user_agent, proto, log_context,
        result_prefix=result_prefix, extra_log=extra_log,
    )


def _build_backup_archive_body(r: dict[str, object], ext_family: str) -> tuple[bytes, str]:
    """Build the response body for a backup-archive trap hit.

    Returns (body_bytes, content_type). The body is a real archive in
    the matching format (gzip / zip / tar / bzip2 / xz) containing a
    fake `.env` + SQL dump with the Tracebit AWS canary embedded.
    For formats with no stdlib creator (`.7z`, `.rar`, `.zst`) we
    serve a tar.gz body under the claimed Content-Type — credential
    harvesters typically grep raw bytes for `AWS_ACCESS_KEY_ID=`
    and replay the canary regardless of whether they could actually
    extract the archive.
    """
    aws = _aws(r)
    db_pw = _fake_db_password()
    env_body = (
        f"AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}\n"
        f"AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}\n"
        f"AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}\n"
        f"AWS_DEFAULT_REGION=us-east-1\n"
        f"S3_BUCKET=prod-backups\n"
        f"DB_HOST=db.internal\n"
        f"DB_USER=appuser\n"
        f"DB_NAME=prod\n"
        f"DB_PASSWORD={db_pw}\n"
    ).encode("utf-8")
    sql_body = (
        f"-- MySQL dump 10.13  Distrib 8.0.35, for Linux (x86_64)\n"
        f"-- Host: db.internal    Database: prod\n"
        f"--\n"
        f"-- S3 backup creds (rotate via Vault; see INFRA-412):\n"
        f"--   AWS_ACCESS_KEY_ID={aws.get('awsAccessKeyId', '')}\n"
        f"--   AWS_SECRET_ACCESS_KEY={aws.get('awsSecretAccessKey', '')}\n"
        f"--   AWS_SESSION_TOKEN={aws.get('awsSessionToken', '')}\n"
        f"--\n"
        f"LOCK TABLES `users` WRITE;\n"
        f"INSERT INTO `users` VALUES (1,'admin','admin@internal.lan');\n"
        f"INSERT INTO `users` VALUES (2,'deploy','deploy@internal.lan');\n"
        f"UNLOCK TABLES;\n"
    ).encode("utf-8")

    members = ((".env", env_body), ("backup.sql", sql_body))

    def _make_tar(mode: str) -> bytes:
        buf = io.BytesIO()
        with tarfile.open(fileobj=buf, mode=mode) as t:
            for name, content in members:
                ti = tarfile.TarInfo(name=name)
                ti.size = len(content)
                t.addfile(ti, io.BytesIO(content))
        return buf.getvalue()

    if ext_family == "zip":
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
            for name, content in members:
                z.writestr(name, content)
        return buf.getvalue(), "application/zip"
    if ext_family in ("tar.gz", "tgz"):
        return _make_tar("w:gz"), "application/gzip"
    if ext_family in ("tar.bz2", "tbz2"):
        return _make_tar("w:bz2"), "application/x-bzip2"
    if ext_family in ("tar.xz", "txz"):
        return _make_tar("w:xz"), "application/x-xz"
    if ext_family == "tar":
        return _make_tar("w"), "application/x-tar"
    if ext_family == "sql.gz":
        return gzip.compress(sql_body), "application/gzip"
    if ext_family == "sql.bz2":
        return bz2.compress(sql_body), "application/x-bzip2"
    if ext_family == "sql":
        return sql_body, "application/sql; charset=utf-8"
    if ext_family == "gz":
        return gzip.compress(env_body), "application/gzip"
    if ext_family == "bz2":
        return bz2.compress(env_body), "application/x-bzip2"
    if ext_family == "xz":
        return lzma.compress(env_body), "application/x-xz"
    if ext_family == "7z":
        return _make_tar("w:gz"), "application/x-7z-compressed"
    if ext_family == "rar":
        return _make_tar("w:gz"), "application/x-rar-compressed"
    if ext_family == "zst":
        return _make_tar("w:gz"), "application/zstd"
    return _make_tar("w:gz"), "application/gzip"


async def _send_backup_archive(
    request: web.Request,
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.Response:
    """Backup-archive canary trap. Dispatch is gated on `API_KEY` and
    `BACKUP_ARCHIVE_ENABLED`; pattern match runs first via
    `is_backup_archive_path`."""
    ext_family = _backup_archive_match(path)
    tracebit_response = await _get_or_issue_canary(
        ("aws",), client_ip, request_id, host, user_agent, path, proto,
    )
    if tracebit_response is None:
        append_log({**log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": "backup-archive-error"})
        return _credential_failure_response()
    try:
        body, content_type = _build_backup_archive_body(tracebit_response, ext_family)
    except Exception as exc:  # noqa: BLE001 — render bugs shouldn't crash the sensor
        append_log({
            **log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": "backup-archive-render-error",
            "error": _exc_detail(exc)[:400],
        })
        return _credential_failure_response()
    response = web.Response(status=200, body=body)
    response.headers["Content-Type"] = content_type
    response.headers["Cache-Control"] = "no-store"
    filename = path.lstrip("/").replace('"', '')
    if filename:
        response.headers["Content-Disposition"] = f'attachment; filename="{filename}"'
    append_log({
        **log_context,
        "status": 200,
        "result": "backup-archive",
        "archiveExt": ext_family,
        "canaryTypes": [k for k, v in tracebit_response.items() if v],
        "bytes": len(body),
    })
    return response


async def _send_fake_git(
    request: web.Request,
    request_id: str,
    path: str,
    git_key: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.StreamResponse:
    """Serve the fake /.git tree.

    `path` is the raw (normalized) request path — used only for logging.
    `git_key` is the canonical lowercase `/.git/...` lookup key returned by
    extract_git_path(); it's what we use to look up the response body, so
    prefixed requests (e.g. `/login/.git/config`) find the same file as
    `/.git/config`. See LOGS.md — `path` in the log row is always the raw
    request so analysis can distinguish prefix-probe patterns from direct
    `/.git/` fetches.
    """
    global _active_slow_drips
    result = await _fake_git_get_or_build(client_ip, request_id, host, user_agent, path, proto)
    if result is None:
        append_log({**log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": "fake-git-error"})
        return _credential_failure_response()

    files, meta = result
    content = files.get(git_key)

    if content is None and f"{git_key}/" in files:
        # Directory asked for without its trailing slash — the same gap the
        # working-copy tree had, and the same fix. Apache (`DirectorySlash
        # On`, the default) and nginx both answer a bare directory name with
        # a 301 to the slash-terminated form rather than serving the index
        # inline, so that is what a really-exposed repository does.
        #
        # Every directory in this tree was reachable only by its
        # slash-terminated spelling, so a dumper walking `refs/heads`,
        # `objects/pack`, `hooks` or `branches` bare got a 404 for a
        # directory the tree does have. The redirect also measures whether
        # the client follows redirects at all, which most bare-socket
        # dictionary scanners do not.
        #
        # `Location` comes from the request path, not the canonical lookup
        # key, so a repository probed under a subpath prefix is redirected
        # inside its own prefix.
        location = f"{path.rstrip('/')}/"
        append_log({
            **log_context, "status": 301, "result": "fake-git-redirect",
            "commitSha": meta.get("commitSha", ""),
            "gitKey": git_key,
            "location": location,
        })
        return web.Response(
            status=301, body=b"",
            headers={"Location": location, "Content-Type": "text/html; charset=utf-8"},
        )

    if content is None:
        append_log({
            **log_context, "status": 404, "result": "fake-git-miss",
            "commitSha": meta.get("commitSha", ""),
            "gitKey": git_key,
        })
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    if git_key.endswith("/"):
        # Any trailing-slash /.git/... key is a directory autoindex — HTML,
        # matching Apache's mod_autoindex / nginx `autoindex on` fingerprint.
        # Covers `/.git/`, `/.git/refs/`, `/.git/hooks/`, `/.git/objects/`,
        # `/.git/logs/`, and their subdirectories.
        content_type = "text/html; charset=utf-8"
    elif git_key.startswith("/.git/objects/") and "/info/" not in git_key:
        content_type = "application/x-git-loose-object"
    else:
        content_type = "text/plain; charset=utf-8"

    # Decide whether this response actually drips, and charge the
    # concurrency semaphore only if it does.
    #
    # Three kinds of response are not drips and must not spend a slot:
    #
    #   * `HEAD` — sends no body at all.
    #   * Single-chunk bodies — the send loop sleeps *between* chunks, so
    #     a body that fits in one chunk is already an ordinary fast reply.
    #   * Directory autoindexes — a real `mod_autoindex` / `autoindex on`
    #     listing is generated in memory and returned immediately. Dripping
    #     one is both less faithful and, because a `/.git/` sweep walks many
    #     directories in a burst, the fastest way to exhaust the semaphore.
    #
    # That last case is what made this worth changing: with every response
    # charged a slot, a source enumerating `/.git/` subdirectories could
    # saturate the cap and start receiving `503 busy`. That drops the
    # engagement, and it is a tell — a real exposed repository does not
    # answer a directory walk with `busy`. Repo *files* still drip, which
    # is where the tarpit value actually is.
    is_autoindex = git_key.endswith("/")
    will_drip = (
        request.method != "HEAD"
        and not is_autoindex
        and len(content) > FAKE_GIT_DRIP_BYTES
    )
    if will_drip and _active_slow_drips >= TARPIT_MAX_CONNECTIONS:
        # Cap reached. Serve the file in one shot instead of refusing it.
        #
        # `503 busy` was the old answer, and it is the same class of tell the
        # rest of this file works to avoid: a real exposed repository does not
        # answer a file fetch with `busy`, and a source parallel enough to
        # saturate the cap gets a burst of them all at once — a fleet-wide
        # signature available to anyone who opens enough sockets. Dropping the
        # drip costs the tarpit hold for these responses but keeps the
        # engagement, keeps the canary in the served body, and spends no slot,
        # so the undripped path cannot itself exhaust anything.
        append_log({
            **log_context, "status": 200, "result": "fake-git-undripped",
            "fakeGitBytes": len(content),
        })
        return web.Response(
            status=200, body=content,
            headers={
                "Content-Type": content_type,
                "Cache-Control": "no-store",
            },
        )
    if will_drip:
        _active_slow_drips += 1
    try:
        response = web.StreamResponse(status=200, headers={
            "Content-Type": content_type,
            "Content-Length": str(len(content)),
            "Cache-Control": "no-store",
            "X-Accel-Buffering": "no",
        })
        bytes_sent = 0
        prepared = False
        try:
            await response.prepare(request)
            prepared = True
            append_log({
                **log_context,
                "status": 200,
                "result": "fake-git",
                "commitSha": meta.get("commitSha", ""),
                "rootTreeSha": meta.get("rootTreeSha", ""),
                "secretsBlobSha": meta.get("secretsBlobSha", ""),
                "canaryTypes": meta.get("canaryTypes", []),
                "fakeGitBytes": len(content),
                "fakeGitDripBytes": FAKE_GIT_DRIP_BYTES,
                "fakeGitDripIntervalMs": FAKE_GIT_DRIP_INTERVAL_MS,
            })
            if request.method == "HEAD":
                return response

            interval_s = FAKE_GIT_DRIP_INTERVAL_MS / 1000.0
            for offset in range(0, len(content), FAKE_GIT_DRIP_BYTES):
                chunk = content[offset:offset + FAKE_GIT_DRIP_BYTES]
                await response.write(chunk)
                bytes_sent += len(chunk)
                if will_drip and offset + FAKE_GIT_DRIP_BYTES < len(content):
                    await asyncio.sleep(interval_s)
        except (ConnectionResetError, asyncio.CancelledError, aiohttp.ClientConnectionError):
            # Scanners regularly close the socket between SYN-ACK and the
            # first byte of body — `prepare()` then raises the same family
            # of errors as `write()`. Treat both the same way so a fast
            # disconnect is a logged event, not an unhandled traceback.
            append_log({
                **log_context,
                "status": 200,
                "result": "fake-git-disconnect" if prepared else "fake-git-prepare-disconnect",
                "fakeGitBytesSent": bytes_sent,
                "commitSha": meta.get("commitSha", ""),
            })
        return response
    finally:
        if will_drip:
            _active_slow_drips -= 1


async def _send_fake_svn(
    request: web.Request,
    request_id: str,
    path: str,
    svn_key: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
) -> web.StreamResponse:
    """Serve the fake /.svn working copy.

    `path` is the raw (normalized) request path, logged as-is so prefix
    probes stay distinguishable from direct `/.svn/` fetches. `svn_key` is
    the canonical lowercase lookup key from extract_svn_path().

    Unlike fake-git this never drips: a working copy is a handful of small
    files, and the tarpit value there came from large loose objects that
    have no equivalent here.
    """
    result = await _fake_svn_get_or_build(client_ip, request_id, host, user_agent, path, proto)
    if result is None:
        append_log({**log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": "fake-svn-error"})
        return _credential_failure_response()

    files, meta = result
    content = files.get(svn_key)

    if content is None and f"{svn_key}/" in files:
        # Directory asked for without its trailing slash. Both Apache
        # (`DirectorySlash On`, the default) and nginx answer that with a
        # 301 to the slash-terminated form rather than serving the index
        # inline, so that is what a really-exposed working copy would do.
        #
        # This matters more than it looks: the bare `auth/svn.simple`
        # spelling — the credential-cache directory — is one of the most
        # requested paths in the whole dictionary, and treating it as a
        # miss would 404 the single most credential-relevant probe the
        # trap receives. Answering with the redirect also measures
        # something the 200 could not: whether the client follows
        # redirects at all, which most bare-socket dictionary scanners
        # do not.
        location = f"{path.rstrip('/')}/"
        append_log({
            **log_context, "status": 301, "result": "fake-svn-redirect",
            "svnKey": svn_key,
            "svnRevision": meta.get("svnRevision", ""),
            "location": location,
        })
        return web.Response(
            status=301, body=b"",
            headers={"Location": location, "Content-Type": "text/html; charset=utf-8"},
        )

    if content is None:
        append_log({
            **log_context, "status": 404, "result": "fake-svn-miss",
            "svnKey": svn_key,
            "svnRevision": meta.get("svnRevision", ""),
        })
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    if svn_key.endswith("/"):
        content_type = "text/html; charset=utf-8"
    elif svn_key == "/.svn/wc.db":
        content_type = "application/x-sqlite3"
    else:
        content_type = "text/plain; charset=utf-8"

    append_log({
        **log_context, "status": 200, "result": "fake-svn",
        "svnKey": svn_key,
        "svnRevision": meta.get("svnRevision", ""),
        "svnRepoUuid": meta.get("svnRepoUuid", ""),
        "svnAuthCached": meta.get("svnAuthCached", False),
        "canaryTypes": meta.get("canaryTypes", []),
        "bytes": len(content),
    })
    return web.Response(
        status=200,
        body=b"" if request.method == "HEAD" else content,
        headers={"Content-Type": content_type, "Cache-Control": "no-store"},
    )


def _match_robots_crawler_ua(user_agent: str) -> str | None:
    """Return the crawler-token that matched, or None.

    Match is a case-insensitive substring check against a small allowlist
    of well-known crawler UA tokens (`googlebot`, `bingbot`, ...). The
    allowlist deliberately mirrors what the tokens look like INSIDE a full
    UA string, so `Mozilla/5.0 (compatible; Googlebot/2.1; ...)` matches
    on `googlebot` without needing an exact-string comparison.

    Not a spoof-proof check -- a scanner can trivially set its UA to
    `Googlebot`. That's fine: the fallout of serving a stable robots.txt
    to a scanner is losing one probe's worth of fingerprint drip, which
    is a tiny cost vs. the >900k Googlebot fetches/window the trap
    absorbs otherwise.
    """
    if not user_agent:
        return None
    ua_lower = user_agent.lower()
    for token in ROBOTS_TXT_CRAWLER_UAS:
        if token in ua_lower:
            return token
    return None


async def _handle_robots_txt(
    request: web.Request,
    log_context: dict[str, object],
    crawler_token: str,
) -> web.Response:
    """Serve a static Disallow-all robots.txt with a long Cache-Control.

    Only invoked when the UA matched the crawler allowlist -- non-crawler
    UAs continue to hit the fingerprint/tarpit chain so scanner probes on
    /robots.txt still contribute to fingerprint capture.
    """
    method = request.method
    body = ROBOTS_TXT_BODY if method != "HEAD" else b""
    append_log({
        **log_context,
        "status": 200,
        "result": "robots-crawler",
        "robotsCrawler": crawler_token,
        "bytes": len(body),
    })
    return web.Response(
        status=200,
        body=body,
        headers={
            "Content-Type": "text/plain; charset=utf-8",
            "Cache-Control": f"public, max-age={ROBOTS_TXT_CACHE_MAX_AGE}",
        },
    )


async def _send_tarpit(
    request: web.Request,
    request_id: str,
    path: str,
    log_context: dict[str, object],
    query: str,
) -> web.StreamResponse:
    global _active_slow_drips
    ctx: dict[str, object] = {
        "log_context": log_context,
        "path": path,
        "query": query,
        "protocol": log_context.get("protocol", "https"),
        "host": log_context.get("host", ""),
        "send_body": request.method != "HEAD",
        "request_id": request_id,
    }

    # Terminal modules (first match wins).
    for mod in TARPIT_MODULES:
        if mod.terminal and mod.should_run(ctx):
            return await mod.run_terminal(request, ctx)

    # Redirect-chain continuation.
    if query:
        chain_id, hop = _parse_chain_params(query)
        if chain_id and MOD_REDIRECT_CHAIN_ENABLED:
            if hop < MOD_REDIRECT_CHAIN_MAX_HOPS:
                location = f"{path}?_hp_chain={chain_id}&_hp_hop={hop + 1}"
                append_log({
                    **log_context,
                    "status": 302,
                    "result": "tarpit-module",
                    "module": "redirect-chain",
                    "chainId": chain_id,
                    "hop": hop,
                })
                return web.Response(
                    status=302, body=b"redirecting\n",
                    headers={
                        "Location": location,
                        "Content-Type": "text/plain; charset=utf-8",
                        "Cache-Control": "no-store",
                    },
                )
            # Chain exhausted — fall through to drip.

    # Concurrency gate (simple int counter — safe in single-threaded event loop).
    if _active_slow_drips >= TARPIT_MAX_CONNECTIONS:
        append_log({**log_context, "status": 503, "result": "tarpit-capacity"})
        return web.Response(
            status=503, body=b"busy\n",
            headers={
                "Content-Type": "text/plain; charset=utf-8",
                "Cache-Control": "no-store",
            },
        )
    _active_slow_drips += 1
    try:
        # Augmenting modules contribute headers + log metadata.
        aug_meta: dict[str, object] = {}
        extra_headers: dict[str, str] = {}
        for mod in TARPIT_MODULES:
            if not mod.terminal and mod.should_run(ctx):
                mod_headers, mod_meta = mod.augment(request, ctx)
                extra_headers.update(mod_headers)
                if mod_meta:
                    aug_meta[mod.name] = mod_meta

        response = web.StreamResponse(status=200, headers={
            "Content-Type": "text/plain; charset=utf-8",
            "Cache-Control": "no-store",
            "X-Accel-Buffering": "no",
            **extra_headers,
        })
        chunks_sent = 0
        prepared = False
        try:
            await response.prepare(request)
            prepared = True

            log_entry: dict[str, object] = {
                **log_context,
                "status": 200,
                "result": "tarpit",
                "tarpitChunkBytes": TARPIT_CHUNK_BYTES,
                "tarpitIntervalMs": TARPIT_INTERVAL_MS,
                "tarpitSeconds": TARPIT_SECONDS,
            }
            if aug_meta:
                log_entry["modules"] = aug_meta
            append_log(log_entry)

            if request.method == "HEAD":
                return response

            if MOD_VARIABLE_DRIP_ENABLED:
                interval_ms = float(MOD_VARIABLE_DRIP_INITIAL_MS)
            else:
                interval_ms = float(TARPIT_INTERVAL_MS)

            deadline = (time.monotonic() + TARPIT_SECONDS) if TARPIT_SECONDS > 0 else None
            while deadline is None or time.monotonic() < deadline:
                await response.write(build_tarpit_chunk(request_id, path, chunks_sent))
                chunks_sent += 1
                await asyncio.sleep(interval_ms / 1000.0)
                if MOD_VARIABLE_DRIP_ENABLED:
                    interval_ms = min(interval_ms * 1.5, float(MOD_VARIABLE_DRIP_MAX_MS))
        except (ConnectionResetError, asyncio.CancelledError, aiohttp.ClientConnectionError):
            # `prepare()` raises the same family of errors as `write()` when
            # a scanner closes the socket before headers go out. Treat both
            # cases the same so the connection-reset path stays a logged
            # event, not an unhandled traceback.
            append_log({
                **log_context,
                "status": 200,
                "result": "tarpit-disconnect" if prepared else "tarpit-prepare-disconnect",
                "tarpitChunksSent": chunks_sent,
            })
        return response
    finally:
        _active_slow_drips -= 1


async def _send_env(
    request: web.Request,
    request_id: str,
    path: str,
    client_ip: str,
    host: str,
    user_agent: str,
    proto: str,
    log_context: dict[str, object],
    result_prefix: str = "",
    extra_log: "dict[str, object] | None" = None,
) -> web.Response:
    """Serve the bare `/.env` payload.

    `/.env` predates the CanaryTrap table and still has its own handler
    rather than an entry in it, so the `/@fs/` resolver reaches it here
    instead of through `_send_canary_trap`. `result_prefix` / `extra_log`
    mirror that function's signature for the same reason: a caller that
    arrived indirectly keeps its own tag and fields without a second copy
    of this body.
    """
    log_context = {**log_context, **(extra_log or {})}
    try:
        tracebit_response = await issue_credentials(request_id, client_ip, host, user_agent, path, proto)
    except aiohttp.ClientResponseError as exc:
        append_log({
            **log_context,
            "status": CREDENTIAL_FAILURE_STATUS,
            "result": f"{result_prefix}tracebit-http-error",
            "tracebitStatus": exc.status,
            "error": (exc.message or "")[:400],
        })
        return _credential_failure_response()
    except (aiohttp.ClientError, asyncio.TimeoutError, ValueError) as exc:
        append_log({
            **log_context, "status": CREDENTIAL_FAILURE_STATUS, "result": f"{result_prefix}tracebit-error",
            "error": _exc_detail(exc)[:400],
        })
        return _credential_failure_response()

    payload = format_env_payload(tracebit_response).encode("utf-8")
    append_log({
        **log_context, "status": 200, "result": f"{result_prefix}issued",
        "types": [key for key, value in tracebit_response.items() if value],
    })
    return web.Response(
        status=200, body=payload,
        headers={"Content-Type": "text/plain; charset=utf-8"},
    )




# ============================================================================
# Apache mod_cgi path-traversal RCE (CVE-2021-41773 / CVE-2021-42013)
# ============================================================================
#
# The 2021 Apache 2.4.49/2.4.50 traversal bugs are still one of the most
# heavily probed remote-code paths on the internet, and the probe shape is
# unusually informative because the exploit is split across two requests
# with *different* meanings:
#
#   1. `GET /cgi-bin/.%2e/.%2e/.%2e/.%2e/bin/sh` — Apache resolves the
#      encoded traversal, lands on `/bin/sh`, and executes it through
#      mod_cgi. With no request body the shell reads nothing from stdin
#      and exits without emitting CGI headers, so a genuinely vulnerable
#      server answers **500** ("End of script output before headers").
#      A patched server answers 403/404. The 500 *is* the positive
#      vulnerability signal — it is what the scanner is testing for.
#   2. `POST` to the same target with a body of
#      `echo Content-Type: text/plain; echo; <command>` — now the shell
#      has stdin, emits the header line the scanner injected, and returns
#      the command output as **200**. This request carries the attacker's
#      actual command, which is the thing worth capturing.
#
# Answering 404 to both collapses that structure: the scanner concludes
# "patched" at step 1 and never sends step 2, so the command — and the
# stage-2 dropper URL inside it — is never observed. Reproducing the
# 500-then-200 asymmetry is therefore not cosmetic; it is the only way to
# reach the request that carries payload.
#
# Matching runs on the RAW request target, not the normalised path,
# because `normalize_path` resolves the traversal *for* us: by the time
# dispatch sees it, `/cgi-bin/.%2e/.%2e/bin/sh` has already collapsed to
# `/bin/sh` and every trace of the CVE shape is gone from `path`. The
# handler therefore takes `raw_target` and logs it verbatim.
#
# Scope is deliberately narrow: only traversals whose *target* is a shell
# interpreter reach this handler. The same CVE is also used to read files
# (`.../etc/passwd`, `.../root/.aws/credentials`), and those keep flowing
# through normalisation into the canary trap table, which already answers
# them with credential material.
CGI_TRAVERSAL_RCE_ENABLED = _env_bool("HONEYPOT_CGI_TRAVERSAL_RCE_ENABLED")

# Encoded-dot traversal segment. Covers the CVE-2021-41773 single-encoded
# form (`.%2e`, `%2e%2e`) and the CVE-2021-42013 double-encoded bypass
# (`.%252e`, `%252e%252e`) that defeated the 2.4.50 fix. Case-insensitive
# because scanners mix `%2E` and `%2e`.
_CGI_TRAVERSAL_SEGMENT = r"(?:\.|%2e|%252e){1,2}(?:%2f|%252f|/)"

# Interpreters worth executing. `sh`/`bash` are what the public PoCs use;
# the others show up in copies of those PoCs adapted for busybox images.
_CGI_TRAVERSAL_TARGETS = ("bin/sh", "bin/bash", "bin/dash", "bin/busybox")

_CGI_TRAVERSAL_RE = re.compile(
    r"^/[^?]*?/"                       # any prefix dir (`/cgi-bin/`, `/icons/`, …)
    r"(?:" + _CGI_TRAVERSAL_SEGMENT + r"){2,}"   # >=2 traversal segments
    r"(?:usr/)?(" + "|".join(re.escape(t) for t in _CGI_TRAVERSAL_TARGETS) + r")/?$",
    re.IGNORECASE,
)

# The canonical mod_cgi exploitation preamble. The scanner has to inject a
# CGI header block before its command, so the body almost always starts
# `echo Content-Type: text/plain; echo; <command>`. Stripping it leaves
# the command the operator actually wanted to run.
_CGI_PREAMBLE_RE = re.compile(
    r"^\s*echo\s+content-type\s*:[^;\n]*;\s*echo\s*;?\s*",
    re.IGNORECASE,
)


def is_cgi_traversal_rce_target(raw_target: str) -> bool:
    """True when the raw request target is an encoded traversal ending at a
    shell interpreter — the mod_cgi RCE shape, not the file-read shape."""
    if not raw_target:
        return False
    target = raw_target.split("?", 1)[0]
    return bool(_CGI_TRAVERSAL_RE.match(target))


def extract_cgi_traversal_command(request_body: bytes) -> str:
    """Lift the injected shell command out of a mod_cgi exploitation body.

    Returns "" when the body is empty or carries no command after the CGI
    header preamble — the caller treats that as a bare probe.
    """
    if not request_body:
        return ""
    text = request_body[:WEBSHELL_BODY_DECODE_LIMIT].decode("utf-8", errors="replace")
    stripped = _CGI_PREAMBLE_RE.sub("", text, count=1)
    return stripped.strip()


async def _handle_cgi_traversal_rce(
    request: web.Request,
    log_context: dict[str, object],
    raw_target: str,
    request_body: bytes,
) -> web.Response:
    """Answer the mod_cgi traversal the way a vulnerable 2.4.49 would.

    No body -> 500 with Apache's stock "End of script output before
    headers" page, which is the positive vulnerability signal the probe
    is looking for. Body present -> parse the command out of the CGI
    preamble, log it with any stage-2 URLs, and return simulated output
    as 200 so the operator sends a second, more revealing command.
    """
    command = extract_cgi_traversal_command(request_body)
    body_preview = ""
    if request_body:
        body_preview = request_body[:WEBSHELL_BODY_DECODE_LIMIT].decode("utf-8", errors="replace")

    log_entry: dict[str, object] = {
        **log_context,
        # `path` has already been normalised down to `/bin/sh`; the CVE
        # signature only survives here.
        "cgiTraversalRawTarget": raw_target[:512],
        "cgiTraversalHasCommand": bool(command),
    }
    if command:
        log_entry["cgiTraversalCommand"] = command[:1024]
        payload_urls = _extract_payload_urls(command, unquote(body_preview))
        downloaders = _extract_downloaders(command, unquote(body_preview))
        if payload_urls:
            log_entry["cgiTraversalPayloadUrls"] = payload_urls
        if downloaders:
            log_entry["cgiTraversalDownloaders"] = downloaders
    if body_preview:
        log_entry["cgiTraversalBodyPreview"] = body_preview[:512]

    if not command:
        append_log({**log_entry, "status": 500, "result": "cgi-traversal-rce-probe"})
        return web.Response(
            status=500,
            body=(
                b"<!DOCTYPE HTML PUBLIC \"-//IETF//DTD HTML 2.0//EN\">\n"
                b"<html><head>\n<title>500 Internal Server Error</title>\n"
                b"</head><body>\n<h1>Internal Server Error</h1>\n"
                b"<p>The server encountered an internal error or\n"
                b"misconfiguration and was unable to complete\nyour request.</p>\n"
                b"<hr>\n<address>Apache/2.4.49 (Unix) Server at localhost Port 80</address>\n"
                b"</body></html>\n"
            ),
            headers={"Content-Type": "text/html; charset=iso-8859-1"},
        )

    output = simulate_command_output(command)
    append_log({**log_entry, "status": 200, "result": "cgi-traversal-rce-command"})
    return web.Response(
        status=200,
        body=output.encode("utf-8", errors="replace"),
        headers={"Content-Type": "text/plain; charset=utf-8"},
    )

async def handle(request: web.Request) -> web.StreamResponse:
    method = request.method
    request_id = str(uuid.uuid4())

    if method not in ("GET", "HEAD", "POST"):
        # The response is unchanged — what is new is that the rejection
        # leaves a row. This gate sits in front of every trap, so a method
        # it turns away reaches no handler and, until now, produced no log
        # line anywhere: that traffic was not merely unhandled, it was
        # unmeasurable. It matters because some of the CVEs these traps
        # imitate are delivered by PUT — CVE-2021-36260 ships its command
        # in a `PUT /SDK/webLanguage` body — so the blind spot is not
        # evenly spread over noise, it points at exactly the surfaces the
        # traps exist to watch. Logging first makes the size of the gap
        # answerable; whether to widen the gate is a separate decision and
        # should be made from that number rather than from a guess.
        body = b"method not allowed\n"
        append_log({
            **_log_context_from_request(request, request_id, 0, ""),
            "status": 405,
            "result": "method-not-allowed",
            "bytes": len(body),
        })
        return web.Response(status=405, body=body)

    # Some exploitation clients send meaningful bodies on GET (notably
    # PHPUnit eval-stdin probes). Read a capped body for GET/POST, but only
    # stamp bodySha256 when bytes were actually present so ordinary GET rows
    # do not all collapse onto the empty-body hash.
    read_body = method in {"GET", "POST"}

    body_bytes_read = 0
    body_sha256 = ""
    request_body = b""
    if read_body:
        # Cap body size off the wire. aiohttp returns exactly N bytes or fewer;
        # the scanner's Content-Length is advisory only, not trusted.
        try:
            request_body = await request.content.read(WEBSHELL_BODY_READ_LIMIT)
        except (ConnectionResetError, asyncio.CancelledError, aiohttp.ClientConnectionError):
            # Scanners that send a Content-Length header and then drop the
            # socket before the body arrives are extremely common. Without
            # this handler aiohttp logs a 30-line stack trace per occurrence;
            # the disconnect itself isn't actionable, so close out quietly.
            return web.Response(status=499, body=b"")
        body_bytes_read = len(request_body)
        if body_bytes_read:
            body_sha256 = hashlib.sha256(request_body).hexdigest()

    log_context = _log_context_from_request(request, request_id, body_bytes_read, body_sha256)

    # Stamped before any dispatch so the finding rides on whichever
    # trap's line ends up being written, rather than only on the
    # not-handled ones. Purely additive to the log: no branch below
    # reads these fields, so a request carrying a credential is answered
    # exactly as it would have been without one.
    if CANARY_ECHO_ENABLED:
        echo = canary_echo_scan(
            str(log_context["rawTarget"]),
            log_context.get("headers") if isinstance(log_context.get("headers"), dict) else None,
            request_body,
        )
        if echo:
            log_context.update(echo)

    path = str(log_context["path"])
    query_string = str(log_context["query"])
    client_ip = str(log_context["clientIp"])
    host = str(log_context["host"])
    user_agent = str(log_context["userAgent"])
    proto = str(log_context["protocol"])

    # Runs ahead of every path-based matcher because it is the only branch
    # that needs the request target *before* normalisation collapsed the
    # encoded traversal — by the time `path` exists the CVE shape is gone.
    if CGI_TRAVERSAL_RCE_ENABLED:
        raw_target = str(log_context["rawTarget"])
        if is_cgi_traversal_rce_target(raw_target):
            return await _handle_cgi_traversal_rce(
                request, log_context, raw_target, request_body,
            )

    # WordPress serves every REST route at two addresses, and only one of
    # them is a path. Resolving the `?rest_route=` form back to its
    # canonical `/wp-json/...` shape here — ahead of every path matcher —
    # is what makes the WP-REST traps reachable by both, rather than each
    # trap having to learn the alias separately. `log_context` keeps the
    # request as it arrived; only dispatch sees the rewrite, and the
    # rewrite itself is logged so alias use stays countable.
    if WP_REST_ROUTE_ALIAS_ENABLED:
        aliased = wp_rest_route_alias(path, query_string)
        if aliased is not None and aliased != path:
            log_context["wpRestRouteAliasFrom"] = path[:200]
            log_context["wpRestRoutePath"] = aliased[:200]
            path = aliased

    if is_webshell_path(path):
        return await _handle_webshell(request, log_context, path, query_string, request_body)

    if is_file_upload_path(path):
        return await _handle_file_upload(request, log_context, path, request_body)

    if is_llm_endpoint_path(path):
        return await _handle_llm_endpoint(request, log_context, path, request_body)

    # Canary-backed, so a keyless deployment keeps the 404 rather than
    # serving a registry with empty credential slots.
    if API_KEY and is_litellm_admin_path(path):
        return await _handle_litellm_admin(request, log_context, path, request_body)

    if is_mcp_server_endpoint_path(path):
        return await _handle_mcp_server_endpoint(
            request, log_context, request_id, path,
            client_ip, host, user_agent, proto, request_body,
        )

    if is_openapi_swagger_path(path):
        return await _handle_openapi_swagger(request, log_context, request_id, path)

    if is_graphql_path(path):
        return await _handle_graphql(
            request, log_context, request_id, path, query_string, request_body,
        )

    if is_sonicwall_path(path):
        return await _handle_sonicwall(request, log_context, path, request_body)

    if is_cisco_webvpn_path(path) or is_cisco_anyconnect_config_auth(path, request_body):
        return await _handle_cisco_webvpn(request, log_context, path, request_body)

    if is_ivanti_vpn_path(path):
        return await _handle_ivanti_vpn(request, log_context, path, request_body)

    if is_aspera_faspex_path(path):
        return await _handle_aspera_faspex(request, log_context, path, request_body)

    if is_fortigate_vpn_path(path):
        return await _handle_fortigate_vpn(request, log_context, path, request_body)

    if is_globalprotect_path(path):
        return await _handle_globalprotect(request, log_context, path, request_body)

    if is_sophos_vpn_path(path):
        return await _handle_sophos_vpn(request, log_context, path, request_body)

    if is_barracuda_vpn_path(path):
        return await _handle_barracuda_vpn(request, log_context, path, request_body)

    # Check Point. The portal and management surfaces need no issuing
    # key; the read primitive resolves through the canary table, which
    # already 404s itself on a keyless deployment — so the branch runs
    # either way and the read simply finds nothing to hand out.
    checkpoint = checkpoint_surface(path)
    if checkpoint:
        return await _handle_checkpoint(
            request, log_context, path, request_body, checkpoint,
            request_id, client_ip, user_agent, proto,
        )

    # Tomcat `/..;/env.*` path-normalization bypass. Match before F5
    # BIG-IP so the bypass-shape env-file harvest goes to the dedicated
    # handler; `is_tomcat_path_bypass_path` already excludes `/tmui/`
    # paths (which the F5 handler owns).
    if API_KEY and is_tomcat_path_bypass_path(path):
        return await _handle_tomcat_path_bypass(
            request, log_context, path, query_string,
        )

    if is_f5_bigip_path(path):
        return await _handle_f5_bigip(request, log_context, path, request_body)

    if is_docker_daemon_path(path):
        return await _handle_docker_daemon(request, log_context, path, request_body)

    if is_docker_registry_path(path):
        return await _handle_docker_registry(request, log_context, path, request_body)

    if is_citrix_gateway_path(path):
        return await _handle_citrix_gateway(request, log_context, path, request_body)

    if is_rdweb_path(path):
        return await _handle_rdweb(request, log_context, path, request_body)

    if (
        is_threecx_ui_path(path)
        or is_threecx_login_path(path)
        or is_threecx_api_path(path)
    ):
        return await _handle_threecx(request, log_context, path, request_body)

    if is_exchange_path(path):
        return await _handle_exchange(request, log_context, path, query_string, request_body)

    if is_hikvision_path(path):
        return await _handle_hikvision(request, log_context, path, query_string, request_body)

    if is_onvif_path(path):
        return await _handle_onvif(request, log_context, path, request_body)

    if is_hnap1_path(path):
        return await _handle_hnap1(request, log_context, path, query_string, request_body)

    if is_soho_router_path(path):
        return await _handle_soho_router(
            request, log_context, path, query_string, request_body
        )

    if is_server_status_path(path):
        return await _handle_server_status(request, log_context, path, query_string)

    # After every exact-path trap above, so a more specific handler
    # (mod_status, pprof, the actuator endpoint table) always claims its
    # own path first and this only sees what would otherwise 404.
    _obs_kind = observability_kind(path)
    if _obs_kind is not None:
        return await _handle_observability(request, log_context, path, _obs_kind)

    if is_geoserver_path(path):
        return await _handle_geoserver(request, log_context, path, request_body)

    if is_liferay_path(path):
        return await _handle_liferay(request, log_context, path, query_string, request_body)

    if is_gravity_smtp_path(path):
        return await _handle_gravity_smtp(request, log_context, path, query_string)

    if is_telescope_path(path):
        return await _handle_telescope(request, log_context, path, query_string)

    if API_KEY and is_oidc_discovery_path(path):
        return await _handle_oidc_discovery(request, log_context, path)

    # Gated on the same condition as the document that advertises them,
    # so the IdP surface appears and disappears as a whole. A deployment
    # that 404s the discovery document must not answer its endpoints —
    # that inconsistency is exactly what this trap exists to remove.
    if API_KEY:
        _oidc_endpoint = is_oidc_endpoint_path(path)
        if _oidc_endpoint is not None:
            return await _handle_oidc_endpoint(
                request, log_context, path, query_string, request_body,
                _oidc_endpoint,
            )

    if is_phpmyadmin_path(path):
        return await _handle_phpmyadmin(request, log_context, path, request_body)

    if is_adminer_path(path):
        return await _handle_adminer(request, log_context, path, request_body)

    if is_whm_path(path):
        return await _handle_whm(request, log_context, path, request_body)

    if is_ds_store_path(path):
        return await _handle_ds_store(request, log_context, path)

    if is_weblogic_console_path(path):
        return await _handle_weblogic_console(request, log_context, path, request_body)

    if is_coldfusion_path(path):
        return await _handle_coldfusion(request, log_context, path, request_body)

    if is_confluence_path(path):
        return await _handle_confluence(request, log_context, path, request_body)

    if is_sap_metadatauploader_path(path):
        return await _handle_sap_metadatauploader(request, log_context, path, request_body)

    if is_drupal_path(path):
        return await _handle_drupal(request, log_context, path, query_string, request_body)

    if is_joomla4_config_path(path):
        return await _handle_joomla4_config(
            request, log_context, path, query_string,
        )

    if API_KEY and is_spring_gateway_path(path):
        return await _handle_spring_gateway(
            request, log_context, path, query_string, request_body,
        )

    if is_nextjs_path(path):
        return await _handle_nextjs(request, log_context, path, query_string, request_body)

    if is_cmd_injection_path(path):
        return await _handle_cmd_injection(
            request, log_context, path, query_string, request_body, request_id,
        )

    if is_phpunit_eval_path(path):
        return await _handle_phpunit_eval(request, log_context, path, request_body)

    if is_body_rce_request(path, query_string, request_body):
        return await _handle_body_rce(request, log_context, path, query_string, request_body)

    # Bare GET/HEAD against the canonical PHP-CGI paths — falls through
    # to here only when no body-RCE exploit query/body matched above,
    # so the CVE-2024-4577 spray scanners that POST the exploit on
    # every target still land in `_handle_body_rce`. Gated scanners
    # that probe `/cgi-bin/php` for liveness first get a 200 with the
    # Windows + Apache + PHP-CGI fingerprint they're checking for.
    if is_php_cgi_liveness_path(path):
        return await _handle_php_cgi_liveness(request, log_context, path)

    # Ahead of the `/wp-admin/*` redirect so the install wizard serves
    # its own multi-step flow instead of being bounced to the login page.
    if is_wp_setup_config_path(path):
        return await _handle_wp_setup_config(
            request, log_context, path, query_string, request_body,
        )

    # Ahead of the generic web-app form trap: `/auth/callback` and
    # `/api/auth/signin` would otherwise be swallowed by its login-path
    # list and answered with a generic form, losing the CSRF exchange
    # that is the whole point of this surface.
    if is_nextauth_path(path):
        return await _handle_nextauth(
            request, log_context, path, query_string, request_body,
        )

    if is_wp_login_path(path):
        return await _handle_wp_login(request, log_context, path, request_body)

    if is_wp_admin_path(path):
        return await _handle_wp_admin_redirect(request, log_context, path)

    if is_wp_user_enum_path(path):
        return await _handle_wp_user_enum(request, log_context, path)

    if is_wp_batch_path(path):
        return await _handle_wp_batch(request, log_context, path, request_body)

    # After user-enum and batch: those two own their routes, and the
    # index only fills in what nothing else answers.
    if is_wp_rest_index_path(path):
        return await _handle_wp_rest_index(request, log_context, path)

    if is_wp_xmlrpc_path(path):
        return await _handle_wp_xmlrpc(request, log_context, path, request_body)

    if is_wp_wlwmanifest_path(path):
        return await _handle_wp_wlwmanifest(request, log_context, path)

    if is_git_dotfile_path(path):
        return await _handle_git_dotfile(request, log_context, path)

    # Web-app form responder runs before the tarpit/fingerprint check so
    # that paths in both lists (e.g. `/`) stay with tarpit; the form trap
    # only matches its own concrete path set, never `/`.
    if is_webapp_form_path(path):
        return await _handle_webapp_form(request, log_context, path, request_body)

    # /robots.txt from a verified crawler UA gets a stable Disallow-all
    # response with a long Cache-Control, so Googlebot / YandexBot /
    # Bingbot / etc. stop refetch-looping. Non-crawler UAs (including
    # any scanner that hasn't spoofed the UA) fall through to the
    # tarpit/fingerprint chain so the probe still contributes to
    # fingerprint capture.
    if ROBOTS_TXT_STABLE_ENABLED and path.lower() == "/robots.txt":
        crawler_token = _match_robots_crawler_ua(user_agent)
        if crawler_token is not None:
            return await _handle_robots_txt(request, log_context, crawler_token)

    # `/@fs/` resolution runs ahead of the tarpit on purpose. Most of what
    # arrives on this prefix is `.env`-suffixed, which `is_tarpit_path`
    # would otherwise claim — and the generic drip issues no canary, so
    # taking the tarpit here would trade a replay-detectable credential
    # for a held connection on the one surface that also tells us the
    # attacker's assumed filesystem layout. With the trap disabled (or no
    # API key) the branch falls through and those paths tarpit as before.
    if API_KEY and VITE_FS_ENABLED:
        vite_fs = resolve_vite_fs(path)
        if vite_fs is not None:
            return await _send_vite_fs(
                request, vite_fs, request_id, path,
                client_ip, host, user_agent, proto, log_context,
            )

    # Ahead of the tarpit for the same reason `/@fs/` is: the listing
    # steps are what make the credential step reachable, and a drip on
    # `/latest/meta-data/` would break the chain before the client ever
    # learns the role name.
    if API_KEY and CLOUD_IMDS_ENABLED:
        imds = resolve_cloud_imds(path)
        if imds is not None:
            return await _send_cloud_imds(
                request, imds, request_id, path,
                client_ip, host, user_agent, proto, log_context,
            )

    # Ahead of the tarpit for the same reason the metadata tree is: the
    # listing step is what makes the payload step reachable, and dripping
    # `/_debugbar/open` would break the chain before the client ever
    # learns a stored-request id.
    if API_KEY and LARAVEL_DEBUGBAR_ENABLED:
        dbg = resolve_laravel_debugbar(path, query_string, host)
        if dbg is not None:
            return await _send_laravel_debugbar(
                request, dbg, request_id, path,
                client_ip, host, user_agent, proto, log_context,
            )

    # Directly after the metadata tree, and ahead of the tarpit, for the
    # same reason: this is the indirect way into that tree, and the
    # listing steps are what make the credential step reachable. The
    # branch only fires when a parameter names a metadata host, so an
    # ordinary request to one of these entry paths still falls through.
    if API_KEY and SSRF_RELAY_ENABLED and CLOUD_IMDS_ENABLED:
        relay = resolve_ssrf_relay(path, query_string)
        if relay is not None:
            return await _send_ssrf_relay(
                request, relay, request_id, path,
                client_ip, host, user_agent, proto, log_context,
            )

    if TARPIT_ENABLED and (is_tarpit_path(path) or is_fingerprint_path(path)):
        return await _send_tarpit(request, request_id, path, log_context, query_string)

    if FAKE_GIT_ENABLED and API_KEY:
        git_key = extract_git_path(path)
        if git_key is not None:
            return await _send_fake_git(
                request, request_id, path, git_key,
                client_ip, host, user_agent, proto, log_context,
            )

    # After fake-git deliberately: a path carrying both segments
    # (`/.git/config/.svn/entries`) is a scanner appending the svn
    # dictionary to every git path it tried, and stays classified as a
    # fake-git miss rather than being reclassified as svn traffic.
    if FAKE_SVN_ENABLED and API_KEY:
        svn_key = extract_svn_path(path)
        if svn_key is not None:
            return await _send_fake_svn(
                request, request_id, path, svn_key,
                client_ip, host, user_agent, proto, log_context,
            )

    if API_KEY:
        trap, trap_walk_depth = resolve_canary_trap(path)
        if trap is not None:
            return await _send_canary_trap(
                request, trap, request_id, path, client_ip, host, user_agent, proto, log_context,
                # Only stamped when the walk actually moved, so the field's
                # presence is exactly the "this arrived nested under an
                # app-layout directory" signal and unnested traffic keeps
                # its existing log shape.
                extra_log=(
                    {"trapWalkDepth": trap_walk_depth} if trap_walk_depth else None
                ),
            )

    # Webhook deliveries. Late in the chain because the match is a path
    # shape rather than a known address: anything above that wants
    # `/api/...` for itself has already taken it. Needs no Tracebit key —
    # the response contains no credential — so it stays useful on a
    # keyless deployment, where it is one of the few traps that does.
    if WEBHOOK_RECEIVER_ENABLED and is_webhook_receiver_path(path):
        return await _handle_webhook_receiver(request, log_context, path, request_body)

    # Backup-archive pattern trap runs after exact-path canary lookup so
    # that explicit entries (e.g. `/backup.sql` -> sql-dump trap) keep
    # their dedicated renderer. Anything matching the broader
    # `<base>.<ext>` shape (including IP-octet / date synthesis stems)
    # lands here.
    if API_KEY and BACKUP_ARCHIVE_ENABLED and is_backup_archive_path(path):
        return await _send_backup_archive(
            request, request_id, path, client_ip, host, user_agent, proto, log_context,
        )

    # Shell-jacking sweep gate. Runs last on purpose: everything above has
    # already claimed its own paths, so whatever reaches here is a root-level
    # `*.php` name no trap wanted — exactly the shape a shell-jacking sweep
    # walks. Sources under the distinct-name threshold fall through to the
    # same 404 below and cannot tell the gate exists.
    if WEBSHELL_ENABLED and WEBSHELL_SWEEP_ENABLED and is_webshell_sweep_candidate(path):
        distinct = webshell_sweep_observe(client_ip, path)
        if distinct >= WEBSHELL_SWEEP_MIN_DISTINCT:
            return await _handle_webshell(
                request, {**log_context, "webshellSweepDistinct": distinct},
                path, query_string, request_body,
            )
        append_log({
            **log_context, "status": 404, "result": "webshell-sweep-observed",
            "webshellSweepDistinct": distinct,
        })
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    if path != "/.env" or not API_KEY:
        append_log({**log_context, "status": 404, "result": "not-handled"})
        return web.Response(
            status=404, body=b"not found\n",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )

    return await _send_env(
        request, request_id, path, client_ip, host, user_agent, proto, log_context,
    )


async def _close_http_session(app: web.Application) -> None:
    global _http_session
    if _http_session is not None and not _http_session.closed:
        await _http_session.close()
    _http_session = None


def create_app() -> web.Application:
    app = web.Application()
    app.router.add_route("*", "/{tail:.*}", handle)
    app.on_cleanup.append(_close_http_session)
    return app


def main() -> int:
    active = []
    if API_KEY:
        active.append("env-canary")
        if FAKE_GIT_ENABLED:
            active.append("fake-git")
        if FAKE_SVN_ENABLED:
            active.append("fake-svn")
        if CANARY_TRAPS_ENABLED:
            active.append("canary-file-traps")
        if CLOUD_IMDS_ENABLED:
            active.append("cloud-imds")
            if SSRF_RELAY_ENABLED:
                active.append("ssrf-relay")
        if BACKUP_ARCHIVE_ENABLED:
            active.append("backup-archive")
    else:
        print(
            "flux: TRACEBIT_API_KEY unset — /.env, /.git/*, and canary file traps disabled (all 404)",
            file=sys.stderr,
        )
    if TARPIT_ENABLED:
        active.append("tarpit")
    if WEBSHELL_ENABLED:
        active.append("webshell")
        if WEBSHELL_SWEEP_ENABLED:
            active.append("webshell-sweep")
    if FILE_UPLOAD_ENABLED:
        active.append("file-upload")
    if LITELLM_ADMIN_ENABLED and API_KEY:
        active.append("litellm-admin")
    if LLM_ENDPOINT_ENABLED:
        active.append("llm-endpoint")
    if MCP_SERVER_ENABLED:
        active.append("mcp-server-endpoint")
    if SONICWALL_ENABLED:
        active.append("sonicwall-ssl-vpn")
    if CISCO_WEBVPN_ENABLED:
        active.append("cisco-webvpn")
    if IVANTI_VPN_ENABLED:
        active.append("ivanti-vpn")
    if ASPERA_FASPEX_ENABLED:
        active.append("aspera-faspex")
    if FORTIGATE_VPN_ENABLED:
        active.append("fortigate-vpn")
    if GLOBALPROTECT_ENABLED:
        active.append("globalprotect")
    if SOPHOS_VPN_ENABLED:
        active.append("sophos-vpn")
    if BARRACUDA_VPN_ENABLED:
        active.append("barracuda-vpn")
    if CHECKPOINT_ENABLED:
        active.append("checkpoint")
    if F5_BIGIP_ENABLED:
        active.append("f5-bigip")
    if DOCKER_REGISTRY_ENABLED:
        active.append("docker-registry")
    if CITRIX_GATEWAY_ENABLED:
        active.append("citrix-gateway")
    if RDWEB_ENABLED:
        active.append("rdweb")
    if EXCHANGE_ENABLED:
        active.append("exchange")
    if HIKVISION_ENABLED:
        active.append("hikvision")
    if ONVIF_ENABLED:
        active.append("onvif")
    if HNAP1_ENABLED:
        active.append("hnap1-router")
    if SERVER_STATUS_ENABLED:
        active.append("server-status")
    if OBSERVABILITY_ENABLED:
        active.append("observability")
    if GEOSERVER_ENABLED:
        active.append("geoserver")
    if COLDFUSION_ENABLED:
        active.append("coldfusion")
    if CONFLUENCE_ENABLED:
        active.append("confluence")
    if SAP_METADATAUPLOADER_ENABLED:
        active.append("sap-metadatauploader")
    if DRUPAL_ENABLED:
        active.append("drupal")
    if JOOMLA4_CONFIG_ENABLED:
        active.append("joomla4-config")
    if TOMCAT_PATH_BYPASS_ENABLED and API_KEY:
        active.append("tomcat-path-bypass")
    if SPRING_GATEWAY_ENABLED and API_KEY:
        active.append("spring-gateway")
    if NEXTJS_ENABLED:
        active.append("nextjs")
    if CMD_INJECTION_ENABLED:
        active.append("cmd-injection")
    if PHP_CGI_LIVENESS_ENABLED:
        active.append("php-cgi-liveness")
    if WEBAPP_FORM_ENABLED:
        active.append("webapp-form")
    if NEXTAUTH_ENABLED:
        active.append("nextauth")
    if WP_LOGIN_ENABLED:
        active.append("wp-login")
    if WP_USER_ENUM_ENABLED:
        active.append("wp-user-enum")
    if WP_REST_INDEX_ENABLED:
        active.append("wp-rest-index")
    if WP_XMLRPC_ENABLED:
        active.append("wp-xmlrpc")
    if WP_WLW_MANIFEST_ENABLED:
        active.append("wp-wlwmanifest")
    if GIT_DOTFILES_ENABLED:
        active.append("git-dotfiles")
    if GRAVITY_SMTP_ENABLED:
        active.append("gravity-smtp")
    if TELESCOPE_ENABLED:
        active.append("telescope")
    print(
        f"flux: listening on 127.0.0.1:18081 (aiohttp), active traps: {', '.join(active) or 'none'}",
        file=sys.stderr,
    )

    app = create_app()
    web.run_app(app, host="127.0.0.1", port=18081, print=None, access_log=None)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        sys.exit(0)
